/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200630-9","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"文教委員会","time":"午前１０時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","topics":[{"id":"topic-01","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今、第四日野小学校の話がありましたが、学級規模としては必ずしも大きくないと思うのですけれど、今回２４学級を想定されているということで、ここに限らず改築時の計画、学級数の設定の考え方について伺いたいと思います。具体的に何の要素などに基づいて決めているのか、全て教えてもらえるとありがたいです。","respondent":"小林学校施設担当課長","answer":"学級数の設定の仕方ですが、就学人口などを見据えて、将来の計画をしております。それと、近隣でのマンションなどの建設も視野に入れて、学級数を最大限とれるように工夫しています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"それと併せて、具体的に資料に基づいて教えてもらいたい点が２点あります。もう一つは第四日野小学校ですけれども、この図面ですが、特別支援学級の教室の場所は１階になっているのですけれど、いわゆる普通教室と随分離れていると思うのですが、なぜこういうところにあるのか伺いたいと思います。","respondent":"篠田学務課長、小林学校施設担当課長","answer":"私から、就学人口の予測についてご説明いたします。基本的に一つは住民登録、住民基本台帳を見ますと０歳からずっと入っていますので、この先入学までというのは、その数字である程度参考にできるということがあります。第四日野小学校につきまして、１階に特別支援学級があって、普通教室と離れているというお話でしたが、こちらについては、特別支援学級でもお子様の状況はいろいろありまして、普通教室から離してほしいという学校からの要望。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"といいますのは、インクルーシブ教育ですとか障害理解の観点からも、ふだんから障害のある子もない子も一緒に、見えるところで学習していくというのが一番の理解につながるのではないかということで、現状の配置に対して、できれば改善してほしいという声も一方で伺うので、その辺はケースバイケースではあると思うのですが、これから具体化していくと思うのですけれども。","respondent":"小林学校施設担当課長","answer":"学級数のお話ですが、今現在できる限りのところで、支障がないものと考えております。それと特別支援教室につきましては、発達障害の症状はいろいろとありまして、基本的には委員がおっしゃるとおり、普通教室に近いところを望むケースが多いと思います。","id":"exchange-003"},{"speaker":"せお委員","kind":"質問","question":"今のお話ですけれど、そもそも特別支援学級ですか。違うと思うのですけれど。第四日野小学校は１枚目のところで計画学級数、特支（通級１室）となっているのですけれど、これはどういうことですか。","respondent":"小林学校施設担当課長","answer":"固定級というのは、普通教室に在籍しないで特別支援学級に直接行って、そちらで授業を行って帰っていくという、この二つの使い分けをここで書いております。","id":"exchange-004"},{"speaker":"せお委員","kind":"質問","question":"言い方なのですが、品川区では特別支援学級と特別支援教室の通級は違うと思うのです。ということは、第四日野小学校にできるのは、結局、通級１室ができるということでよろしいのですか。","respondent":"矢部教育総合支援センター長","answer":"特別支援教室というのは、例えば３年１組にいるお子さんが、２時間程度、１週間に１回ぐらい別の教室に行って、ソーシャルスキルの勉強とか、友だちとのおつき合いの勉強とか、若干の学習もやりますけれども、比較的短い時間を取り出して、そこで学習するというスタイル。","id":"exchange-005"},{"speaker":"せお委員","kind":"質問","question":"位置もそうなのですけれど、特別支援教室の場合、この１部屋だけを使うのかということがありまして、やはり私としては、今後インクルーシブ教育に向けてどんどん普通学級に在籍していただいて、授業によって分けたほうがいいというときは、そういうふうにほかの教室を使っていくという形が理想だと思うのですが、この第四日野小学校でほかに使える部屋とかがあれば教えてください。","respondent":"小林学校施設担当課長","answer":"第四日野小学校はこれから設計をまた進めていくのですけれども、例えば多目的教室とか、これは学校の考え方によって変わってくると思いますが、そういう部屋を使ったりということは可能だと思います。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問","question":"もう１点だけ、すみません。第四日野小学校の計画概要、コンセプトの２番に四日野ルームというものが書かれているのですけれど、同学年のつながりとか異学年交流とかという、具体的に何か決まっていることがあれば教えてください。どのような交流をするのか。","respondent":"小林学校施設担当課長","answer":"具体的に決まっているものではございませんけれども、委員のお話のとおり他学年、ここは少し大きい部屋にしておりますので、学年を飛び越えた交流の場をつくったり、ランチをしたり、いろいろなことで使われると思います。これは学校が今後計画していくと思います。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"それから第四日野小学校ですけれども、工事によって既存では南向きの校舎が、今度は運動場が北東になるということで、日影の関係あるいは校庭に対してどういう時期にどういう影がというような、当然計算されていると思うのですけれど、概略を教えていただければと思います。","respondent":"小林学校施設担当課長","answer":"現在はかむろ坂通りのほうに校舎があって、ちょっと閉鎖的で、グラウンドが見えないものですから、そういうところも含めて近隣に与える日影の影響を少なくするため、敷地条件、立地条件、方位とかいろいろあるのですけれども。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"工期は影響ないということでよかったです。日影の関係ですけれども、学校建築が昔から南側校舎と決まっていたのは、子どものための発想だったと思うのですね。今は違うのですか。子どもが校庭で日に当たって育つようにというのは第一義的なものでなく、近隣に影を落とさないようにというのが校舎の配置計画の第一になってくるものなのですか。その考え方を教えてください。","respondent":"小林学校施設担当課長","answer":"北側に持っていくと、当然近隣の敷地が日影になってきますので、説明会でもトラブルになる要素になります。苦渋の選択をして、南側のほうに持ってきたです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"確認","question":"それと、先ほども出ていました支援級の関係ですけれども、この表の見方を教えてください。計画学級数と書いてある１８とか２４というのは、普通学級の数字ということでしょうか。固定級と書いてあるのが、いわゆるそこに在籍する子どもたちが通う特別支援学級で、通級というのは子どもたちが各クラスに在籍して、必要な時間に通ってくる場所というふうに考えてよろしいでしょうか。一応確認です。","respondent":"小林学校施設担当課長","answer":"多目的室などを改修して、将来的には普通教室にも転用可能ですという、マックスの数字を書いております。それと特別支援学級につきましては委員おっしゃるとおりでございまして、普通教室程度の大きさで設置しています。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"ただ、ここ数年改築されている学校で、それぞれ特別支援関係の教室が、ほかの子どもたちの活動場所や動線から大きく離れているというのはこれまでも指摘され、改善を求められていたところではないかと思うのですが、その点についてどのように、この設計についてお考えでしょうか。学校側はなぜ離したほうがいいと言っているのか、その理由も教えてください。","respondent":"小林学校施設担当課長","answer":"現在のところ、特別支援学級につきましては、今、委員がおっしゃったとおり給食室の上に配置しております。基本設計、実施設計と、今、実施設計を進めておりますけれども、我々は関係部署等のご意見をいただいて、先ほどもお話ししましたが設計条件を整えていきます。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"声を聞く相手というのは、教育委員会内、関係部署あるいは学校だけなのでしょうか。保護者の声までは聞くようになっていないでしょうか。","respondent":"小林学校施設担当課長","answer":"我々は専門の知識を持った人等も含めていろいろな方からご意見をいただき、今お話ししましたように町会長も入れて話し合いもしました。そういうところからの要望があったときは最大限聞き入れるように、計画はしたところです。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"これで最後にしますけれども、特別支援教室の配置については、特別支援教室を利用しているお子さんたちの親御さんですとか、あるいはより当事者に近い方の声を含めて聞かれるのがよろしいのではないかと思います。そうするとやはり、できるだけ当事者に近い方にそれぞれ聞くということを、今後やっていただければと思います。最後、ご答弁をお願いします。","respondent":"小林学校施設担当課長、矢部教育総合支援センター長","answer":"指導課、教育総合支援センター等とも打ち合わせをしまして、専門の方も入れて意見を聞いて、設計に反映できるものについてはできる限り織り込んでいるというところで。委員ご指摘のとおりで、インクルーシブ教育は大変大事だと思っています。学校の実態は、基本的にこの特別支援教室に通うお子さんというのは、１週間に２時間程度ですので、ほぼ教室でみんなと仲よくやっております。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういった中でここにあるものが、どれが間に合うとか、間に合わないとかそれぞれあるとは思うのですが、今後空調も考えながら設置されたほうがいいのかなとも思うのですけれど、その辺は何か検討していたり、研究していたりすることがあれば教えていただきたいです。","respondent":"小林学校施設担当課長","answer":"ただ昨今、コロナウイルスの問題もありますので、今現在できるかということはちょっと申し上げられないのですが、検討段階の中では、普通の換気扇だと効率がよくないので、熱交換をしての換気というものがあります。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"日進月歩ではないですが、どんどん新しいものが出てくると思うので、その都度またいろいろ検討されると思うのですが、特にコロナの関係でそういう懸念もされているので、ぜひ、可能な限り配慮していただければと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"３点お聞きしたいと思います。２点は具体的なイメージが分かりましたら教えていただきたいのですけれども、第四日野小学校のコンセプトの２の最後のところ、「鉄道に隣接することから、騒音や駅からの見合いに配慮したバルコニーを整備します」ということなのですが、どのようなところを配慮していらっしゃるのか、具体的なイメージを教えていただけたらと思います。","respondent":"小林学校施設担当課長","answer":"それと湿気につきましては、ここについては屋上に設置しておりますので、温水プールではございませんので、湿気については基本的に大丈夫と考えています。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"湿気のほうも、特に温水プールではないということで、更衣室も５階ですので、それほど湿気がたまりやすいかどうかというと、設計のことに詳しくないので分からないのですけれど、多分窓とかはないと思いますので、いろいろ設計の面で工夫していただいたり、また今、コロナの関係もあって換気などにも配慮していただいているかと思いますので、ハードの面とソフトの面と併せて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれど、多目的室を第四日野小学校でも作られていると思うのですが、普通教室に転用可能だということですけれど、この理由は、やはり人口増などに対応するために作られているのかということと、今回の一覧表に載っている学校は全て、また今後もそうした多目的室を、人口増に柔軟に対応するために作っていくという方針なのかということを、まず１点お伺いいたします。","respondent":"小林学校施設担当課長","answer":"就学人口に合わせて、将来を想定しましてできる範囲、この敷地の中でできる範囲の学級数をとっているところです。委員のおっしゃるとおり、多目的教室というのは現状ではそういうふうに使って、将来就学人口が増えたときに、普通教室に改修して使用するです。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"２点目としまして、城南小学校、城南幼稚園では、文化財発掘調査というのがあったかと思うのですけれど、特に工事がまだ着手されていない、浜川小学校などもそうだと思うのですが、文化財調査もしくは土壌が汚染されている場合というのもあり得なくはないかなと思っているのですけれども、そうした調査とか、またもし出た場合の対応とかはどのようにお考えなのでしょうか。","respondent":"小林学校施設担当課長","answer":"埋蔵文化財等につきましては、発見というか出てきた段階で適正な方法をとって、工事のほうを進めていきます。土壌汚染につきましては、撤去をして普通の汚染されていない土に入替えるとか、それについては法律に基づいて対応していくです。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"既に工事をやられたところはあるのですけれども、浜川小学校の調査段階、設計の段階とか、現段階では特に問題は発生しないということでよろしいですか。","respondent":"小林学校施設担当課長","answer":"はい、そのとおりです。","id":"exchange-020"},{"speaker":"芹澤副委員長","kind":"確認","question":"これを見るとやはり全面グリーンなので、人工芝になっているのかなと思うのですが、この状況の中での区民まつりの活用というのは、どういった話し合いになっているのでしょうか。","respondent":"小林学校施設担当課長","answer":"トラックについても、大きなものではない。というところから、いろいろと打ち合わせの中でできる範囲を想定したのですけれども、非常に狭小の敷地で、学校の校庭を確保するのもかなり難しかったというところで、意見を頂戴しましたけれども、今回はこういう配置で進めていくです。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"それぞれのパースを見ると、人工芝、それから舗装のものもあるのでしょうか。それぞれどういう観点で選ばれているのかというのと、災害時にやはり火を使うときなど、舗装のものはよろしくないという時期もあったと思うのですけれども、それについてはどう対処されるのか。","respondent":"小林学校施設担当課長","answer":"有事の際は、人工芝を剥がすのも大変ですけれども、そういうふうなことをやるか、あとは養生、鉄板を敷いてその上で火を使うとか、いろいろなことは考えられると思うのですが、有事の際はそういう形で、人工芝を守るのではなく、災害の対応のほうを優先してやるべきであり。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"環境汚染については、品質は向上していると思いますけれども、しかし経年で必ず抜けていったり、あるいはちぎれて流れていったりするものですので、当初の開発だけではなくて、例えば排水の仕組みですとか、そういうものも工事のときであれば比較的、途中からだと大変だと思うので、そこを配慮していただけるでしょうかというお話で、もう一度お願いします。","respondent":"小林学校施設担当課長","answer":"そういうところは小まめに清掃をすることにより、流れていかないように努めていきたいと考えています。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"このパースで、鮫浜小学校とか、浜川小学校、浜川幼稚園も、人工芝なのですか。人工芝にトラックが書いてあるということなのでしょうか。剥がさないと火が使えないようではなかなか災害時の拠点としては難しいかと思いますので、そこの配慮をお願いしたいと思っているのです。そういうことが、一時はスタンダードになっていたと思うのですけれどもいかがでしょうか。そこのご答弁をお願いします。","respondent":"小林学校施設担当課長","answer":"鮫浜小学校のトラックにつきましても、白の人工芝とか、色を塗るとか、そういうものはありますので、それについてはこのとおり描いていく予定です。","id":"exchange-024"}]},{"id":"topic-02","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"昨日も申し上げましたけれども、本会議の中で松本議員ならびに中塚議員より、品川区の区立学校、特に中学校の校則についての質問がありました。その中には、やはり校則として見直しが必要ではないかと思われる部分もあるかと私は感じているのですけれども、現在での教育委員会の把握と、それから内容について、あるいは今後の対応について、教えていただければと思います。","respondent":"矢部教育総合支援センター長","answer":"時間を守る、挨拶をする、ハンカチを持つなどです。ただ、実際は個別の対応や配慮も多くありまして、弾力的に対応しております。現在の校則が、児童・生徒の個性を縛るものではないと考えております。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"時代に応じて見直すというのは、とても大切なことだと考えています。最後におっしゃったような、熱中症防止のために水を飲むというのは現実に許可されている。現実に合わせて、やはりここは変えるべきだと思うのです。こういうルールが残ってしまっているという現実に対しては別に言いませんけれども、適宜そういうことに気づいたら見直す学校であってほしいと思うのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"委員のご意見は承りました。これまでも学校のほうには働きかけておりますので、引き続き、続けていきたいと思います。大事なところは、児童や生徒がきちっと理解をして、行動するということかと思います。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問・要望","question":"ですので、そこは単に学校に働きかけることだけではなくて、教育委員会としてぜひイニシアチブを、もし学校が動かないようであれば、イニシアチブをとっていただきたいと思います。もう一つ、水分だけではなく、下着の色というのもあったかと思います。これは十分に、ぜひ議論をしていただきたいと思います。それについては、教育委員会のお考えはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"もう一点の場面は日常生活において、子どもたちに廊下を走ってはいけない理由は何かということを考えさせる場面はありますので、上手に組み合わせて指導してまいりたいと考えています。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"これについては、また今後の進捗などを教えていただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、個性を縛るものではないという認識も示されましたけれども、明らかに人権に抵触するようなものでしたら、把握するためだけでなく、改善を求めていくというか、促していくというか、そういうことも教育委員会としては必要ではないかということなのですが、それについてはいかがでしょうかというのが一つ。事実として。","respondent":"矢部教育総合支援センター長","answer":"１点目の明らかな人権侵害ではないかというところにつきましても、同じように指導主事が問い合わせて、管理職とのやり取りの中で気づくようにしていることと、委員ご指摘のように児童の権利に関する条約の中でも、「必要な範囲内では校内で指導や指示を行い。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"誰がどう見ても理不尽な内容で、実際に指導している側も、守らなくてもいいよみたいに有名無実化しているようなルールですと、先ほどもありましたけれど、ルールは建前と本音があって、守らなくてもいいのだという、逆の効果が生まれてしまうというか、それはやはり子どもにとってもよくないことだと思いますので、そこら辺も踏まえてしっかりと、これからも取り組んでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問","question":"一般質問の答弁でも、先ほど委員からもありましたけれど、自主的に生徒が校則を決めていって、生徒会で話し合っているというお話もあったと思うのですが、私としては、生徒会などで校則を決めるということであれば、生徒たちに多様性についても学んでほしいと思います。多様性を学ぶ機会というのは、特に中学校ではどういった取り組みとかがありますでしょうか。","respondent":"矢部教育総合支援センター長","answer":"子どもたちの目の前にある多様性を認める場面は、個々に学校の中であると考えています。そのほかには市民科とか、国際理解等の学習の中で、少しずつ触れていくものかと考えております。今後とも多様性については、大切だと考えていますので進めてまいります。","id":"exchange-031"},{"speaker":"せお委員","kind":"意見","question":"多様性について学ぶことは、これからはとても大切だと思いますので、先ほども、協調性を育む四日野ルームとあったと思いますけれど、多様性を学んでいけば協調性はついてくるものだと思うので、そういったところも含めて授業でも、授業以外のところでも、取り入れていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-03","title":"ガバメントクラウドファンディングを活用した子どもの食の支援事業～新型コロナウイルス感染症対策に関する緊急支援として～","agenda":"ガバメントクラウドファンディングを活用した子どもの食の支援事業～新型コロナウイルス感染症対策に関する緊急支援として～","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"この事業について、もう一度お金について確認させていただきたいのですけれども、まず実施したものについて集まった金額、それからクラウドファンディングは手数料その他の経費がかかると思います。その経費が幾らぐらいだったのか。そのうち、食品と配送料もかかったと思います。その内訳、そして食品の選定と調達業者をどのように選んで、どこになったのかということを教えてください。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、この残額３１９万１９７円相当額を、第２回目のしあわせ食卓事業として対応してまいります。今回、食品に使った部分ですが、第１回目につきましては食品代というか、商品代という形ですけれども、２５８世帯分で７９万４,０００円となっております。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、約５００万円が寄附金として区に入ってきた。そのうちの１３８万円余が、第１回目のしあわせ食卓事業に使われたということでよろしいのでしょうか。それで、残りが３１９万円余。第２回目、５,５００円相当とおっしゃっていたのは、１家庭分ということなのでしょうか。そうすると７９万円は２５８世帯ですから、５,０００円分を充てたということなのでしょうか。そこまでいいですか。","respondent":"三ッ橋子育て応援課長","answer":"こちらは先ほど委員ご指摘のように、１家庭分の商品代と申し上げましたのは、１世帯分として考えてください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"それと最初の質問で、食品の選定ならびに調達業者をどう選んだのかということを教えてください。","respondent":"三ッ橋子育て応援課長","answer":"失礼いたしました。食品の選定、配送業者につきましては、食品ロスの削減に取り組む業者であり、しながわＣＳＲ推進協議会会員となっております、株式会社クラダシというところを使っております。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"これは全てクラダシさんなのですか。その５,０００円の中で、その企業が自分の手持ちの食品ロスの食材を選んで、つまり幾ら分のものを５,０００円として購入されているのでしょうか。いわゆる一般価格よりは相当安く入手され、販売されている企業かと思いますけれど、どのような感じでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"こちらの商品代は５,５７０円分ですが、一般価格で申し上げますと、１万７,０００円相当です。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"ただ一方で、いわゆる売れなかった商品ということですので、これはちょっと個人の価値観も入りますけれども、菓子類など、一般的にあまり日本人の口に合わない輸入菓子とかもかなり扱っていらっしゃるようですが、そこら辺、どういうものを選ぶかというのは、区としてもきちんと入っていらっしゃるのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"今回、特に乾麺であったり、先ほど申し上げたような内容なのですけれども、かなりよい物と、普及されているものの中、一般的なものが中心となっています。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"アンケートですが、無料で宅配までしたら、喜びの声というのは当然来ると思うのですけれども、クオリティーを上げていくためには、率直にどう受け止めたかというお声が大切だと思うのですが、それについて何か工夫はされていますでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"やはり基本的にはお礼、感謝のお声が一番多いのですけれども、それぞれのご家庭のご意見が様々ありまして、例えば割と年齢層が高いお子さんがいらっしゃるところ、乳幼児がいらっしゃるところ、いろいろあるので、全てを網羅することはなかなか難しいのですけれども。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後は要望になりますけれども、やはりこういう事業は各自治体でやっていて、主食になるものが一番、困っている方ほど喜ばれるということなのですね。そういうこともぜひ勘案して、こちらの都合というよりは求められているもの、引き続き努力をしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"アンケートですけれども、何人ぐらい返信があって、どういう項目を聞いているかというのを聞かせてください。それと、前回第１回目の２５８世帯に加えて、新たにひとり親家庭等医療証を受給した方で配送を希望する家庭ということですが、配送希望というのはどういうふうにつかむのかということで、この事業の周知はどういうふうにやるのか伺います。","respondent":"三ッ橋子育て応援課長","answer":"周知方法ですが、今回はひとり親家庭等医療証と共に発送いたしまして、食の支援が必要な方が申請してくるというものです。広報しながわとホームページではお知らせしております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"アンケートの回答数といいますか、何人ぐらいかというのだけ、最後に教えてください。","respondent":"三ッ橋子育て応援課長","answer":"アンケートの回答数ですが、最終的には５０％の１２９人でございました。食品を配送した後のアンケートに答えていただいた方は５０％の１２９人です。最初にしあわせ食卓事業のお知らせをしたときのアンケートにつきましては１００％の２５８人です。","id":"exchange-041"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、コロナの関係での緊急支援となっていますけれど、そこからまた状況が変わって希望したいと、こういうものがあるなら自分もお世話になりたい、そういう方もいらっしゃるかと思うのですが、今回はあくまで前回、第１回目に送られた方を対象として、それ以外の方については基本的に受けないという考えでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"令和２年度のしあわせ食卓事業につきましては、これからひとり親家庭等医療証と共に、食の支援が必要かどうかのお知らせをしていき、そしてご要望をとる予定です。それは令和元年度と同様に１２月と考えております。","id":"exchange-042"},{"speaker":"たけうち委員","kind":"質問","question":"そこは何か、募集してしまうと大勢来てしまうのかなと、来てしまうという言い方もおかしいですけれど、希望される方が増えてしまうから、混乱を招いてしまうのかもしれませんが、せっかく、わざわざ新型コロナウイルスの緊急支援ということでやっているのであれば、次の１２月と言わずに何かお知らせして、前回は申し込まなかったけれど、今回は逼迫していて大変なのだと手を挙げる人にも。","respondent":"三ッ橋子育て応援課長","answer":"区としては１２月と考えておりますけれども、東京都が児童扶養手当受給者に対して、カタログで商品も配送するということを考えているようなのです。そちらに手を挙げていただき、希望されれば食品等が来る予定だと考えています。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そちらのほうの周知もしっかりやっていただきながら、ぜひ可能な限り、要望だけさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"アンケートの部分をお聞きしたいのですけれども、配送を希望しなかった理由というのは、今回何かあるのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"配送を希望しない方というのは、今回は食品を配送しますということしかお伝えしていなくて、そのアンケートしかとっておりませんので、皆さん、食品の配送を希望された方という形になっております。","id":"exchange-045"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、１２月にお知らせをしたときのアンケートの戻りというのは、配送を希望される方だけを対象にしたアンケートをとったということなのでしょうか。アンケートに関しては、医療証を受給している方全体としてとっていらっしゃるのか、食品を希望された方だけを対象にしたアンケートになっているのか、教えてください。","respondent":"三ッ橋子育て応援課長","answer":"医療証の配送のとき、しあわせ食卓事業がありますというお知らせをして、その食品の配送を希望される方から、アンケートの答えをいただいたということになります。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"もう一つなのですが、しながわ活力応援給付金が今回あるかと思うのですけれども、例えば寄附をしたいとご希望をされる方がいらしたとき、こうしたガバメントクラウドファンディングを活用した子どもの食の支援事業というものがありますということと、９月以降始めますということを、寄附を希望される方にしっかりとお伝えしていくことは大事だと思っていますので、その辺りもお願いしたいのですが。","respondent":"三ッ橋子育て応援課長","answer":"しながわ活力応援給付金に関しましても、９月から私どものガバメントクラウドファンディングを実施するということは周知してまいる予定です。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問・要望","question":"午前中には事実関係の確認を中心にさせていただきましたが、この後、質問をいろいろさせていただきたいと思います。そこで区としては、これを今後定期化していく考えがあるのかどうか。配送方法なのですけれど、宅配業者による直接配送ということですが、これはどういう形で行われているのか。品川区ではどのような配送方法を考えているのか、教えてください。","respondent":"三ッ橋子育て応援課長","answer":"ただ、定期化に関しましては、確かに委員ご指摘のように、食品を受け取る側は定期的なほうが、もちろんありがたいと思うのですけれども、その辺りは本当に区として十分に考えていかなければいけませんので、今回の第１回のガバメントクラウドファンディング。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"今の二つの質問はつながっておりまして、つまりこの事業の目的というのは、困っているから、困窮しているから食材をさしあげましょうということなのか、それとも食材を提供することをきっかけとして、支援につなげるということが主な目的になっているのか、どちらなのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"そのような考えに基づいております。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"その考えはとても賛同するところですけれども、実際にアンケートも半分戻ってきたということで、今回１回目を届けたことで、支援に何件つながったのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"アンケートの結果から申し上げますと、１２９名の方からアンケートの回答をいただきまして、今回の支援の中で関心を持ったものという項目もありまして、奨学金のこと、学習支援のこと、また就労支援など、例えば奨学金の関係ですと、５３名の方からご意見をいただいております。","id":"exchange-050"},{"speaker":"あべ委員","kind":"意見","question":"そうした形で支援につながっていくのはとてもいいなと考えています。現在２５８世帯ということですけれども、例えば人口が半分の文京区でも今、５６０世帯、もっと超えていたかもしれませんので、そうした意味では支援につなげることと、ご利用世帯が増えるように、また工夫をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なのですが、午前中、たけうち委員の質疑の中で、当時は必要でないけれども、コロナの影響で新たに希望する方に届けるべきではないかというご意見があり、そのとおりだと思うのです。次は１２月でしたか、タイミングはとても大事だと思うのです。今届けるということが大事だと思いますので、ぜひ柔軟な対応といいますか、運用をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-04","title":"ひろまち保育園閉園に伴う在園児の優先転園","agenda":"ひろまち保育園閉園に伴う在園児の優先転園","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"それと、所管課としては子どもを最優先に考えて、在園児が卒園するまで、ひろまち保育園の閉園時期を延ばすという選択も当然あったと思うのですけれども、保育園部局としてそういう提案をちゃんとしたのかどうか、それともしなかったのか、伺いたいと思います。","respondent":"立木保育課長、吉田保育施設調整担当課長","answer":"そういった部分を少しでも軽減できるように、これは新入園のお子さんもそうなのですけれども、保育士のほうがきちっとお子さんの様子を見ながら対応していくということで、そこは保育士はプロですので。閉園を延ばす方向での検討についてですが、広町の開発がある中で、もともと５年間の期間限定ということで、スタートしたところです。令和３年以降、広町のまちづくりの予定があることから、当初の予定どおり５年で閉園するところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"提案","question":"ここに関しては、この資料によりますと、もう７月１日から周知をするということですけれども、確かにどんどん在園児が減っていくということになりますと、むしろ転園したいという人もいるかもしれません。その上で、優先転園を案内するだけでなく、この方針そのものを、閉園延期も含めて再検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"吉田保育施設調整担当課長、立木保育課長","answer":"現在はそのため、閉園に向けた最後の取り組みをしています。現在の２歳児、３歳児、４歳児につきましては、今まで同様、転園に関して丁寧な対応をしていくところです。見てほしいということでなく、しっかり見ているという事実ですので、もちろんしっかりやることは前提なのですけれども、決して現場のほうに丸投げしているということではなく、保育課のほうもいろいろな研修等も交えながら。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろとご答弁いただきましたけれど、やはりコロナのこういう状況で、子どもたちにものすごいストレスがかかっていますし、コロナの危機を経て社会も大きく、何を求めていくかというのは随分変わってきているのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"あべ委員","kind":"質問","question":"ひろまち保育園ですけれども、今は閉園に向けてというだけではなく、定期保育もやっていたと思うのですが、１歳児、２歳児、３歳児で募集していたでしょうか。各年齢での現在の人数と、年度途中で入園希望してなかなか保育園に入れない方に、引き続き今年度も、このひろまちの定期保育にご案内していくのかどうかということを教えてください。","respondent":"立木保育課長","answer":"今、ひろまちのほうは空きスペース型の年間保育という形で、１歳児、２歳児、３歳児のお子さんを１年間ということでお預かりしています。６月の在籍数で、１歳児が３０名、２歳児が１５名、３歳児が１０名という形になっております。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問","question":"ここは年間保育というイメージなのですね。この年間保育、基本的にはフルタイムの方が多いということなのでしょうか。１歳児、２歳児、３歳児合わせて現在５５人、多分これからまだ増えるのではないかとも思うのですけれども、この方がフルタイム、あるいは毎日のご利用が多いのか、その辺は把握されていますか。","respondent":"立木保育課長","answer":"詳細、個別のデータを持ち合わせていないので、お答えがはっきりとできないのですけれども、定期利用に関しましてはやはり入園審査がありますので、それなりに時間数等もある方がご利用されるというふうに考えております。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"であれば、３１人が転園できれば大丈夫ということではなくて、この定期利用の子どもたちも、しっかりと予定に入れた需給の計算でなければいけないと思うのです。その受け皿というのは、１歳、２歳、３歳が、２歳、３歳、４歳になっていくわけですから、当然入れているとは思いますけれども、そこの需給予測というのはどうなっているのでしょうか。","respondent":"立木保育課長","answer":"定期利用の方、こちらの年間保育利用の方も含めまして、資料にありますとおり、すみません、２歳児は入っていないのですけれども、３歳児、４歳児、５歳児ということで、合計これだけの入園枠は、現時点で定員ベースでとれているというところです。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問・要望","question":"もちろん一定の割合、転居等はあると思いますけれど、それはほかのお子さんも当然そうだと思います。それも保育園に落ちて入ったという方も少なくありませんので、そうしたことを考えると、この数字上だけではない、保育の受け皿の拡大というのをぜひ図っていただきたいと思っているのですけれど、その来年度の予測というのはどのようにお考えですか。","respondent":"立木保育課長","answer":"やはり一つ影響があるのは、恐らくご希望どおりになかなか、ご自分のご希望している園を選べないというところがあるやもしれないのですけれども、そういったマッチングの部分といったところは入園の相談のほうで、例えばこちらの園だったらどうでしょうみたいな形というのは。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"保育の質の問題です。これが閉まってしまうことによって、せっかくの区内でも誇れるレベルの保育実践が途切れてしまうというのは非常にもったいないことだと思っているのですけれども、これまでのひろまち保育園の実践レベル、あるいはその事業者について、今後品川区とどのような関係になっていくのか、それを引き継ぐことができるのか、教えてください。","respondent":"立木保育課長","answer":"今現在も、品川区はレベル的には高いものがあるというふうに自負していますが、培ったものはそのまま捨てることなく、活かしていきたいと考えています。","id":"exchange-060"}]},{"id":"topic-05","title":"上大崎三丁目教育・保育施設の整備・運営事業者の選定","agenda":"上大崎三丁目教育・保育施設の整備・運営事業者の選定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"すみません、私は文教委員、相当久しぶりというか、ほぼ初めてなので改めて伺いたいのですが、ここを認定こども園とした理由といいますか、区の考えを伺いたいのと同時に、改めて認定こども園とは、保育園や幼稚園と何が違うのか、教えていただければと思います。","respondent":"若生保育支援課長","answer":"認定こども園はどういったものかと申しますと、説明の中でも申し上げましたけれども、通常の保育認定をされているお子様、０歳児から５歳児までをお預かりすると共に、それとは別の教育認定を受けた３歳児以上のお子様、いわゆる幼稚園部門の。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのは、近隣住民、地元との調整や話し合いの現状について伺いたいのですけれど、特に施設の直近の住民の方との話し合いとか、やり取りといいますか、その辺はどうなっているのか伺いたいと思います。住民の理解というのは率直に得られているということなのでしょうか。","respondent":"若生保育支援課長","answer":"その後、昨年度の１０月１８日に今度は近隣住民を対象として、こういった保育施設を計画していくということで、内容に関して区としての説明会、近隣住民の皆様との意見交換会、こちらを地域センターで行ったところです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"提案","question":"これからもそういう施設計画を練り上げる段階での丁寧な進め方というのが必要だし、そういうこともやっていただきたいのですけれど、いかがでしょうか。","respondent":"若生保育支援課長","answer":"そういった中で、どういう建物を建てていくのかというところは事業者のほうからきちんと説明させていただいて、その中で近隣の方々からご要望があったところにつきましては、委員ご指摘のとおり、なかなか全てを受け入れてできるものではございませんけれども。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"これは３０年間の貸付で行うということですけれども、国からこれを購入して、定期借地で貸付料というのはどのぐらいになるのでしょうか。それから３０年間で原状回復して返還ということですが、３０年だとあまり堅い建物にはならないですよね。これは例えばプレハブみたいなものになるのか、鉄骨とか入れる感じでもなさそうですが、どういうふうになるのでしょうか。教えてください。","respondent":"若生保育支援課長","answer":"こちらの貸付料につきましては、これから事業者のほうと、想定している金額等も検討しつつ調整していきたいと考えていますが、不動産鑑定で３者ほど見積もりをとったところで、その平均値として大体この地域ですと月当たり２百数十万円と。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"スケジュールは、令和２年６月は今日で終わりなのですけれども、そうすると既に整備・運営事業者決定、これは、工事の事業者も含めて決まっているということなのでしょうか。それから１０月開設ということですが、保育園は年度途中の開設というのはままあるかと思うのですけれども、あまり教育部門の年度途中開設というのは、これは少し時間差になるのでしょうか。それを教えてください。","respondent":"若生保育支援課長","answer":"それから年度途中開設の部分で、教育部門と子育て支援機能の部分が１０月から開始できるかですけれども、教育認定に関しては申し訳ございません、入園の担当のほうに確認をしないと分からないところなのですが、子育て支援機能。","id":"exchange-065"},{"speaker":"あべ委員","kind":"意見","question":"最後になりますけれども、これから解体工事に入られるということで、あの地域もなかなか、道路といいますか入りにくかったり、住宅街で道も狭めということで、そこは十分理解を得ながら、かつ安全にやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区としては不明確で定量的に示すのは困難ということだったのですが、なぜ困難なのか、どこが不明確なところなのか、あるいは現在の待機児童数が１３名ですが、不承諾数は１,１７５名ということで、この内訳ですとか、あるいは現在や過去の区の待機児童数のカウントの仕方の変遷ですとか、国の今の指針の内容などもあわせて、ご説明いただければと思います。","respondent":"若生保育支援課長","answer":"平成２７年度以降は、子ども・子育て支援制度を開始したことによって、いわゆる地域型事業ですとか認定こども園、幼稚園の預かり保育、こういったものの利用者も、待機児童から除く取り扱いに変わったものです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"区民が混乱と言いますけれど、それはどうなのでしょうか。質問なのですけれど、不承諾数が今年１,１７５人、待機児童数が１３人になるということなのですが、先ほど幾つか国の定義に基づいて例を挙げていただきましたけれど、三つしか分からなかったので、この１,１７５名の具体的な項目と内訳を教えてもらいたいのですけれど、よろしくお願いいたします。","respondent":"若生保育支援課長","answer":"この合計が１,１６２名でございまして、これを除いた待機児童数が１３名ということで、１,１７５名の内訳となっています。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"事務事業概要にも載せたほうがいいと思いますし、そうしないと、具体的な実態がつかめない。保護者にとっても誤解が生じてしまうといいますか、そういうふうに思いますので、ぜひそういう形で公表していただきたいと思いますけれども、いかがでしょうか。そういった方々の実態というのは、どのようにつかんでいらっしゃるのでしょうか。伺いたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"国のほうの待機児童数調査につきましても、この内訳を含めて報告しているところでございまして、区としてこれが公表できない数字ではないものですけれども、今後につきましては、区民等に分かりやすいのはどういう公表の仕方なのか。それ以外に、やはり通わせたい園、ここがいいというご家庭、先ほどのマッチングのお話にもなるかと思うのですけれども、そういったところで、統計的に全ての不承諾者の希望園数というものをとっているわけではないので。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際に、あえて１園のみを希望というのは大体どれぐらいなのか、感覚でもいいのですけれど、これは実態をつかむ上でも、４９７名のうち何人なのかというのは、一つつかむ必要があるのではないかと思うのですが、大体何人ぐらいかということと併せて、ご答弁いただきたいと思います。","respondent":"立木保育課長、若生保育支援課長","answer":"特定の１園というところで申し上げますと、２１２名ということです。それぞれのご家庭で、将来等の働く、働かないという決定があると思いますので、保育園に入れなかったから必ずしも求職活動を中止したのかというところは、この数字からはなかなか判断できない部分です。","id":"exchange-070"},{"speaker":"安藤委員","kind":"意見","question":"最後のところは、やはり保育園に入れないから職に就くのを諦めたというのが普通だと思いますし、それがほとんどだと思いますので、深刻に受け止める必要があるのではないかと思いますし、そういう子育て家庭が置かれている深刻な保育園不足の実態というところをしっかり捉えた上で、施策を進めていく上でも、しっかりと具体的に数字をつかみ、そして公表していくことが必要だと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、いろいろと数字が出てきました。国の共通の定義によれば１３人、この計算式自体は分かります。だから、１３人まで数字が少なくなってよかったということではなくて、次はその諦めざるを得なかった方々にも、どうやって保育を提供するかという、そこを考えていただきたいのです。１３人ですといって終わってしまったら、そこの改善をしようというスタートラインに立てないわけではないですか。","respondent":"若生保育支援課長、立木保育課長","answer":"ただ、そういったところのご利用にも至らないといいますか、ご利用になれず仕事を辞めざるを得なかったといった方も、一方でいらっしゃるというところは、今後区としましても。そうしたときに、ただいま保育支援課長が申し上げたとおり、総合的な待機児童対策ということでこれまで進めてきておりますので、そういったトータルでの保育の必要性の部分を提供させていただいているという形になっております。","id":"exchange-072"},{"speaker":"あべ委員","kind":"質問・要望","question":"ミスマッチの部分もそこそこあると、それは私も否定しないです。その中で、例えば今品川区では、８園まで希望が書けるのだと思いますけれども、この８園になってからかなり保育園の数は増えてきました。これが１点です。それを選ばないからといって、私は親のわがままだとは全く思わないので、そうしたこともやっていただきたいと思いますが、この点をお願いします。","respondent":"立木保育課長、若生保育支援課長","answer":"希望の園数に関しましては、どの程度までいけるかというところは今後、検討させていただきたいと思います。そういった事業も考えながら、今後質の向上に努めてまいりたいと考えております。","id":"exchange-073"},{"speaker":"あべ委員","kind":"質問・要望","question":"希望が同じエリアでも、集まる園と集まらない園と、何が違うのかということはぜひ見ていっていただきたいと思います。入れなかった人たち、コロナに関連しての保育料の返還ですとか、認可園に入れるかどうかでやはり差がついてきてしまうのですよね。そうしたところで入れなかった方々に不利が続くようなことがないように、目を配っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"あべ委員","kind":"意見","question":"行政視察については、やはり今後、おっしゃったように不透明な部分がたくさんあると思います。必ずしも前例にとらわれないで、宿泊を伴わない近距離での視察ですとか、あるいは場合によっては遠隔での研修など、何かできる形で学んでいくというようなことも、併せて考えていただけるとありがたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=5008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":48839,"voices":184}},{"id":"r02-20200630-5","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"総務委員会","time":"午前１０時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、新型コロナウイルス感染症対策の財源づくりについて伺いたいと思います。国に対して増額を要求すべきだと思いますけれども、区はどう思っているのか、いかがでしょうか。同様の質問ですけれども、新型コロナウイルス感染症の感染状況によっては、今後さらに追加の補正予算や事業も必要になってくるかと思いますけれども、今後追加の財源はどのように確保していくのか、それぞれ伺いたいと思います。","respondent":"品川財政課長","answer":"この間いろいろ、補正予算で計上してきたのは給付金が大きいところがあります。それ以外の対策事業については、やはり数億円単位で行っているというところですので、現在２２億円あるとすれば、対応が十分可能ではないかと考えております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりは増額を求めているということでよろしいのか、その点を確認させてください。もちろん区民生活を支える福祉を削れと言っているわけではありません。私がとりわけ問題にしているのは、再開発事業についてです。審査の結果は審議会に委ねるとして、区の姿勢として、巨額な税金を使うこうした超高層の再開発事業は、少なくとも延期という姿勢を持つべきではないと思うのですけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"その時々の状況に応じて随時対応していきたいと考えております。既存の事業を中止するといったお話もございましたが、区役所の事業というのは、当然計画に基づいて実行しているものです。ですので、必要な事業においては、それを実施していくというのが基本的な考え方です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"これで最後にしますけれども、財源確保については、再開発は少なくとも延期としていただきたいと改めて要望しておきたいと思います。今のご説明で、財源確保について、いろいろな対策が取れるというご説明がありましたが、例えば、どういう対策が考えられるのか。","respondent":"品川財政課長","answer":"どうしてもという場合には、当然起債を起こすとか、そういう方法で財源を確保する方法もあります。財政面でいろいろ手法があり、いろいろ検討して財源を考えていかなければいけませんので、そういった視点をもとにしまして考えていくという説明になります。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"今財源のお話もありましたし、こういうことに充てるということについては、必要なものだと思いますので結構なのですが、限られた財源を有効に使っていただきたいという意味で、１点伺いたいのですが、例えば、感染拡大防止対策物品購入とか、これは所管ではあまり議論にならなかったようなのですが、子どもの未来応援事業で、子ども食堂の支援とか、保育園関係の健康診断時における感染防止対策物品。","respondent":"品川財政課長","answer":"委員のお話にありましたとおり、購入の際には当然国の基準等いろいろ照らし合わせて、よりよいものを購入していきたいと考えております。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の基準というより、それが有効でないと表示されているので、限られた財源をそこはちゃんとぜひ有効なものに使っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"区内産業もそうですけれども、一部の業者、商店に流れていくという状況、あと使う方もそれなりに家計にある程度余裕のある方が買って、さらにそれにプレミアムが付くということですから、支援をやるのはいいことなのですが、今この状況において家計が大変な方、それは区のほうで十分把握されていると思いますので、そういう方に財政的な支援、補助なのか。","respondent":"品川財政課長","answer":"区の対応としては今回しながわ活力応援給付金等を出して、無駄がない給付にし、とにかく今回は全区民の皆さんに届くような対応という形にしています。先ほど委員からお話がありましたプレミアム付区内共通商品券等は、今回いろいろ工夫して、なるべく当たりやすい。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"悩ましいところで、商店街振興の意味ではいいのですが、どうしても一部の方に限られる。それはそれで大事なことですが、今課長がお話ししたとおり、プレミアムが付くとしても、お金がない方にそれを買い求めろというのは現実論としては厳しい、買いにくいものだと思うのです。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"ほかにご発言はありますか。では、私からちょっと確認です。今お話がありましたしながわ活力応援給付金の担当が新設されていますが、この後の流れなのですけれども、国の給付金は今、福祉計画課でやっていますが、その方が移って作業していく感じになるのですか。その辺の流れを、まず確認したいと思います。","respondent":"佐藤企画調整課長","answer":"区独自の給付金の仕組みに関してですけれども、６月２日に組織を立ち上げた時点で、全庁的に職員を兼務で配置して、給付金事業の詳細、システムの構築等にあたっていますので、委員がご指摘のとおり、国の給付金を担当する職員もいますので、その辺は給付の状況を見ながら。","id":"exchange-008"},{"speaker":"中塚委員","kind":"意見","question":"賛成します。第２波に備えて、引き続き検査や病院、区民や事業所への支援をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"もっと困っている人に集中的に手当てをすべきではないのか。一般質問でも言いましたが、特にもう仕事を失ってしまったという方たちが既に出ているわけで、事業者への支援はもう当然で、そこが雇用を確保していただくのが大前提なのですけれども、やっぱり集中的にこういう方たちへの財源の手当てが、お金の手当てが必要ではないかと思いますので、そのことだけは今後検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"品川区総合庁舎免震オイルダンパー交換","agenda":"品川区総合庁舎免震オイルダンパー交換","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ＫＹＢ株式会社による本当に悪質な事件だったと考えています。事態が重いだけに、相手がしっかり反省しているのか、それには自分たちがなぜこのような行為に至ったのか、しっかりと説明させることが必要かなと思いますので、データ改ざんと検査機器の不正操作について、先方がどのような理由というか、間違いを説明しているのか伺いたいと思います。","respondent":"東野経理課長","answer":"これを社内できちんと検査できる体制が整っていなかったことも理由の一つだと聞いているところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"量産体制に入って、納期を守れない、また検査の体制が組めなかったため、改ざんに手を染めたと、今回新たに設置されるものは国の確認がされているということですが、国を第三者というのか分かりませんけれども、基準に合っているかどうかは、どのように担保されるのか、国による検査について説明していただきたいと思います。","respondent":"東野経理課長","answer":"国の検査責任といいますか、どういう担保を取れるのかという部分ですが、国が検査チェックをするというところで今回の改ざんも分かったので、国の検査が最終手段だと考えています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"いずれにしてもこの間の区の毅然とした態度は評価したいと思います。区は被害者ですので、今後こういう信頼を失うような事態が二度と起きないように、総務委員会で言うのは変ですけれども、建設行政といいますか、契約も含めて引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、今回国のお墨つきを担保といいますけれども、それは信じるに値するのですか。その辺はどうなのですか。結局、国が検査して、検査基準を作っても不適合が流れてきた。今回も同様ですよね。何を担保にして、今回これを承認、また区としてもどういうふうに承認したのですか。","respondent":"東野経理課長","answer":"データ改ざん、それから元の数値の改ざんといったところが、国としても最終的には発覚したという部分がありまして、そういうところの検査体制をきちんとしているものと区では捉えておりますので。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"製造業の立場からすると、これだけ改ざんした会社をまた使うというのはどうなのかなとは思うのです。ではそのときに、このダンパーの耐震、免震の安全保証があったわけですが、この数年間それが全然機能しなかったことに関して、賠償責任を先方に問うわけにはいかないのでしょうか。その辺はどうなのですか。","respondent":"東野経理課長","answer":"ただ、賠償責任という形にするのか、それとも会社の責任においてきちんと適合品に交換してもらうのかという判断になってくるかと思います。それを区は交換でと判断したものでございまして、特に賠償責任を求める考えではございません。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"交換するのをその会社に頼むのは当たり前ですよね。もし何かおっしゃりたいことがあるなら、ちょっと言ってください。それと、総務委員会でダンパーのところを見にいきました。付けたはいいが、外すのはなかなかできない。たしかまたそこに埋め込み直すというのもできないというご説明だったと思うのですが、それが何でできるようになったのですか。ちょっと教えてください。","respondent":"東野経理課長","answer":"高さが１メートルもないようなところに付いているので、腰をかがめていくような、作業しにくいところになってあります。ただ、以前、ダンパー自体を付けたときには、工事作業員が作業できてありますので、決して交換できないという状況ではないというように受け止めてあります。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"設置した後も、設置しているときもそうですけれども、作業の現場をきちんと見ていただいて、安全に、しかもしっかり取り付けている状態になったかどうかは、区としても確認をしてください。かなり狭い場所で、付けるときは付けられても、外すときはなかなかできないという状況もありますから、そこは区でしっかり確認をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。それが１０月３日で、だけれども、交換は要求していくということなのですが、１１月１１日の元データの保証ができないためというのは、１０月３日の答弁とどういうふうに整合性が取れるのか、ちょっと教えていただきたい。","respondent":"東野経理課長","answer":"経緯のところにも書いてあります平成３１年１月２２日のところに、指定性能評価機関である日本ＥＲＩ株式会社に構造審査を依頼しというところで、ここで技術的に適合、いわゆるダンパーだけではなく、免震装置といったものでの構造計算をした結果。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"ただ、そのとき私ももう一回質問していて、ＫＹＢ社から提供してもらったデータをもとに庁舎の構造計算をしているということだったので、ＫＹＢ社からのデータで大丈夫ですかという感じで伺っているのですが、これはダンパーの問題とは別に、あくまで庁舎全体としては大丈夫ということですが、１１月１１日の元データの保証ができないためというのはどういうことなのでしょうか。教えてください。","respondent":"東野経理課長","answer":"実際出してきたものがございました。ただ、それも元の数値がきちんと合っているかどうかという信憑性がないものと判断したところです。そういった意味で、決算特別委員会の当時に発言したものと思われます。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"は信頼して、しっかりやっていただくことを要望するしかないわけですが、私たちも区民にきちんと説明できるような何かを示していただけるとありがたいと思いますので、もしそういうことができる、それは無理とかあれば、伺いたいと思いますが、いかがでしょうか。","respondent":"東野経理課長","answer":"元の数値をきちんと実証できなかったというところが、区として最大限追及してきたところでございまして、結局は全部の取替えにつながったことになりますので、区民に対してはそういう説明をしていきたいと考えています。","id":"exchange-020"},{"speaker":"湯澤委員","kind":"確認","question":"それが今回交換に至るのに少し時間がかかっているのかなと思います。交換にあたって、例えば、品川区の場合、工期は７月１１日から２３日ということで、品川区として、ここに至るまでにはどういった経過でこういうことになったのかということを確認させてください。","respondent":"東野経理課長","answer":"平成３０年１０月からになりますので、１年半という期間、かなりの経過をたどったところです。先ほどご説明しましたが、区として交渉した結果、昨年１１月に４基全部取り替えますというところまで引き出したものと捉えています。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。説明を受けて、内容は確認させていただきました。このことを区民に公表するにあたって、品川区のホームページにはこのような流れで行いました、そして工事はこのように行いますということは、ホームページ、またＳＮＳ等を使って公表されるのか確認させていただきたいと思います。","respondent":"東野経理課長","answer":"委員会でも報告している事項です。区民の安全・安心のために、ホームページでの公表もきちんとしていきたいと思います。ぜひ前向きにやっていきたいと考えております。","id":"exchange-022"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"委員長、副委員長で慎重に進めるのは確かに分かりますが、今回の新型コロナウイルス感染症は、普通の病気とはわけが違うので、どういう感染ルート、どういう状況になるか、症状になるかというのがもっと明確にならないと、何もわからない段階で視察ありきというのは問題があると私は思うので、今回はより以上に慎重に、できれば今年に関しては見送るのが妥当ではないかと私は思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":21323,"voices":75}},{"id":"r02-20200630-10","meetingId":"r02-cm06","date":"2020年6月30日","dateIso":"2020-06-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":969,"voices":8}},{"id":"r02-20200701-14","meetingId":"r02-cm07","date":"2020年7月1日","dateIso":"2020-07-01","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ネーミングライツについてお伺いします。だから、できることなら、私としてはやってほしくないというふうに思ったのですね。特にＣ.Ｃ.Ｌｅｍｏｎホールが非常に目立ったので、私はあのときに非常に思ったし、今回この委員会にこの言葉が出てきて、品川区でもやりたいのかなと非常に思いましたので、私は改めて思ったのですが、その点はどうお考えなのか伺いたい。","respondent":"品川財政課長","answer":"どういう形が非常に適切な方法になるかとか、そういった部分も検討しながら、やはり進めていかなければならないという点があるかというふうに思います。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"私がちょっと調べたら、京都市美術館でも５０年契約で京セラの名前を冠したという事例をたまたま発見しまして、京都市京セラ美術館と。京都市美術館だったものが京都市京セラ美術館という名前になったのだそうです。その特別の受益、利益を得ている人がその得た受益、利益に対して負担すべきだという考え方だと思うのですけれども、こういう理解でよろしいでしょうか。お伺いします。","respondent":"品川財政課長","answer":"基本的にはこういう公共施設の利用料というのは、当然使っている方については使った部分で、やはりいろいろな教室をやったりとか、スクールをやったりとか、そういうところで、本人に受益が出ているという部分で、一定部分については当然お金を支払ってもらうということで。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"私は、大昔、それこそ４０年ぐらい前は、区内の施設、地域センターとか文化センターは無料で使えたと思うのですよ。だから、区もそういう施設を増やしてきているということですから、むしろそういう施設を使うというのが特別なことではなくて、一般的、普通なことだと思うのです。そうやったとしても、多分大した費用ではないというふうに私は思うのですけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"こういうところもやはり考えていきますと、総合的な考え方としては、やはり使う方については一定の料金をいただくと、こういう受益者負担の考え方というのが必要ではないかと、このように思っております。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこいら辺を転換していく方向で頑張っていただきたいというのが私の要望です。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすれば、すごく使い勝手がいいのに、ロッカーを使うのだったらお金がかかるのですよという意識を、ロッカーを使わないでプールに入るということはまずないし、誰もが使うものですから、そういう点で言えば、そういう意識をつけたいという考え方というのが区のほうにあるのではないかと思うのですけれども、それはぜひやめていただきたいと思うのですが、いかがでしょうか。","respondent":"品川財政課長","answer":"区としてそういうニーズにどういうふうに応えていくかというところは、やはり区政運営をする中でも非常に難しいところではないかと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところからすると、やはり公共施設というのは何のためにあるのか、どういうふうに区民の中で使われるべきなのか、やはり区民の生活と豊かな活動を保障する、権利を保障する、そういうふうなところで考えていただきたい。だから、本当に取るとしても負担にならない低廉なものでぜひやっていただきたいと、そういうことでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、ちょっと委員長、確認なのですが、今日は使い方ではなくて、財源確保についてですよね。これは品川区、世田谷区、さまざま２３区の中で大分打撃を受けて、横浜市ももちろんそうですが、その辺について、やはりふるさと納税の対応策というのですか、こちらでもっと画期的なものが生み出せればいいのでしょうけれども、やはりそこが主眼になるのでしょうか。","respondent":"品川財政課長","answer":"ですので、品川区のいろいろな特筆した点を出していくような事業を、ふるさと納税の中とかクラウドファンディング等に入れて税外収入を得ていくというところは、新たな一つの手法ではないかというところで、こういった面を少し検討していきながら新たな展開を探っていきたいと。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"一生懸命ネーミングライツやクラウドファンディングをやっていて、財源を使ってやっているのだけれども、やはりふるさと納税で相当持って行かれるとなると、今までは確かにふるさと納税ありきではないけれども、返礼品競争なんかやらないのだという確固たるものが区としても方針としてあったと思うのですが、ここはそろそろ転換していかないと２年後はおそらく財源のほうも東京都から入ってこなくなったり。","respondent":"品川財政課長","answer":"競争にならないようにというふうに先ほど答弁しておりますが、返礼品についてもやはり何かもう一工夫ぐらいはつけて今後臨んでいきたいというような考えはありますので、返礼品についても当然工夫をして対応していきたいというふうに考えております。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か伺います。いつも思っているのだけれども、例えば国・都の支出金の補助制度とかがいろいろとあるのだけれども、これを宝くじだとか、例えば国なんかだったら省庁があって、その中の例えば国土交通省の観光庁があって、観光庁の補助金があるよとか、いろいろあるではないですか。税外収入というのはどういうものだという見解をしっかり区が出すべきだ。そこら辺の考え方も含めて教えてほしい。","respondent":"品川財政課長、堀越企画部長","answer":"こういった点もいろいろと考えていきながら、今後のあり方についてはやはりいろいろと検討していかなければいけないという必要性があるかというふうに考えております。それから、広告収入も同様になるかと思います。一方で、これも財政課長が答弁したものですが、区民の皆様の施設に対するいろいろな思いですとか、なじみですとか、そういうのもありますけれども、いろいろな先行事例ですとか。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"どうしてそういう意味を言ったかというと、例えば具体的に言うと、観光庁の補助金があった。それは５億円ですと。内情がわかっている。では大学はどこを引き込むか、そのときは東京海洋大学を引き込んで大分やったのだけれども、だけど、結局そういうのというのは、どこの商店街とどこがどうやってやれるのというのがあって、いや、できないのではないかと思うと、それは引き込めないではないですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"塚本委員","kind":"提案","question":"各所管から、これはガバメントクラウドファンディングでやりたいのですというふうに提案があって、それを企画のほうで認めていくというような方向性なのか、そこは企画のほうからも、これはどうだ、やってみないかと話を持ちかけるというか、勧めていくというか、その辺の考え方とか進め方、ガバメントクラウドファンディングをどういうふうに考えているのかというのをお伺いしたいと思います。","respondent":"品川財政課長","answer":"所管においてこういう内容でクラウドファンディングができないかどうかということを考えていただくというところは当然あるのですけれども、一つはやはり企画部門のほうでも個別でこういうのはうまくいくのではないかというところで。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"それと、財源確保ということからは少しずれてしまうのかもしれないのですけれども、寄附につながるみたいな話で、いわゆる民間活力、ＰＦＩだとか、ＳＩＢとかという民間の資金を使って公共事業を進めていくという考え方ということについても、最後にどのように捉えていらっしゃるのかをお伺いしたいと思います。","respondent":"品川財政課長","answer":"民間の活用という部分ですが、２０年前ぐらいからＰＦＩというような形で民間のノウハウを入れながら事業を進めていくというようなやり方が大分出てきたかというふうに思います。","id":"exchange-012"},{"speaker":"せお委員","kind":"提案","question":"私は予算特別委員会でもちょっと触れさせていただいたのですけれども、公園内や区有施設内、あと水辺といったところで、カフェとかレストラン、パン屋とか、そういった飲食店に場所をお貸しして、そういったところでさらに高齢者とか障害者とか、あとちょっと今コロナ禍で雇用が少なくなっているので雇っていただいて、雇用も増やしてもらうと。","respondent":"品川財政課長","answer":"例えば寄附額に応じて１万円ぐらいだと１年間とか、１００万円出すと永年とか、これは一例ですけれども、そういうものもちょっと見たりしております。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"補助金のところで、先ほど申請してもつかないこともあるという話があったのですが、それはどのくらいの割合であるのか。事務の手間というのはどの程度、先ほど結構大変だというお話でしたけれども、そこのところをもう少し具体的にご説明いただければと思います。私は必要ないのではないかなと思うのですけれども、もともとの財源をどう振り分けるかということが問題だと思うのですが、いかがでしょうか。","respondent":"品川財政課長","answer":"非常に大変な作業量の中で補助金を取りに行くというところが、やはり事務サイドのほうとしてはあるです。それから、税外収入につきましては、当然区として歳入が入る部分ですので、これは区の考え方としては税外収入、これは必要というふうに考えてあります。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"収入が増えるという意味では、それはお金があればその分だけいろいろできるということになりますけれども、やはり品川では人口も増えていて、今後、人口推計でも今の人口に戻ってくるまでに２５年ぐらいかかるということだったと思うのですが、そういった中で今税収も増えているというところで、現在そんなに財源を心配する必要はないのではないかと思うのですけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"全体の財源というところの目線ではなく、当然区としていろいろなところから歳入を確保すると、こういうところが大事ですので、そういった面でも税外収入は必要というふうに考えてあります。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"これは本来区がやるべきことであって、寄附で賄っていくというのは自助共助の助け合いに置き換えていくということだと思うのですね。ガバメントクラウドファンディングの活用というのは、しっかり区が事業を行って、その上でそこに上乗せをしていくということで活用していくべきだと思うのですけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"ガバメントクラウドファンディングというところは、当然区の歳入を、収入を幅広いところから得るというような形でやっているものです。ですので、より多くのところから、より多くの手法を使って歳入を得ていくと、こういうやり方をしていくという考え方です。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした生活困窮家庭とかを支援していくということで、やはりそういったところは区がそもそもやるべきことなので、区がしっかりとやるということをまず基本に据えていただいて、それにさらに上乗せをしていくという形でガバメントクラウドファンディングなどは活用していっていただきたいというふうに言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ただ、今後の人口減少、しばらく先だという話もありますが、高齢化も進んでいき、やはり民生費、福祉費というところで、非常に大きな支出が発生するという中で、民間の感覚というか、いわゆる経営の感覚というものが非常に求められてくるというところだと思います。ですから、先ほどのいわゆる助成金、補助金を取れるところはしっかり取っていく。これは区の職員の方も大分ご協力をしたと聞いています。","respondent":"品川財政課長","answer":"例えば、千本桜についても、これは完全にまちづくり部門のほうから上げてきた案でありますので、税務課だけで全部をやるというのは非常に難しいというところは私たちのほうも心得ております。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"財源としてのインパクトがないというところもありますので、ぜひそこのところは工夫をしていただきたいというところと、税外収入というところでは、今後もいわゆる体力があるから鷹揚に構えるのではなくて、これから先のことを考えて、先ほどいろいろな委員からもありましたけれども、取れるものは全部取っていくというぐらいの民間の経営感覚で臨んでいただきたいというふうに希望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"小芝委員","kind":"提案","question":"主に２点提案をします。１点ですけれども、品川区内にあります大森貝塚遺跡庭園ですが、例えば改修工事をクラウドファンディングで提案してみてはいかがでしょうかと思います。縄文時代の遺跡ということで、これが必ずしも歴史好きな人に結びつくかどうかはちょっとわからないところではありますけれども、かなり品川区のＰＲにもなるかなと思いますのでいいと思います。いかがでしょうか。","respondent":"品川財政課長","answer":"いろいろな広告物という面では、そのニーズに合ったところとか、目立つ場所とか、さまざまなところを検討しながらやっていかなければいけないなというふうに思っております。そういう部分も考慮しながら今後いろいろな、税外収入のところについても考えていきたいと考えています。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"ネーミングライツのご説明の中で、企業の地域貢献的なところの観点でのお話がありました。品川区において、いわゆる行政関連で企業の社会貢献というと、今はどのように把握をされて活動されているか教えていただきたい。","respondent":"品川財政課長","answer":"学校などにも近隣の企業から本当に多大な寄附をいただいて、学校事業に使ってくれというような形でやっているところもありますし、長年定着している企業に関しては、非常に区のことを思っていただいて。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"だんだん歴史も長くなって、このコロナ禍、今後の品川区の社会のあり方ということも含めて、一ついろいろな組織、事業を見直す契機だと思うのですけれども、ＣＳＲについても、そういう観点で、例えば本当に社会福祉協議会で事務局をお任せしていていいのかどうかということも含めて、品川区の思いも含めて、そろそろ１回お話し合いをして、発展していこうという機会があってもいいのかなと思いましたので。","respondent":"品川財政課長","answer":"そういったところをある程度の時期を見て、やはり見直しをかけていくというところは必要ではないかと思いますので、そこはまた担当所管のほうでどういうふうに考えるかというところの考え方もあるかとは思いますが、大分課題等もわかってきているので。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"提案","question":"１点だけ。反対というか、こういうこともあるのだということを頭に入れてほしいというだけ。今ＣＳＲの話が出たので、品川応援団みたいな形なわけではないですか。その方々は企業であるけれども、区民の方々、各企業がそこにあって、会社もお世話になっているということを考えるのであれば、区民の皆さんにいろいろな形で社会貢献したいということがあるではないですか。そこの会員は３００人。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"芹澤委員","kind":"確認","question":"例えば企業から今回の品川のガバメントクラウドファンディングに寄附ということができているのかというのを教えていただきたくて、担当課とちょっとお話しした際に、手続きがいろいろとあってできないというようなお話をされていたように思っていまして、そこの確認だけお願いします。","respondent":"品川財政課長","answer":"ガバメントクラウドファンディングのところで、企業からというところですが、たしか法人税の一部を寄附するとそこの部分が控除になるというようなことがあったかと思うのですが、すみません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781582?Template=document&Id=6092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":32503,"voices":52}},{"id":"r02-20200702-18","meetingId":"r02-cm07","date":"2020年7月2日","dateIso":"2020-07-02","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午前１１時２９分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"機運醸成で何ができるかということを考える上でも、いろいろ情報をお持ちの区にしっかり伺いたいと思いますので、幾つか質問します。それと、前回お伺いしたときにはご答弁があった、６月１０日に開催されたＩＯＣ理事会の件ですけれども、結果としては区はどう受け止めていらっしゃるのか、併せてお考えをお伺いしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１点目の都との連携ですが、特別区、それから東京都のオリンピック・パラリンピック準備局、それから組織委員会等を合わせたオリンピック・パラリンピックの課長会というものがあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"直近、何回か。ホッケー教室は年３回ということで、これは見ると、もともとは今年度の事業なので、オリンピックがある予定だった年の事業予算としてついていたということだと思うのですけれども、これはもともと大会中に開催する想定だったのが８月から１１月に３回と変更になったのかを伺いたいと思いますし、それとほかにも秋ぐらいに時期が変更されているイベント等もあります。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"前回は５月に開かれるということでしたが、特にそのときは議題がなかったので、流会となっています。次回は７月に開かれる予定になっております。それから、ホッケー教室なのですが、もともとは大会前に１回、終わった後に２回という予定でおりました。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後になりますけれども、具体的なところで恐縮ですが、ブラインドサッカー出前体験教室で、「新型コロナウイルス感染症の状況を見極めて実施予定」とありますけれども、この場合、出前体験ということなので、実際に参加する方が競技を行うという要素もありますし、実際、イベントをやりますと、観客の方が集まるということもあるでしょうし、若干。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"感染症の状況は日々推移しているところだと思いますので、なかなか今、“何人になったらこうだ”というようなことはお答えが難しいところですが、この辺りは、またいろいろ日々の状況を見ながら判断するというような感じです。","id":"exchange-003"},{"speaker":"こんの委員","kind":"質問・要望","question":"何点か確認させていただきたいと思います １つは、１年前どうしようか会議、２つ目にブラインドサッカー、３つ目にホッケー教室の３点について何点かお聞きしたいと思います。それから、前半と後半に分かれているというご説明がありましたけれども、１０時スタートというこのチラシ、では、一体何時ぐらいまでやっているものなのか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１年前どうしようか会議は新規です。当初から予定していたものではございません。そもそもなぜこれを開くことにしたかという１つは、やはりメインのターゲットはしな助なのです。","id":"exchange-004"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、一般の方たち向けというよりは、内容はしな助向け、あるいは周知なども、このチラシはしな助中心にお配りしたり周知したりするものなのかというところを確認と、あと、これは７月２３日ですから、もう今日は７月２日で、早めに周知してあげないととは思うのですけれども、そこら辺の周知を早めにしたらどうですかということ。そこら辺のところも教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"周知に関してなのですが、しな助はメールの配信をしています。その中でしてまいります。それだけではなくていろいろな、今まで一緒に活動してきてくださった協会の方たちとか、選手の方だとか、もちろん一般区民の方、どなたでも見ていただければと思っています。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"ありがとうございました。大体、１年前どうしようか会議の内容が具体的に分かりました。１１月なので、まだまだ先と思いきや、日程はすぐに来てしまうとなると、どのようにこれを準備されていこうとするのか、もう少し具体的に教えていただけますでしょうか。併せて、ホッケー教室のほうもお聞きします。イメージ的に湧くような、湧かないような感じなので、少しそこら辺のところを教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２点ご質問いただきました。ブラインドサッカーの１Ｄａｙ Ｃｕｐですが、委員おっしゃいますとおり、密にならないようなといいますと、入れる人数は少なくなってしまいます。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"ブラインドサッカーのほうは分かりました。そうなると、この時期もう一つ心配されるのは、新型コロナウイルス感染症だけではなくインフルエンザもダブルで来る時期かと思います。ホッケー教室のほうも分かりました。お家の中にある道具でもできると先ほどご説明がありましたけれども、ぜひいろいろな工夫でオンライン教室を開催していただきたいとの要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"ご説明、ありがとうあります。何点かお聞きしたいのですけれども、１年前どうしようか会議、しな助向けですけれども、そういったいろいろな活動をやってもらう中で、今、たしかしな助のほうは、窓口を締めたのですよね。もうしな助の募集はしていないのですよね。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しな助の応募については、特にまだ締めてはいないのですが、今の時期ですと、なかなか新規に入られる方は増えない状況です。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"それと、先ほどしな助の今後のことにつきまして、年代別にアンケートをとっていくというお話がありましたけれども、そういったアンケートをとって、まだ先の話ですけれども、今後、しな助をどういった位置づけで考えていくのか、方向性があれば教えていただきたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それに基づいて、アフターオリンピックに対するキャリア研修を開きたいと考えています。しな助は、東京２０２０大会に向けた機運醸成のための集まりですので、大会が終わった後は、しな助という形での継続はなかなか現状では難しいと思っています。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"確かに５００名近いボランティアがそのままいなくなってしまうのは非常にもったいないので、しっかりとそういった形で残していただけたらと思います。最後に、聖火リレーは中止になりましたが、あれは来年度に向けたときに再募集するのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"聖火リレーについてのご質問です。聖火リレーは来年に延びまして、今決まっている方に走ってもらうということで、新たな再募集はないと聞いております。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"すみません、直接的に機運醸成のことについては関係ないのですけれども。ブラインドサッカーを荏原第六中学校で練習されていたと思いますが、現状はどうなっているのかお伺いしたいのです。もしお答えできるようでしたら、お願いしたいのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今現在は新型コロナウイルス感染症の関係もありまして、日本代表の選手の練習はずっと休止されておりました。委員ご指摘のとおり、以前は荏原第六中学校の校庭を使って練習していたのですが、今現在はそちらのほうは休止しております。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"新型コロナウイルス感染症の影響によって練習を休止したということですけれども、では、休校に入る前からだったのか、いつ頃から練習が休止になったのかをお伺いできればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"荏原第六中学校の練習に関しましては、新型コロナウイルス感染症の影響がある前から一旦休止をしております。今はまた休止になっているのですけれども、今、立会小学校のほうを使わせていただいて練習をする形になっております。","id":"exchange-012"},{"speaker":"田中委員","kind":"確認","question":"荏原第六中学校から立会小学校に移動することになったのは、新型コロナウイルス感染症の影響ではなく、何らかの理由があって行われて、現在、立会小学校でも新型コロナウイルス感染症の影響で休止しているということなのですか。その辺を確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、荏原第六中学校から立会小学校に代わったのは、新型コロナウイルス感染症とは直接は関係ございません。今現在は、やはり新型コロナウイルス感染症の関係もございまして立会小学校でも練習はしておりません。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明、ありがとうございました。それで、まず確認をさせていただきたいのが、現状、品川区の中にありますホッケー会場が、今、どうなっているのかが１点と、ＹｏｕＴｕｂｅ配信ではこのゲストの方たちはそれぞれがオンラインなのか、このゲストの方たちが１つの会場に集まって、そこが一つの発信場所になっているのか、そのやり方を教えていただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"会議の会場ですが、参加者は１つのところに集まって、おしゃべりをしているところを配信する、そのような予定になっております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"担当部署として、土・日も含めていろいろなイベントにも出ていただいて、大変にご苦労だったろうと思うと、機運がそがれたところなのですけれども、これから新たな気持ちで、また区民の皆さんに機運醸成ということで頑張っていただきたい。これをお願いしておきます。委員会に出ていなかったので分からないのですけれども、例えば設計費用とかそこら辺まで手配していたのかどうか。それをまず教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しながわハウスについてのご質問です。こちらはスポル品川大井町を借りて開く予定で、仮設のテント等も設置する予定です。委員がご心配されているとおり、こちらはかなり時間がかかるものです。建築確認も取らなければいけないということで、これは一定程度、進んでおりました。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そのことに費用がかかるのは仕方がないと思うので、それはぜひ通常どおりの支払いでやっていただく中で、これは逆に、来年に向けてここの場所がまた新たに設置ができるのかどうか。手続きしたことによって建築確認を１回取っておけば、そのままいけるはずですよね。今年やったものが来年に向けて活かしていけるのか、その辺はどうなのですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"来年に向けてというご質問です。組織委員会のロードマップの中にもありましたが、あまりお金がかからないような簡素な形でという方針に転換したということもあります。区の財政としても、なかなか今、予定していた規模での実施は厳しいかなという実感をもっております。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ありがとうございました。規模縮小ということがあるから、かなり難しく、これからどう考えていくかということは、部署として考えても大変だと思うのですが、その辺、改めて頑張っていただきたいということで要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"渡部副委員長","kind":"確認","question":"しながわハウスは、今の状況も聞き、確認はできましたけれども、その他の事業において、基本的には今年度は中止になっているのだけれども、来年度に持ち越しで今回中止と出ているものはやっていけるのかどうなのかがまず一点です。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１年延びたことで、実は機運醸成のイベントは私どもオリンピック・パラリンピック準備課だけではなく、子ども関係のところですとかいろいろなところで予定しておりましたところ、１年延びてどうするのかということで、今現在はどこの課もできない状況です。","id":"exchange-018"},{"speaker":"渡部副委員長","kind":"質問","question":"状況に応じて、それぞれよろしくお願いします。やはり今の段階では、１０月、１１月まではやることが前提で動いてほしいというのがあって、そこは盛り上げていきたい。これはもう出来上がっているわけですから、例えばですけれども、組織委員会のオーケーが出るのであれば、区民対象に開放することはできないですか。例えば潮風公園のほうでも、真っさらではなくてある程度仮設が進んだわけではないですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"潮風公園のほうですが、現状としては、今、６割方施設ができている状況です。６割方ということは、まだ工事があるので、子どもや一般の方が入って安全な状況なのか、そこが一つのポイントかと思いますので、その辺を確認しながら進めていきたいと思います。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"１３番に書いてあるのですけれども、あれは国からでしたか、４つの種類のフラッグ。１３番に書かれていることはそうしたことも含めた新しいものを作るだとかということでしょうか。先ほど来言っている世界的な状況がどうなるのかというところも含めてなのでしょうけれども。メインのデザインは変わらないのでしょうけれども、その辺、分かれば教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１年延びたということで、もう一度、どこに付けるのが適切かということも含めまして検討をしていくです。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。だから、何だかんだ言っても、怖いですよね。実際、今、オリンピック・パラリンピック準備課にどのような声が届いて、今一生懸命やっていただいていることに対する応援だったり、また意見だったり、主なものでいいですが、教えていただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その辺を含めて４コマ漫画をやってみようということで、私どももいろいろな批判とかが来てしまうかと思ったのですけれども、応援も批判も特に何もなくて、逆に寂しいといいますか、もう少し反応がいただきたいという。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"前回の委員会でもその辺を確認したり、教えていただいたりしたのですけれども、今のこうした温度差だとか、現実の状況だとか、そうしたところも含めて、なおかつアスリートの方、元アスリートの方とのつながりが強いところを活かして、正直、私も疲弊し切ってきた部分がありますので、本当にどうなるのだろうという中での現実対応もあるので、例えばアスリートであるからこそのメンタルトレーニングだとか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ＳＮＳを通じまして、私どもの職員のホッケー元日本代表の方を中心に、今までは家で簡単にできるストレッチ、それから筋力トレーニング的なものを発信してまいりました。","id":"exchange-022"},{"speaker":"つる委員","kind":"意見","question":"家の中でこもり切っている中でも、みんなとつながれているというその連帯感は、まさにこのようなＳＮＳ等で発信することによって、離れているけれどもつながっている、それがまさに演出できるのかなということで、ぜひそうしたところも、今度の１年前どうしようか会議でもトークテーマの１つに入れてもらうとか、形はどのような形でもいいと思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"この１年前どうしようか会議を開くという情報も、多分、ホームページでもお知らせするのだと思うのです。それを機にオリンピック・パラリンピックの情報をホームページにも掲載されていくのかと思うのですけれども、その辺、スケジュールはいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはり昨今のように暑い日にずっとマスクをしている状況で、その辺りの新しい注意喚起のこともありますので、区のホームページは今現在、カウントダウン表示は載せる予定はございません。","id":"exchange-024"},{"speaker":"湯澤委員","kind":"質問","question":"競技について興味をもっていかないといけないという中で、今、各委員からもご指摘がありましたけれども、オンライン配信とかケーブルテレビ品川でお伝えするとかで、例えば競技についてもそうですし、あとは選手、それから監督、こういった方々に取材していって、このような選手がいる、このような監督がいるのだということを、区民の方、それから区民だけではなく日本中の方に知っていただいて、それで。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"どのような形でできるかは分からないのですが、今までも選手にインタビューするなど、私どものホームページでは幾つかやってはいるのですが、ホームページに見に来る人はもともと興味のある方ということで、それほど興味がない方にも。","id":"exchange-025"},{"speaker":"湯澤委員","kind":"意見","question":"それと同時に今回は、新型コロナウイルス感染症の対策も必要になるかと思うのですけれども、選手もそうですし、それから、それを見ていただく観客の方々、スタッフの方もそうですけれども、そういった方々に、この会場は感染拡大防止のためにこれだけしっかりやっているのだというアピールを、例えば動画配信をするのであれば、アピールしていけばいいのではないかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、キャナルアートモーメント品川２０２０というイベントは、どういった内容のものですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これを当初は、パラリンピックが行われている８月２９日から３０日に行いまして、パラリンピックと日本文化、それから品川区の文化を世界中にアピールする予定でございましたが、それを時期をずらしてやっていこうというものです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。たとえ実際に人を大量に集めることができなくても、そうしたオンラインでの配信をぜひやっていただきたいと考えております。こうした気持ちが落ち込んでいる今だからこそ、日本舞踊とか文化に触れて、少しでも癒しにつながればいいなと考えておりますので、ぜひそうしたオンライン配信もやっていただきたいと考えておりますけれども、実際その辺りはどのようにお考えなのかをお知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今現在計画している中では、オンライン配信は含んではおりません。ただ、新型コロナウイルス感染状況等によっては、そうも言えないというような状態になる可能性もありますので、そういった場合にはオンライン配信も検討の俎上に上がってくるかとは思っているところです。","id":"exchange-028"},{"speaker":"西村委員","kind":"提案","question":"ありがとうございました。皆さんおっしゃっているのですけれども、１年前どうしようか会議は、私もすごくすてきだと思いまして、イベントですとかトークショーではなくて「会議」となっているのがすごく面白いと思っています。手詰まり感というか、なかなか私たちでは考えられないようなアイデアもいただけるのではないかという期待も込めましてご提案します。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"事前に質問を募集するつもりでおりました。その中にアイデアを募集するのもいいかなと思いますので、検討したいと思います。それから、自己ベストを目指す取り組みです。実は、外国人おもてなし語学研修は品川区でもやりました。","id":"exchange-029"},{"speaker":"西村委員","kind":"意見","question":"スポーツの祭典ではありますけれども、文化、語学、手話も、何かみんなで目指していき、レガシーとしてみんなの心に残るような取り組みが、オンラインを通してでもできるのではないかと思いますので、期待を込めまして引き続きよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"木村委員","kind":"意見","question":"今回、東京２０２０大会が新型コロナウイルス感染症で延期になった。今回、２回目の東京オリンピックということで、１回目は私も小学校の頃に体験をしているわけですが、これを見ました。このチラシにもあるように、１年前どうしようか会議ということでありますから、これをいいほうに捉えて、１年間増えたわけでありますから、これをどのようにプラスに替えていこうかと考えることができるかどうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１年延びたことは残念なことではありますが、今、委員がおっしゃいましたとおり、このピンチをチャンスとしてどうやって取り組んでいくかということが、私たち行政にも問われているところだとは認識しております。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706411?Template=document&Id=6578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":27045,"voices":82}},{"id":"r02-20200707-10","meetingId":"r02-cm07","date":"2020年7月7日","dateIso":"2020-07-07","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":9245,"voices":50}},{"id":"r02-20200819-6","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"区民委員会","time":"午後 １時００分～午後 ２時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","topics":[{"id":"topic-01","title":"令和２年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和２年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"昨年は新規が３つ、２つが２年目ということで、最大３年の中で、結局この５つに関しては、今年度継続と。その工夫してきた結果、年々増えて、この助成事業は伸びていると。そういった中で、今年これだけ減ってしまったことに関して、ある意味反省というか、今後増やしていくべき方向性に向かっていくために、何か方法であるとか、現段階でどういった形で検討しているのか、そこの部分をまずお聞かせください。","respondent":"宮澤協働・国際担当課長","answer":"今後、団体数を増やすに当たっての周知の部分につきましては、広報しながわやホームページ等で事業説明というのはしているところですが、すまいるネットが来年度からリニューアルするので、それを機に改めて見ていただく方、閲覧する方を含めて。","id":"exchange-001"},{"speaker":"くにば委員","kind":"質問","question":"今おっしゃった形で、相談に来たけれども数件に関しては辞退ということでした。昨年度は応募が２７件あって、申請書を書いてやり取りしたのが２２団体、最終審査が１５事業というふうに、昨年度の答弁の中であったのですけれども、今年応募自体は何件あったのでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"事前の相談、説明会というのも開催しましたが、４月のタイミングでしたので電話でお問い合わせがあったり、こちらからもかけたり、電話でなるべく済ませるような形にしました。ですので、説明会にいらっしゃったのは２団体、２名という形になっております。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"せっかく４００万円から５００万円まで助成総額を上げたという思いがあるはずなので、そこに関して現状、何かコロナ禍でも次のバックアップ体制というか、こういうふうにしたらいいのではというアドバイスであるとか、そういった方法は何かお考えにあるでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"来年度に向けて今の状況の中でできる範囲としまして、伴走的な相談体制という形で、ＮＰＯを支援するＮＰＯ、こちらに委託をしまして、相談というのも個別に受けてお話しさせていただいています。","id":"exchange-003"},{"speaker":"くにば委員","kind":"提案","question":"最終的にすまいるネットに登録している団体のみがこちらの対象ということなので、例えばすまいるネットのホームページのほうに、先ほどおっしゃったコロナ対策、オンラインで開催するとか、今のコロナ時代においてどういった形でボランティアであるとか、こういった動きをさらに継続していく方法、そういったものをすまいるネットで、例えば広報として区からの提案として掲載するなり。","respondent":"宮澤協働・国際担当課長","answer":"すまいるネットのリニューアルを、来年度に向けて今、構築しておりますので、その中でそういった周知という部分も考えていきたいと考えています。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"今、すまいるネットの話が出たのですけれど、すまいるネットに登録している団体数はどのぐらいになるのでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"登録団体数は５３４団体です。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"その意味で、すまいるネットに登録している人たちというのは、ある程度広報があれば分かるのかなと思うのですが、それ以外のこれから活動しようとしている人たち、活動している人たちに、どう広報するのかというのが大事なのではないかとも思うのです。その辺り今年度、具体的に広報手段として何をとられたのか、お願いいたします。","respondent":"宮澤協働・国際担当課長","answer":"区民活動助成制度の周知方法につきましては、広報しながわ、区ホームページで周知したところです。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"これはほかでもよく申し上げるのですが、せっかくツイッターの公式アカウントがあるので、そこでできればやっていただきたいというのと、せっかく今年からＬＩＮＥも、公式アカウントができたかと思いますので、そういったところで広報していただきたいというのは、要望としてあります。","respondent":"宮澤協働・国際担当課長","answer":"今年度につきましては、説明会は直接区役所の会場で開くという形で、その後の個別相談会につきましては、直接いらっしゃった団体もありますし、今年度から一応オンラインで相談というのも取り入れて、やりました。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"個別の相談はオンラインということで、先進的にやっていただいているなと思いますので、始めの事業説明の相談会も、オンラインという選択肢もできればご検討いただければと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"２ページの、学識経験委員１名はどのような方でしょうか。有識者委員２名はどのような方でしょうか。公募委員は公募された委員、あと区の職員ということで、いいと思うので、まず学識経験者と有識者を教えてください。","respondent":"宮澤協働・国際担当課長","answer":"続いて有識者委員２名のうち、お一人につきましては、東京都社会福祉協議会の、東京ボランティア・市民活動センターの職員の方にお願いしております。もうお一人の方につきましては、中小企業診断士の資格を持つ区の商工相談員の方にお願いしているものです。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"審査委員会が開かれたと思うのですけれど、この方たちに対しての謝礼というのですか、支払われているのであるならば、その金額を教えていただけますか。","respondent":"宮澤協働・国際担当課長","answer":"公募委員も含めまして、委員の方につきましては謝礼を支払っております。金額につきましては後ほどでよろしいでしょうか。調べます。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる常連さん、今までやったところが２回、３回という形でいただいているということではないですか。それで新規もない。もちろん部長、課長も含めてという形でやれば、謝礼とかかからないではないですか。そういう意味で、コストパフォーマンスを含めて１００万円以下の助成に関して、ここまでやる必要があるのかなという思いがあるのですけれども、その辺についてはいかがですか。","respondent":"宮澤協働・国際担当課長","answer":"ただ、地域振興基金を活用しての助成制度ということで、区民の皆様から広く寄附をいただいている基金を原資としますので、支出に当たっての審査につきましては、区職員２名を含めて、学識経験者や有識者、公募委員の方の意見を踏まえて、実施するべきと考えているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"やはり育成も大事ですからね。せっかく学識経験者、有識者の方、今、どういう方ですかという質問を最初にさせていただきました。だからそこも含めてという形で、だから金額等でなく、これから育てていくということも含めてやっていくのだということをきちんと、今、答弁でいただきましたけれど改めて、そういうことにも力を入れていっていただきたいと思うのですけれど、いかがでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"今後の活動に当たっての育成という部分、区民活動助成制度を含めてまた個別の相談による支援というのも含めて、充実を図っていきたいと思っているところです。あわせて、先ほどの委員のご質問の謝礼につきまして、回答します。失礼いたしました。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"２万３,０００円と、１万４,０００円掛ける４ですよね。そうすると８万円に少し欠けるぐらいのお金がかかるわけですから、そういう方々に来ていただけるのですから本当に活用していただいて、また区民委員会でこの政策というのは毎回のように報告が出てくるので、あのときはああだったけれども、今はすごいのですよ、応募が３桁に行きました、もう審査していくのが大変なぐらいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどすまいるネットの登録団体が５００を超えているということで、この団体の活動状況というのは把握されているのでしょうかということと、把握しているのであれば、このコロナで休止しているところ、もう解散というかやめてしまったというようなところは、把握されているのでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"しながわすまいるネットの登録団体５３４団体ですが、各団体が情報発信をしておりますが、その各団体の活動状況までは、全てを細かく把握しているということはございません。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、この助成制度を使って活動してきた、昨年であれば１２事業が選定されたわけですけれども、その事業団体は今どうなっているのか。この申請してきた６事業は続いているということなので、活動中というのは分かるのですけれど、そのほかは休止ということなのでしょうか。休止してしまっている、もう解散してしまったというところはどれだけあるのか、伺いたいと思います。","respondent":"宮澤協働・国際担当課長","answer":"令和元年度に採択された事業で、先ほどの説明でございましたが、助成の種類として３年度にわたっての助成になりますので、昨年度が３年目の助成だったところは今年度引き続きの助成はないのですが、１年目、２年目で今年度申請がなかったところにつきましては。","id":"exchange-015"}]},{"id":"topic-02","title":"「五反田バレーアクセラレーションプログラム」Kick-Offイベントの開催","agenda":"「五反田バレーアクセラレーションプログラム」Kick-Offイベントの開催","exchanges":[{"speaker":"松本委員","kind":"意見","question":"こういった事業なら創業前の段階で入ってこられるというのも大事かなと思いますが、その辺りはどういうお考えなのか、お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる創業前の段階から５年以内と、確かに結構幅広くなっているところはありますけれども、なかなかやっていく中で、完全にもう事業として計画していて、きちんとなっていると、それが進みそうだというところであれば。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"質問する前に、この五反田バレー、ここまで来たのかと思ったことがありまして。それと質問ですけれど、そもそも論ですけれど、これは品川区の事業なのですか、それとも品川区がバックアップというか助成をしてやる事業なのですか。事業の主体はどこなのですか。どういうふうに関わっているのですか。","respondent":"遠藤商業・ものづくり課長","answer":"品川区の事業なのですけれども、多くのところが関わってやっていただく、協業といいますか、それぞれの会社が持っているミッションなどがありますので、そういうところでいいものを出し合って、一緒にやっていこうということで。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"問い合わせ先が株式会社キャンパスクリエイトとなっているのですけれども、なぜこういう形になっているのかという説明をしていただきたいのが１点。もう１点は、一番最初に品川区が入っていて、３番目にＷｅＷｏｒｋが入っていますね。これはどうしてか、教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"それからＷｅＷｏｒｋにつきましては、コワーキングスペースを運営されているというところで、やはり大手とスタートアップのマッチングというところに大変興味を持っていらっしゃるということで、お声をかけたところ。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"なぜ伺ったかというと、ＳＨＩＰと事業内容が、ＷｅＷｏｒｋもそうですよね、スペースをお貸しして、ＳＨＩＰもスペースをお貸ししてという形なので、さすが心が広いというか、品川区はすばらしいと思うのですが、いい意味のライバル同士でもあるし、なぜ今回こういうふうに入れたのかなという思いがあったので、改めて質問させていただいたのですけれど。全体という意味でやるということで、いいのですよね。","respondent":"遠藤商業・ものづくり課長","answer":"特別な線引きをしているわけではないですけれども、もちろん広がれば広がるほど、品川区の中で広がればいいなとは思っておりますので、現状は東五反田と西五反田と分けることなく進めていければということは思っているところです。","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"１点まず伺いたいのが、今回はこのアクセラレーションプログラム全体の、チラシ裏面のプログラム（予定）のKick-Offイベント開催という部分の予算、経費７９７万円余りということは、Kick-Offイベントのみでの経費でしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"記載のほうが、申し訳ございません、こちらは全てのイベント、先ほどの運営とか、募集とかも含めての経費が８００万円弱という形になっております。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問","question":"このプログラムの最初のKick-Offイベントから、８項目ずっと実施日があって、最後のＤｅｍｏ Ｄａｙまで含めた全部のパッケージとして、品川ビジネスクラブのほうに７９７万円を丸ごとという形でしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"はい、そのとおりです。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問","question":"分かりました。ではこの約８００万円の経費の内訳というのは、把握なさっているという認識でよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"先ほどのプログラムの部分で、全体の企画と審査、申請の受付部分につきまして約２５０万円、Kick-Offイベントから研修、Ｄｅｍｏ Ｄａｙまで含めたものが大体４７０万円程度、そのほかで広報関係の経費が７５万円、トータルで８００万円弱という形になっております。","id":"exchange-022"},{"speaker":"くにば委員","kind":"意見","question":"内訳ありがとうあります。主にプログラム（予定）を見ると、場所に関しては基本的にＳＨＩＰを使うということで、会場費がかかるというイメージはないのですが、主に後半のほうの４７０万円という部分で、何の経費でそれぐらいかかるのか不明で、もう少し詳しくお聞かせいただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"残りの部分につきまして大体３００万円程度というふうに、内訳としていただいておりますが、その中身がどういうふうになっているかまでは、すみません、把握できないところです。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"分かりました。そのくくりの一つのメンタリング、９０万円ぐらいとおっしゃるのは、何がそれだけかかるのか、もう少し具体的に、金額がとても気になっているので教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"メンタリングは個別相談になりまして、実施日の記載のとおり３日間に分かれて２０社に対してやるということですので、１社が大体５万円弱ぐらいという形で考えて、それで大体９０万円、１日３０万円という形で見込んでおります。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"ではコンサルタント費用的な形で、１社当たり幾らという形のおおむねの見方ということで、分かりました。それでこちらのＣｒｅｗｗ株式会社は、こういった同様のイベント、オープンイノベーションプログラムの開催回数１７０回ということで、様々行ってきている中で、今回品川区とのタイアップでやるのは初めてになるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"品川区でやらせていただくのは、Ｃｒｅｗｗは今回初めてです。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"分かりました。では今回初めてということで、スケジュールのほうは最終が来年３月１７日までで、今回の事業は最終的に評価が出ると思うのですけれども、これはぜひとも、こちらのイベントが問題なく、プラスアルファでいろいろな、今回２０社ということで決まっておりますけれども、さらに来年度以降につなげていけるような形で、現在その検討をなさっているのでしょうか。最後にそれだけお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"Ｃｒｅｗｗ株式会社は１７０事業会社とオープンイノベーションプログラムを実施、５５０件の協業をやってきたというところで、特別区では私ども初めてやらせていただくのですが、別の地域、西のほうだったかと思いますけれども、では既に実績を上げているところです。","id":"exchange-026"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１つだけ、もしお許しいただけるなら、しながわ活力応援給付金について確認したいことがあるのですけれど、よろしいでしょうか。課長がいらっしゃるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"１点だけ確認させてください。確かに同意しますかというふうに書いてあるのだけれども、１０万円の給付金の情報をそのまま使ってしまっても、本人が同意してチェックすれば、使っても、いわゆる法律的、条例的には問題ないのか、それだけ確認させていただけますか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"今回申請書の振込口座欄のところ、国の１０万円の特別定額給付金と同じ口座を希望される方は、レ点を付ければということで、委員がおっしゃったとおり、まず申請書のところに活用することを同意していただくということで、同意事項欄を設けさせていただいて。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"今のしながわ活力応援給付金なのですけれども、発送がもう８月上旬ぐらいからされていて、その後の初めての委員会なので、報告としてこの委員会であってもよかったのかなと思うのですけれども、そこは特に今回、報告事項に挙がらなかったというのは、何か事情があるのでしょうか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"８月５日に申請書を発送させていただいて、今、鋭意、順次進めているところです。始まったばかりのこのタイミングですので、改めてご報告しますので、よろしくお願いします。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"結構いろいろと、我々も要望とか質問とかを受けていますので、ぜひ早目のご報告をいただきたいと思うのと、あと先ほどＬＩＮＥの話をしましたけれども、今回ＬＩＮＥを活用していただいているというところで、これはかなり、逆によかったというふうな区民からの声もいただいていますので、ぜひ引き続き、こういった先進的な取り組みをしていただければとお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2876#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":18442,"voices":75}},{"id":"r02-20200819-7","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"厚生委員会","time":"午後 １時００分～午後 ４時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)から先に行います。 それでは、(3)品川区がんの夜間相談窓口事業の開始","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)から先に行います。 それでは、(3)品川区がんの夜間相談窓口事業の開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"場を重視する相談の場ですから、これは例えばファクスや電話などでの相談は多分受け付けていないような気がするのですけれども、その点はいかがなのでしょうか。だとすると、どういうところなのか。その辺のところをもう少し伺いたいというのがもう一点。それから、それと重なるような質問ですけれども、相談に見える方ですけれども、どういう方を対象に、念頭に置かれているのかということが３点目。","respondent":"高山健康課長","answer":"２点目の、マギーズ東京を選んだポイントですが、資料にも書かせていただきましたが、夜間の相談ということで、日中お仕事を持たれている方なども訪れやすい時間帯であること、また、冒頭申しましたように、昨年度、「品川区がん対策推進計画」を策定する際に。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"同じ相談をしてもいいし、それプラスアルファもあると理解したのですがよろしいですか。そのプラスアルファというのは、場の提供というか、雰囲気みたいなもの、プラス夜間もあるということなのですか。そういう理解でよろしいのでしょうか。","respondent":"高山健康課長","answer":"訪れていただくと、一番に雰囲気の違いというのが伝わった、思ったと書いておりますけれども、そもそも、この創設者の思うところの空間づくりというのを大変きめ細やかにされている点から、やはり、同じ相談と一口に言っても、しつらえといいましょうか。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"がん研有明病院なども近いものですから、そこでがんを宣告されている方も当然多いのですけれど、近くの病院で宣告された方がそのまま、頭が真っ白のままそこに行くような、そこでゆっくり、じっくり話を伺わせていただけるような、やはり病院や相談センターとは違うところでの、昔の意味とは違う緩和ケアの施設。以上です。","respondent":"高山健康課長","answer":"それから３点目の、区民に限定してかという点が、なかなか難しいところではあるのですけれども、先ほど説明の中でも少し触れさせていただきましたが、もともとのこの施設の成り立ちの、予約不要で、どなたでもというような趣旨は大事にしたいと思いますので。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"意見","question":"では最後に１点。２点目のアクセスのところだけ。車では私も行ったことがあります。電車も近くにこういうものがあるということで、ここは本当に豊洲市場の目の前なのです。バスとか、いろいろな手段が多分考えられるとは思います。区民の方が利用しやすいように、ぜひアクセスも分かりやすく提示していただければと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-02","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"１.保健所の（１）、相談センターに来る主な相談内容というのが、前回の同じ形式の報告書よりも、何かちょっと、せっぱ詰まったというか、深刻な感じになっているような感じを私は受けたのですけれども、患者の管轄保健所から濃厚接触者になると言われており、品川区からの連絡を待っているというのは、待っているのだけれども、なかなか連絡が来ないというような感じで。","respondent":"鷹箸保健予防課長","answer":"体制についてですが、現在、新型コロナウイルス感染症に対応しているのは、医師が１人、保健師は、８月から増やしていただきまして、常勤が４名、会計年度任用職員が４名、派遣の看護師が電話相談センターも含めまして１７名で対応しております。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"それから４の（２）にはＰＣＲ検査センターのデータが挙がっています。そうすると、８００人弱というのが、大体、ほかの品川区内の検査をする大型の病院でやられていると考えていいのでしょうか。８００人を、大体３院でやられていると考えて、注にある抗原検査とか唾液ＰＣＲ検査というのは、大型の３院、３つの病院でやられていると、この表を見るときに考えていいのでしょうか。","respondent":"鷹箸保健予防課長","answer":"委員のご質問のとおり、毎週火曜日、ホームページに最新版を更新している、品川区における新型コロナウイルス感染症患者数等についての検査の陽性率等の変化を出すベースとなります検査の対象人数につきましては、品川区のＰＣＲ検査センターのほか。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"これは、報告書のほうにある、８月１１日現在の６６８人とは若干ずれていて、全体が６００人弱というようなグラフになっているのですけれども、この６００人弱のそれぞれの内訳の数字は公表はされていないのでしょうか。それから気になるのが、死亡者というのはグラフで見ると全然分からないのですけれども、一人もいないという理解でよろしいのでしょうか。","respondent":"鷹箸保健予防課長","answer":"そのつもりで見ますと、５月８日から２９日までのところの基線の黒が少し黒いのですけれど、ここに含まれております。最近では８月１４日にお一人亡くなっています。合わせて５名の方が品川区の対応の方です。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問・要望","question":"濃厚接触者として検査を受けたのは何人なのかというのをお教えいただきたいというのが第１点です。それから第２点として、いろいろ調査・指導をなされたということは伺っているのですけれども、その調査・指導を何人の体制で何日間にわたって行われたのかをお教えいただきたい。最後に、ほかに同様の地域が品川区内であるのか、ないのかということもお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"それ以外の方は区外の方でしたので、それぞれお住まいの自治体に検査の依頼をしております。特定した２５名以外の一連のお客様等特定できない方については、我々が把握した中で、おおむね２５名程度ではないかと考えております。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"私からは３点伺いたいと思います。それと、そういうところと意見交換していると、東京都の委託ということなのですかね。もしくは自分で行くこともある。そこから先の話ですが、ではどうすればいいのかということは、品川区で考えられるのですか。それとも東京都が考えなければいけないことなのですか。何かお考えがあれば、またそこの考え方について教えていただければ。３点お伺いします。","respondent":"鷹箸保健予防課長","answer":"唾液のＰＣＲ検査を実施していただくということで、お願いできている医療機関の数ですが、詳しい場所その他はお教えできませんけれども、少なくとも私どもが把握している中では十数件で、結構な数の医療機関にご協力いただけております。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"そうすると、２つ目の質問のＣＯＣＯＡの内容ですけれど、これは今、ＣＯＣＯＡから接触通知が飛んできました。そうしたら、保健所とすれば、まずはほとんどというか全て、ＰＣＲ検査につなげているという認識でいいんですか。","respondent":"鷹箸保健予防課長","answer":"それを否定する根拠はまるでないので、お回ししています。その数もかなりの数です。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"ＣＯＣＯＡから飛んできている数、相談件数は分かりますか。それは、ＣＯＣＯＡからの相談ということで何か取っていますか。それだけ教えてください。","respondent":"鷹箸保健予防課長","answer":"ＣＯＣＯＡがちゃんと動くようになったのは、ＨＥＲ－ＳＹＳが動くようになった８月３日以降なのですけれども、ＨＥＲ－ＳＹＳで飛んできたものを、その陽性の患者が登録していないと、これは動かないので、我々が、その方が登録しているかどうかを聞いて、そうすると。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"逆というのは、それは国のほうの仕組みのものなので、厚生労働省の相談センターに連絡してくださいと言われましたと。それで今、ＰＣＲ検査をするように勧めるということを伺ったので、逆に言えば、その方には、もう一回、保健所にそういった状況を説明していただいて、具体的な状況を説明していただかないといけないのでしょうけれど、それでやはりＰＣＲ検査のほうにということになれば検査できるのですか。","respondent":"鷹箸保健予防課長","answer":"そういった意味では、システムそのものがきちんと動いておりませんで、それに登録して戻ってくるというと、その１週間後ぐらいからようやく動いたと思いますので、その端境期の方につきましては、残念ながら我々のほうで対応がしっかりできていなかった可能性があります。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"あまり具体的に、何日にこういう連絡が来て、こういう方ですと言ってしまうと、ちょっとあれなので、ここでお話しはできないですけれど、承知しました。ご相談があったら、今のように対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"何点かお聞きしたいのですが、まずＰＣＲ検査センターのことですけれども、月曜日から木曜日までで、一番初めは１日１５件というところから始まったのが、今これは、平均でも５５人ぐらい来ているということになると思うのですが、最大何件ぐらいまで取れるキャパシティーがあるのかということと、今でも多分、月曜日から木曜日までということになっていると思うのですが、そうすると。","respondent":"鷹箸保健予防課長","answer":"唾液のＰＣＲ検査の検査機関ですけれども、既に医師会を通じて東京都と契約しておりますので、行政検査の対応が可能でございまして、そこで、そのクリニックの院長先生が、この方は行政検査が必要と考えられた場合には、そちらで行政検査の実施が可能という体制になっております。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"唾液検査が十数カ所でできるということは、「品川区における新型コロナウイルス感染症患者数等について」というグラフで、唾液検査の総数が不明のため、実際の陽性率は低い可能性がありますということで書かれているのですけれども、そのような行政検査ということでやられたものも把握することができないということになっているのか。その点についてお願いします。","respondent":"鷹箸保健予防課長","answer":"ですが陰性の方が含まれていませんので、これは見かけの陽性率の可能性がありますということを、このグラフでご説明している形になります。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう一つお聞かせいただきたいのが、先ほど、おくの委員からもあったのですが、死亡者の数は５名ということで言っていただいたのですが、このグラフの最新のところでの７１２名というところで分かったら教えていただきたいのですけれど、自宅療養者と宿泊者、待機者、入院者の実数を教えていただけないでしょうか。","respondent":"鷹箸保健予防課長","answer":"ほかの感染症で、例えば腸管出血性大腸菌ですと、潜伏期間の２倍までで発症がなければ終わりという考えがあるのですけれど、この病気の場合、それもありませんので、終わりましたという報告は非常に難しいかと思います。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうところで言えば、今、厚生労働省でも、検査に対してかなり積極的に、体制を強化するという方針を出していると思うのですが、そんな中で、エッセンシャルワーカーと言われるところに対して、定期的なＰＣＲ検査というのを、千代田区は介護従事者に行うということを、先日、報道されておりましたけれども、そういうところでも、品川区としても、やることができないかと思っているのですが。","respondent":"鷹箸保健予防課長","answer":"品川区として、例えば他の自治体のように定期的な検査を実施するという方針、そういった考えは、少なくとも現時点ではありません。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は改めて、そこのところはぜひ、そのときだけと言われますけれども、そういう形で徹底して検査を増やすことによって感染者が分かれば、感染者が隔離・保護されるというところで、そういうところがどんどん広がっていくのが、感染を押さえ込むということにもつながっていくと思いますし、エッセンシャルワーカーの方々が本当に安心して働けるというところでは。","respondent":"鷹箸保健予防課長","answer":"その後も残業は続いているところではありますが、それを軽減するために、例えば、来週から派遣の事務を入れてもらうとか、派遣の職員を増やし、また今回８月から、会計年度任用職員の保健師を３名増員ということで新たに雇っていただきましたので。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"特に、何度も申し上げているところですけれども、品川区は、もともと保健師の数が本当に少なくなっておりますので、これを教訓にして、ぜひ保健師の増員、それから保健所の体制強化ということで取り組んでいただきたいということで、要望させていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"それで、検査のご案内をした後、受けたかどうかというところまでの把握は実際はしておりませんが、受けなかったという方をこれまで聞いておりませんので、そこで陽性だった方は発生届が出るという形で対応しているところになります。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"クラスターのところですけれど、区内の濃厚接触者２０名で１４名の陽性者という。２０名ではない。その辺の、何名検査をした中で１４名の感染者が出たのか、そこのところをお聞かせいただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"その中で検査をした１７名だとか、そういうことではありませんので、明確に何名までやったから分かったということではなくて、発生届が、ある意味、ばらばら出てきた中で、よく聞き取りをさせていただいたら、似たような時期に同じお店を利用されていると。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"お店を８月３１日まで休みますというところが何軒かあったのですけれど、あれも保健所の指導ということで、ああいうふうに休業されているのか。その点についても確認させてください。","respondent":"鷹箸保健予防課長","answer":"普通にお住まいになっている方もたくさんいらっしゃる地域ですので、あそこの地域全体が何か危ないとか、感染者が多いとか、そういうことではなく、非常に密なお店、立ち飲みだけで、５、６人でいっぱいになってしまうようなお店も多いと聞いておりますし、換気も非常に難しいと。","id":"exchange-021"},{"speaker":"鈴木（博）委員長","kind":"質問・要望","question":"最後に委員長から一言要望させていただきたいのですが、新型コロナウイルス感染症がまた流行してくることによって、乳幼児健診の集団健診が非常に難しいと思います。これは私からの要望です。","respondent":"鷹箸保健予防課長","answer":"続きまして、お手元の資料に基づきご説明します。","id":"exchange-022"}]},{"id":"topic-03","title":"ＨＰＶワクチンの区による情報提供","agenda":"ＨＰＶワクチンの区による情報提供","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"そうしたら、もともとの資料はＡ４判であって、できればもともとの大きさでつけていただければと。それから、そこを見ると、青色の資料だけではなくて、「医療従事者の方へ」という緑色の資料もありまして、その中で、こういうふうにするのだということも書いてあったりして、私が読んでも参考になるのですけれども、これもやはり配布しているということなのでしょうか。それをお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"今回は、対象となるのが、接種を検討する、あるいは接種についてまだご存じない対象児、あるいは対象の保護者の方ということですので、青色のパンフレットを対象児のところに送ることで考えておりまして、それ以外のオレンジ色あるいは緑色のパンフレットの個別の配布については。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"水色のパンフレットを送るということですけれど、それと併せて、どの医療機関でこれを受けられるのかというのも送られるのでしょうか。それで、緑色というのは、医療機関で医療従事者の方がこういうことでチェックして、指導しながらやってくださいという中身になっていると思うのですけれど、医療従事者に対しての指導というのもされるのか。その点についてお聞かせください。","respondent":"鷹箸保健予防課長","answer":"こちらのパンフレットを送ることに方針は変更しましたが、平成２５年６月１４日の積極的な接種勧奨を差し控えるという方針は変わっておりませんので、医療機関名簿を配布することは致しません。","id":"exchange-024"}]},{"id":"topic-04","title":"令和２年度障害児者の相談支援体制整備促進事業等に係る事業者の選定","agenda":"令和２年度障害児者の相談支援体制整備促進事業等に係る事業者の選定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"民間相談支援事業者の選定のことなのですけれど、１０事業者のうち４事業者を選定した。それで６事業者が選定されなかったということなのですが、この６事業者というのはどこで、理由はどういったことなのでしょうか。それをお伺いしたい。","respondent":"松山障害者福祉課長","answer":"選定理由なのですが、今回選定された４事業者につきまして、一番の大きな理由としましては、それぞれ相談支援員の資格がある人を配置し、バックアップ体制、いわゆる職員体制が、１名ないし２名の相談支援員を配置するということになっておりますので、バックアップ体制として。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"相談支援員の方がどのぐらいいるのか。それをお伺いしたいと思います。そういう意味での職員体制をお伺いしたいと思います。その辺のことをお伺いしたいと思います。それで、昨年もこういうふうにして決められたということ、議事録も読ませていただいたのですけれども、今後もこういう形で増やしていく予定はあるのかということも併せてお伺いしたいと思います。お願いいたします。","respondent":"松山障害者福祉課長","answer":"４点ご質問を頂きました。１点目の職員体制についてですけれども、民間相談支援事業者・在宅介護支援センター併設型の事業者ともに、配置される相談員は１名ないし２名の予定です。それから２点目ですけれども、専門職についてのお尋ねです。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ教えてください。今回の事業開設予定地を見ると、１０６号室、２０２号室、３０５号室、最後の.Ｃｏｎｎｅｃｔ株式会社というところが１階となっていますけれど、いわゆる民間のマンションの一室ということでよろしいですか。こういう相談事業というのは、大体そういう形でやられるパターンが多いのですか。それはもう事業者が持たれるということなのですか。その辺りを教えてください。","respondent":"松山障害者福祉課長","answer":"開設予定地ですけれども、品川区だけではなく、相談支援事業所は、民間のマンションの一室を借りて行うことが多いのが実情です。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう形で、障害者のほうの在宅介護支援センターも担当地域ということで、前回の場合はそうされていると思うのですけれど、今回も高齢者と同じ地域を担当するということで行っていくのかということを、１点お願いしたいと思います。その点について、まずお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"先ほど説明させていただきましたように、今のところ考えておりますのは、６つの基本圏域がありますので、昨年度開設した相談支援事業所がある地区の２地区、品川地区、荏原東地区、そして、今回それを除いた４地区を対象に募集させていただいたということで。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、在宅介護支援センターの場合は、高齢者のモデルをやるという方向だったと思うのですけれど、そういうことで、在宅介護支援センターが、今回合わせて４カ所になるわけですけれども、在宅介護支援センターで計画をお願いしたいと思っても、この担当地域以外の方は利用できないということになるのでしょうか。","respondent":"松山障害者福祉課長","answer":"ただし、障害の高齢化というのと、あるいは８０５０問題は、やはり解決しなければならない課題だと認識しておりますので、その課題に向けて、どうやったらいいモデルをつくれるのかというところが、大きな目的、共通目的になっております。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"というのも、去年、同じような形で６カ所が指定されたときに、平成３２年度は１,９４０件ぐらい、計画の見込量ということで出されているということだったのですけれど、おおよそ１カ所につき１人の相談支援員ということなので、最高でも３５件ぐらいまでということになると、それ掛ける６カ所ということでしかないのかと思うのですけれど、去年新たにできた６カ所で。","respondent":"松山障害者福祉課長","answer":"ただし、障害者の大人の方の場合については、円滑に移行していると認識しています。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その辺のところは、補助金が出されていながら、実際は計画が組まれていないという、そんな状況になっているのか、そこの実態も併せて教えていただきたいのと、今回、児童もさらに３カ所増えるわけですけれど、合わせて児童のほうが６カ所ですか、増えると思うのですけれど、そういうことで、これからは品川区の障害者福祉課で組んでいる計画が、この事業者にどういうふうにしたら移行できるのかというような。","respondent":"松山障害者福祉課長","answer":"２・３月は新型コロナウイルス感染症関係の影響もございまして、なかなか本人と対面でというのが非常に難しかったというところもありますので、それを加味しますと、一件も作らなかったわけではなく、事業所として場所を設置して事務所を構え、東京都に届出をし。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう一つ伺いたいのが、１０事業者、今回応募してくれてよかったという思いをしているのですけれど、これはどういうふうに周知されたのか、各事業所に声かけなどもされたのか、その点についてもお聞かせいただきたいと思います。それから、もう既に連絡会というのは持たれているのでしょうか。","respondent":"松山障害者福祉課長","answer":"今回の選定から漏れてしまった６事業者に対しましても、補助なく自力でやりたいというお声も聞いておりますので、期待したいと考えています。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"こういう形で様々な事業所が品川区内に入ってくるというのは、いろいろな刺激だったり、本当に質的にもすごくいいことではないかという思いをしているのですけれど、それぞれの事業者が他区でいろいろな実績があるということも言われておりましたけれども、そういう点では、他区でいろいろな事業、相談だけではなくてグループ訪問をやっていたり、いろいろなサービスを行っている事業者が。","respondent":"松山障害者福祉課長","answer":"品川区において今後貢献できるようなサービスにつきましては、今回、応募するにあたりまして、その項目を設けまして、実際に担当の方で事業者と対面で、どのようなことができますか、あるいはどのようなノウハウを品川区で展開できるかということの打ち合わせもしておりますので。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":37240,"voices":95}},{"id":"r02-20200819-8","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"建設委員会","time":"午後 １時００分～午後 ５時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件抜き出しています。","topics":[{"id":"topic-01","title":"令和２年請願第８号、「（仮称）豊町１丁目計画 新築工事」に関する請願","agenda":"令和２年請願第８号、「（仮称）豊町１丁目計画 新築工事」に関する請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"こうした中で、この請願の文章の中には、１回で説明会が終わってしまったということで、住民の方々との合意はできていないと書いてあると思うのですけれども、この説明の段階で、説明が尽くされたと区のほうでは考えているのか、まず区のお考えを伺いたいと思います。","respondent":"森住宅課長","answer":"説明は基本的には終わっているというふうに考えておりまして、また、合意ができていないというお話がありますけれども、基本的に事業者としては、敷地の中であるということでありますので、なかなか今の時点で通行を可とするということは難しいけれども、今後。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今ご紹介もありましたけれども、敷地内の通行を認めることは難しいと事業者のほうから回答があったということで、これは請願者の方々が求めている緊急時の対応というのも困難ということなのか、そこの確認をさせていただきたいと思います。これも困難ということであれば、緊急時の対応は区としてはどのように考えているのか、伺いたいと思います。","respondent":"森住宅課長","answer":"基本的には、区全体として、木密の改善もありますし、例えばこの青いところの既存道路につきましては２項道路になっておりますので、そういった部分でのセットバック等々で緊急車両の出入りができるように。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"区としては、２項道路なので、２ｍ、２ｍのセットバックをして４ｍにしていくことで、緊急時の対応をしていきたいというお考えだということだったと思うのですけれども、それが果たしていつ頃になってしまうのかということも心配になるわけです。区としてもそこに協力をしていくということが必要なのではないかと思いますけれども、いかがでしょうか。","respondent":"森住宅課長","answer":"あるいは、今後、工事も進めていくことになろうと思いますけれども、そういった中でのご要望についても、基本的には、これまでもやってまいりましたけれども、これからも近隣の方々にご理解いただけるように事業者には指導していきたいというふうに考えております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。ぜひ住民の皆さんに区も協力していただいて、話し合いをしっかりとしていただいて、合意が得られるように力を尽くしていただきたいというふうに思います。９月着工ということになっており、この請願については、今回で結論を出すということにしていかなければ着工してしまうので、結果を出していくべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"私は、この請願と関係資料を見たときに、住所が分からなくて探せなかったということがありまして、請願者の方に前もってお伺いしておけばよかったなということをすごく思ったのですけれども、今、既存道路の部分は道路としてあるけれども、緑色の、今まで近隣の方たちが通られていた道路は、もともとは道路ではなかったのかどうかというところをまず確認させてください。","respondent":"森住宅課長","answer":"その突き当たりといいますか、東詰めのところが計画地になっておりまして、その計画地の中の家の周辺といいましょうか、そういった形の特に法的に位置付けられているものではないのですけれども、そこに、先ほど、３棟。","id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"今この計画地のところでは、民地であって、皆さんが利用されていた。民地だけれども通路となっていた部分も、計画地となっているところは権利が発生してしまっているということですね。そこの部分について確認させてください。","respondent":"森住宅課長","answer":"緑色の部分につきましては、もともとの地権者の方が持っておられて、その中できちんとした契約といいましょうか、周りの方々との話し合いの中で「ここを通っていいよ」というふうになっていたというふうには聞いていないのですけれども。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"というのは、ここの計画に限らず、今、品川区内でのまちづくりとかでも、様々なところでやっぱり説明不足というのは指摘をされていて、住民の方たちがどうしてなのだという、理解が得られないままという状態は結構多発しておりますので、この話し合いの場を求める請願者の気持ちはとてもよく分かります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"先ほどの説明の中で確認したいのが、管理組合に伝えるということをおっしゃったのは、何を伝えるのですか。","respondent":"森住宅課長","answer":"この共同住宅につきましては、分譲を予定されているですので、住まわれた方々が、通常であれば管理組合を作ってというふうに考えています。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"ということは、この緑色の部分も含めて建物が建つと私は理解したのですが、そうすると、青色の既存道路、これは２項道路になっているからセットバックになって、ここまでは通路になるわけですね。だけど、それがなくて、建物が建ってしまったら、そこを「はい、どうぞ」と言っても通れないわけです。そこはどういうふうなイメージを持っているのでしょうか。","respondent":"森住宅課長","answer":"この計画地は、敷地にめいっぱい建物が建つというわけではなくて、当然、必要な空地もありますし、駐車場も幾つか計画されているというふうに聞いておりますので、外構の工事は追加で発生するかもしれませんけれども、そういったいわゆる建物周りの空地を使ってということは。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"要は、余裕があるということですね。それがこの事業者がどう受け止められるかということなので、多分この請願は、話し合いを設けてほしいということなのだろうなと思うのですが、ただ、５月１９日に請願者の方がいらっしゃって、事業者に伝えたわけですね。それで、６月１０日には難しいという。これは何が難しいと言っているのか、お分かりですか。","respondent":"森住宅課長","answer":"事業者として６月１０日に回答された内容としましては、緊急、非常時を問わず、敷地の中を不特定多数の方が通行されるということを可とすることは難しいというお話でございました。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、せめてどういうふうに言うのか、管理者の方々に要望を伝えられるような状況、そういう場を作れるのかどうか。ただ、民民の話なので、やっぱりそこは民民で何とかしてほしいという思いがあります。いろいろ問題があります。ただ、思いを受け取る上では、もう少し区のほうでやれることはないでしょうかという思いはあります。そこの瀬戸際のところで何かできることはないでしょうか。","respondent":"森住宅課長","answer":"ですので、当然、近隣の方々のご要望については、こういった「通行させてくれ」とかということも含めて、あるいは、工事の最中にも当然要望を聞いていくという形で事業者のほうにも伝えるということは区の役割としてあるわけですけれども。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"確かに分かります。区の立場は重々に分かっていつつも、この請願者の方々の思いも理解はできるわけです。空地があるのであれば、そこを何とかお願いできないか。条件整備だと思うのです。通常、いつもいつもそこを通るという形にはならないかもしれません。ただ、緊急事態にはというところで、その条件である程度合意がとれれば、それでも前進かなと私は思うのです。これは要望として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"確認だけさせてください。５月１９日、区民の皆様の要望を受け、区としては事業者にそれを伝える、これが１つあって、それに対するお答えがあった。これは分譲するのだというお話ですね。あるのは、区民の皆様の要望を聞いて、それをしっかりお伝えして、今は回答としては敷地内の通行を認めることは難しいという回答があった。多分これはこの後も工事中も何も要望があってお伝えすることはできる。","respondent":"森住宅課長","answer":"今、委員おっしゃられたように、区として指導できる内容といたしましては、条例に基づきまして標識の設置、説明会を行うというところを義務付けしているまでです。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。不採択でお願いします。これまで我々もこういう民民の話は議会でも相当いろいろ出てきたのですが、民民の限界というのもあるわけで、これに対して議会として、「こういう請願が出てきた。これについては不採択」と、今までもずっとこういうふうにしてきましたし、今回もそれでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問・要望","question":"本日、結論を出していただきます。しかしながら限界があるというような、今、答弁の中でも、質問の中でも聞きましたけれども。先ほど来、課長もお話をされた、今、石田秀男委員の質問にもあったように、今後管理組合ができ、また管理組合の組合員たちもそこの地権者であります。そこの中で新しく来た方たちと旧来から土地に住んでいる方たちの軋轢が起こらないように対処をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"本日、結論を出すで、結論は不採択でお願いします。民地です。そういう地域にわざわざ越してこられる新しい住民の方々が、何か危急のときに、この既存の道路も使えないというような危険性も、今のお話を聞いていて感じるところもありますので、今後の対応については新旧皆さんの意見をしっかり踏まえて、しかるべきところにお話を通していただきたいということが意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"のだて委員","kind":"意見","question":"本日、結論を出すということで、この請願は、話し合いをしていきたい、それに協力してほしいということですので、住民に説明を尽くすことがやはり必要だというふうに思いますし、自治体としてもそれに協力していくべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"田中委員","kind":"意見","question":"本日、結論を出すで、趣旨採択にしたいです。理由は、やはり権利者の方たちの土地ですので、ここをどうしても通してほしいというこの請願者の方たちの思いはなかなか難しいのかなというところがあるのですが、ただ、この請願趣旨は、説明会の場をもうちょっととってほしいといったことなので、そこに関しては採択をしたい、応援したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論をお願いいたします。不採択でお願いします。今まで民地だったところを、ちょっと通りに使っているとか、それが当たり前になってきて、ここをもっと拡げてほしいなどと言い出す方もいらっしゃるのです。ここではないです。だけど、「そこは民地ですよね」と言っても、「いやいや、いつも使っている道だから」みたいなことを言われると、それはやはり違うのではないですかという話。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"採択ということで主張いたしましたが、住民の皆さんの要望を多く賛同させていくということで、趣旨採択ということにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-02","title":"羽田新飛行ルートの運用状況等","agenda":"羽田新飛行ルートの運用状況等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"国から示された資料について、区としてはどのように受け止めていらっしゃるのか、それを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国としては、今、この報告制度が２０１７年度から実施されて、これが定着している結果のあらわれだですが、やはり定着して報告制度が充実して報告されるのみではいけないわけでございまして、当然ながら、この原因究明、数を減らしていく、毎年。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"あったとすれば、どういった説明だったのか、伺いたいと思います。幾つかですが、この推計平均値を上回った測定局もありますので、なぜ上回ったのかということも国土交通省から説明を聞いておられましたら、伺いたいと思います。今後、「別途１～２週間程度の短期的な測定を検討する」ということが書かれておりますが、こういったことも含めて、今どういった調整がされているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区内３か所のうち、八潮ポンプ所につきまして数字が超えてありますが、基本的にこの件に関する説明は、国のほうからはございません。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、住民への被害も大きくなるということになるので、区としても国に原因、理由をしっかりと説明をいただきたいということで要望していただきたいと思います。今、国のほうではいろいろチェックをやっているというお話ですが、このチェックや点検を続けていくことで、落下物はゼロになるというふうに区のほうではお考えなのか、国の説明などもあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国においては、国の職員が駐機中の機体をダブルチェックといいますか、そうしたところも行ってきている。国の説明では、こうした取組を総合的に継続し、重点的に行っていくことで、落下物ゼロを目指していきたいということで聞いてあります。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"チェックを徹底したことで２倍弱に増えているというのは確かに言えると思うのですけれども、チェックを徹底して、その対策をしていくことで、確かに減らすことはできると思うのですが、今、実際に９００を超える部品欠落がある。これはゼロにしていくというか、実際にゼロにできるのかというところが大きな問題だと思うのです。改めて落下物をなくせるのかというところでご答弁を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"事業主体の国に責任をもって取り組んでいただく。その中ではゼロを目指して取り組んでいくということを掲げてありますので、区としては、これまでどおり、落下物、安全対策、取組の徹底、さらなる加速した取組をこれからも継続して区としては求めていくです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"実施主体は国ですけれども、やはりその被害が区民に及ぶということになりますので、区としてもそこはしっかりと受け止めていただきたいというふうに思います。それと、区のほうで行った騒音測定があったと思うのですが、その詳しい分析を公開するということで、これまで言われていたと思うのです。それは今現在どうなっているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"以前の建設委員会でも説明させていただいたのですが、測定を行っているのですが、数字がいろいろ、大きな音であったり、この音が本当に飛行機の音なのか、場合によっては学校のチャイムの音だったり、何かほかの要因で大きくなっている音の場合がありますので。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"なぜかというと、突き合わせでチャイムの音が入ってしまって、羽田新ルートの飛行機の音かどうか分からないというのが、ちょっと納得がいかないというか、今、騒音の問題とかで区民の方たちは、この羽田問題に対してとても不安に思っているときに、測定はしているけれども突き合わせができないから公表ができないというのもすごく分かるのですけれども、ただ、今どれくらい騒音が出て、どれだけ不快か。","respondent":"鈴木都市計画課長","answer":"やはり区として公表するということになりますと、当然ながら信頼性のある、いろいろな技術的に精査をして公表していかなければいけないということで、当然ながら区としては、一刻も早く公表したいという思いはありますが、そうした意味で国のデータとの突き合わせですとか。","id":"exchange-026"},{"speaker":"田中委員","kind":"提案","question":"分かりました。先ほど私が提案したハンディタイプのところですけれども、今、航路下にある小学校に関しての騒音を知りたいのと、あと、航路と言っても線路があるわけではないのでずれるではないですか。なぜかというと、この国土交通省の資料を提出して、私たちに何を求めていたのかということが見えてこなくて、区として何を報告したかったのか、その部分をまずお知らせいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"それは今後、地域の声等の状況を見ながら、実施していくかどうかということは考えていきたいというところと、先ほどのハンディタイプのものを使っていただくとか、そうしたところでそうした声には対応していきたいです。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会について、前回の委員会の中では、１回目の検討会の様子を見て、その後の要望とかを出していくという話だったと思うのです。ですので、中身がそんなに進んでいなかったとか、そういったことなのかもしれないのですけれども、１回目の検討会の中身がそうだったとしても、報告はあるべきだと思うのです。検討会は、結局、何回行われるのかという……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"私たちが求めているのは、羽田新ルートの問題について区が今後どう対応していくのかといったことだったりするので、国の報告を示されても、なぜなのかなと思うのです。続けて、区のホームページ。ただ、そのほかのことで、今、コロナの問題と羽田新ルートの問題はとてもよく区民の方から質問されます。ですので、そういった改善を求めたいのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"１回目から明確に答えを出すという形で大臣が答弁をしたということではございませんで、私もそれを受けて、この検討会の推移について、動向についてはきっちり注視していきたいということは、前回の委員会でもご説明させていただいたと思います。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会のことです。注視していくというのは、本当にそのとおりなのです。ただ、年度末をめどにまとめていきたいということだったのですけれども、開催の、例えば１か月に１回開催されるとか、何か月に１回開催されるとか、そういった開催についてもぜひ求めていただきたい。要望します。受け止める先、「ここに相談できます」と窓口が分かるようにお知らせできるように要望いたしますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"委員会の回数ですが、これは当日、６月３０日、マスコミ等の中でも質問があったようですが、やはり今後の進め方、次回の開催時期については、国のほうでは、今いろいろな準備、検討をしている中で、明確にはお伝えできないです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"その検討会開催について、ぜひ、待つだけではなくて、今おっしゃっていたように、事あるごとに「いつ開催されますか」といったことを言ってもらえるようにしていただきたいと思います。品川区は一番影響を受けている区で、自治体としてもっと求めていく姿勢は見せてよいと思うので、年度内にめどをまとめていきたいといったことで納得するのではなくて、どんどん要望をしていってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"データの見方がちょっと分からないので教えてください。どこのページでもいいですけれども、その中に、これ、「エルデン」と読むのでしょうか、これは何でしょうということです。どういう測定の仕方をやっているのでしょうか。「便数が減少していることから、低い値となっている」という意味は何でしょうか。本来はどういうふうな意味合いがあったのでしょうかということが１つ。","respondent":"鈴木都市計画課長","answer":"騒音の測定として拾っているのがこの資料で、何機飛んだかというのはまた別の資料で公表されてあります。見方としては、そういう見方になります。この下のところに矢印、ピンク色と青色で付いていますが、これは説明会で国が示された推計平均値を示しています。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"結局、何機も何機も通るわけですから、実際聞いたところだと、１機飛んできた、ただそれは、例えば頭上に飛んできたときに一番音が大きいわけですね。国の示した結果は結果なのだけれども、実際に品川区ではどういう影響があったのでしょうかというのは、やっぱりかみ砕いて話をしないと分からないのではないですか。多分これの３倍ぐらいの便数になるのではないでしょうか。もう１つ、落下物の件です。","respondent":"鈴木都市計画課長","answer":"ただ、そのときに、羽田のこれからということで説明会、運用開始前にいろいろな資料を作って国が出してきた中には、例えば「８０ｄＢというのは、町なかの音ですとおおむねこれぐらいの音です」ということで、比較できるように示してきたものが、この資料にはないという意味では。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"今は３分の１ぐらいだと思いますので、それが３倍になったときに、どういう影響があるのかというのは、数字的にも比較できるようにはしていただきたいというふうに思います。本当に１個でも落としてはいけないのです。ここは品川区がどうのこうの言うものではないので、注視をしていただきたい、やっぱり追及をしていただきたいというふうに思っておりますので、これは意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、１点だけ。今後の委員会での報告についてですけれども、先ほど求めた区の担当で測定している数値や検討会の報告とともに、区への問合せの件数を。前回、たしか３か月分だったかを教えていただいたと思うのですけれども、問合せ件数をお知らせいただきたいと思います。今も教えてください。今までのというか、今月のというか、教えていただければと思います。","respondent":"鈴木都市計画課長","answer":"区への問合せ件数ですが、４月が２６件、５月が２７件、６月が２４件、７月が３３件、８月が、８月６日現在になりますが４件です。この問合せ件数につきましても、今後、適時適切に当委員会でご報告します。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"前回たしかその件数の中で、騒音に対してとか、国の対応に対してとか、内訳も示していただいたと思うので、そのようにお願いします。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-03","title":"令和２年８月都営住宅入居者募集","agenda":"令和２年８月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"去年でしたか、１軒、都営住宅だった元芝アパートがなくなってしまったということで、区内の都営住宅の軒数、戸数が減っているというのが現状だと思うのです。そういった中で、やはり都営住宅を必要としている方々が大勢いらっしゃって、募集がなくなっているというふうに思うので、そこの区の考えと、ぜひ減らさないように、増やしていっていただきたいということで伺いたいと思います。","respondent":"森住宅課長","answer":"今、お話がありました元芝アパートがなくなって、今、区内に３,４０９戸という形になっておりますけれども、都営住宅ですので、増やす、増やさないというお話はなかなか区としてはできかねますが、移管のお話もありましたけれども、区といたしましては、その施設について。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろな総合的なことを勘案して判断していくということだったのですか。ですので、ぜひ公営住宅、都営住宅、区営住宅も含め、減らさないことはもちろん、増やしていっていただきたいというふうに思いますので、もう一度お考えを伺います。","respondent":"森住宅課長","answer":"その中では、昨年度末に設立いたしました居住支援協議会も含めて、民間の力を生かしながら、住宅にお困りの方々への提供をそれぞれのお立場でご協議いただきながらしていければと考えているところです。","id":"exchange-038"}]},{"id":"topic-04","title":"大井町駅周辺地域まちづくり方針（素案）の策定","agenda":"大井町駅周辺地域まちづくり方針（素案）の策定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"簡単に伺いたいのですけれども。新たな価値の創造というのは何を差すのか、どういったことなのかというところを伺いたいと思います。行政のところで、「柔軟な執行体制の確立」と書いてありますが、この「柔軟な」というのはどういったものになるのか、ちょっとイメージが沸かなかったので伺いたいと思います。","respondent":"多並都市開発課長","answer":"最後の１３ページのところですけれども、行政の中で「柔軟な執行体制」と書かせていただいたのは、住民の方だったり、また、事業者の方、ＮＰＯの方々から、いろいろ実現したいという話があったときに、確かに条例。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"ですので、この「機運が高まってきた」というのは、何をもっておっしゃっておられるのか、また、誰のことを言っていらっしゃるのか、そこを伺いたいと思います。この間、大井町の基本方針を含めやられてきておりますけれども、まちづくり方針を作られたというのは、どこで作られたのかというか、誰が作ったのか、そこのところを伺いたいと思います。","respondent":"多並都市開発課長","answer":"一方、そういう再開発を望まない方の団体の方も、令和２年２月からそういう形で検討されているというのも、我々も一緒にやらせていただいて聞いておりまして、今まで２回ほど開催されているということを聞いております。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"まちづくりというのですけれども、大体区で出てくるまちづくりは高層ビルの、ということになるのです。ちなみに、特に先行してやるというような形で資料にも書いてありますけれども、Ｃ地区とＥ地区のところで、勉強会が何回ぐらいやられてきたのかということもお伺いしたいと思うのですけれども。まちづくり勉強会の事務局という形で東急も入っているということですよね。この点はいかがでしょうか。","respondent":"多並都市開発課長","answer":"そういう意味では、一番は、東急がというわけではなくて、地域の方がご自分の土地や建物をこれからどうしていこうかと考えるときに、その中でそういう検討をしていきたいということであれば、これは必要なことでありますし。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"今はまだ検討段階ということでしたけれども、そうしたら、高層ビルありきということはないということなのか、そこのところは確認をさせていただきたいと思います。実際に今回新たに開発があったとして、商業施設ができて、そこに来たお客さんが、賑わいにどれだけ貢献していくのかというところは、区としてはどのように分析されているのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"１点目の新型コロナウイルス感染症に関することでありますけれども、これについては、やはり地域の方だったり、今回もいろいろな方とお話ししている中で、まずはまちづくりというところから話しますと、まちづくりはやはり１年、２年で終わるものではなくて、１０年単位の、実際。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、検討を進めてきていらっしゃると思うのですが、その中で報告書も４回求めても黒塗りという状況があるので、そういったところもぜひ公開していただいて、住民が参加できるようにしていっていただきたいと思います。住民目線のまちづくりが重要だと考えていますので、より反映をしていくという視点で、どのように考えていらっしゃるのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後のまちづくりはいろいろ都市計画手法を活用しながら進めていく予定ですけれども、その際には、手続きごとに住民説明会を開かなければいけないところもありますので、そういう意味では、ステップごとに、段階ごとにご説明しながら進めていくことになりますので。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に１点だけ。今回の方針についても説明会をやるということでしたけれども、大体この間、そういう方針が示されて、説明会やパブリックコメントなどをやった際に、意見が出されても、全然変わらないということが往々にしてありますので、その意見をぜひ住民目線で反映していくという視点でそれぞれやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"多分、今の感染症の対策として、定員とかを減らしていくのかと思うのですけれども、その定員についてもお知らせいただきたいのと、また、多分こちらもとても関心が高いと思うのです。区庁舎のことも加わっていますので。関心が高いと思うので、２日間の日程の中で時間を割って開催するのかとか、そういったところも聞きたいのと、あと、リモート、その場に行かなくても、ネットで見られたりするのかという点。","respondent":"多並都市開発課長","answer":"行けなかった、もしくは行けないので、いろいろ説明してほしいと個別のお話があった際は、我々が直接、郵送なり、そのような形で、ホームページをご紹介したりいろいろしますけれども、いずれにしろご連絡いただいた方には。","id":"exchange-045"},{"speaker":"田中委員","kind":"確認","question":"説明会をリモートで中継といった、家庭や職場で見ることはできないということですね。議事録や資料が後日公開されるというところを確認させてください。質疑があるということで、そこで意見をきちんと伺うということだったのですけれども、その質疑の内容によっては、今出されている素案の中身が変わっていく可能性も十分にあり得るということでよろしいでしょうか。確認させてください。","respondent":"多並都市開発課長","answer":"当日、住民の方々からご意見があって、素案に反映させるためにいろいろご意見をいただきたいところですので、もちろん変更を想定しながらのご意見のお伺いということであります。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときに見られたら一番いいのですけれども、そういうことができるのかというところを確認させていただきたいと思います。そして、もしかしたら先ほど説明があったかもしれないのですけれども、パブリックコメントは実施されるのですか。されるとしたら、時期もお知らせいただきたいと思います。","respondent":"多並都市開発課長","answer":"今回はパブリックコメントの実施はいたしません。地域の方々にご説明して、地域の方々からのご意見をいただいて反映していく、そういう形をとらせていただきたいと思います。","id":"exchange-047"},{"speaker":"田中委員","kind":"意見","question":"今、パブリックコメントは実施されないということだったのですけれども、では、やはり説明会に来て質疑をしないと区民の意見は言うところがないということになりますか。そこのところをお知らせください。","respondent":"多並都市開発課長","answer":"そういう形でいろいろ、パブリックコメントということもありますが、大井町だったり、ほかに大崎だったり武蔵小山だったり、いろいろなところで、今、まちづくりをいろいろやっていますけれども、地域の方に知っていただきたいということで、地域の方にご説明という形で。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"大井町駅周辺のこのまちづくりに関しては、区庁舎のことも関わってくるので、多分、ほかのところのまちづくりとはちょっと変わってくるのかなと思うのです。ですので、区広報とホームページの周知よりももっと周知が徹底されるべきだろうと思うので、そこのところを検討いただきたいと思います。これは要望します。今のＪＲとの協議の状況や進捗状況などを報告いただきたいと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"それ以上の具体的なところにつきましては、これからどのような形で公表するかというのは、ＪＲ東日本の社内の内容でもありますので、そこについてはよくお話ししながら、しかるべきタイミングには公表いただくような形、もしくは区のほうで公表できるものがあれば。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"ＪＲとの協議が一番最近行われたのはいつなのかというのと、その内容は。協議をしてここまで来たというのは分かるのです。協議の状況を、進捗などを報告いただければと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"そういうところで、今ちょうど、これから事業が動いていくところになり、本年度は一番まとめ上げていく年度でもありますので、頻繁に調整させていただいているというところが今の実態であります。","id":"exchange-050"},{"speaker":"田中委員","kind":"確認","question":"その協議、昨日も行われたということなのですけれども、その協議の場、広町のこれからについて話し合っている場なので、そういったものもきちんと議事録とかが残されているというものなのですよね、ということを確認させてください。","respondent":"多並都市開発課長","answer":"「これがあって、これがない」とかではなくて、必要な部分はもちろん区のほうで保存しますけれども、そういうものもあるということです。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"今の答弁の前のご答弁の中で、ＪＲとの話し合いは具体的なものとなってきているということだったので、大体のそういったものができてきているのですね。細かな部分もできてきているのかなと思うのです。情報公開を今しているところなので、そういったものがきちんとこれから公開されていくようにしていただきたいと、ぜひきちんとお願いします。要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認させてください。これは広町地区のまちづくりという形で、そこを変えましたということだと認識しているのですが、ほかの地域の変更点はあるのでしょうか。そこは変えずに、今回はあくまでも広町アパートの解体、この辺だけのものだという理解でよろしいですか。","respondent":"多並都市開発課長","answer":"広町地区以外は、先ほどちょっとご説明しましたが、活力創造の形でＥ地区とＣ地区をこの中で設定しています。これはほかの地区と１個違うのは、地元の方がまちづくりの検討をされているという意味で、ここをゾーンとして設定させていただいた。それが変更点です。","id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"それとも、区としての考え方がある程度あって、もちろん大枠はあると思うのですが、具体的なものについての進め方は、その話し合いが見守っているということの確認をしたいのですが。","respondent":"多並都市開発課長","answer":"先ほど、広町地区については、具体的にということで書かせていただきましたけれども、それ以外の地区については、もともとのまちづくり構想で書かせていただいたものと大きく変わっているわけではありませんので、そこは特出しで書いてあるだけで。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなった場合に、過去にとらわれずに、もう少し広い意味での官民連携という形に変えていかなければならないのではないかということを、１点、意見として言わせていただきたいと思います。最後のページの想定スケジュールですが、これ、横軸のスパンがよく分からないのですけれども、１年ごとなのか、１０年ごとのスパンなのか、横軸のスケールがちょっと分からないので、説明をお願いします。","respondent":"多並都市開発課長","answer":"最後のページのスケジュールのところですけれども、ここがスパンを書かなかったのが１つの意味でもあるのですけれども、考え方としては、広町が進んだときに、例えばＥ地区、周りの地区についてはこういうときに進んだらどうだろうと、そういうイメージで書いてあるものであって。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"必要なことです。ただ、では、そこにどういう関与で住民が入ってくるのか。一緒になってまちづくりをしていこうという感覚だったらいいのですけれども、そうではない状況になってしまうと、せっかくよかれと思っていろいろ計画をして勉強している方々と住民たちとの間に亀裂が入ってしまうとまずいなというふうに思うので、やはりそこはうまく調整していただきたいと要望したいと思います。","respondent":"多並都市開発課長","answer":"１点目と２点目と両方でお話ししますけれども、大井町に限りますけれども、まちづくりを進めていく中で、やはりいろいろなご意見の方がいらっしゃいまして、先ほどありましたＮＰＯだったり、いろいろな動きの中でのものがあるということも我々は承知しているところであります。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、区民の意見を聞く場の少なさがやっぱり引っかかってしまっていて。パブリックコメントもないということだったので、この大井町駅周辺のまちづくりに関しての「ご意見をここにお寄せください」みたいなものとかがホームページとかにあったらいいと思うのです。そういったことをぜひ考えていただきたいと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"先ほども説明会の後、資料は周知するというお話をしましたけれども、その中にも「お問合せがあればご連絡ください」という形で、もちろん書かせていただきたいと思っています。","id":"exchange-057"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。ここのところの柔軟性、これがこういうふうに出てきてしまって、ここは集積ゾーンで、ここはにぎわいをもってとなると、動かなくなるというのではなくて、行政の柔軟性というのは私はあると思っているのだけれども、簡単なことを言うと、例えばしながわ中央公園と組み替えてしまおうかとか、いろいろな選択肢が出てくるわけではないですか。そこだけ確認します。","respondent":"多並都市開発課長","answer":"実施段階ではもちろん総合的に、今ご意見があったようなことを含めて幅広く検討しなければいけないとは思っているところであります。都市計画上の整理もありますけれども、実施段階ではいろいろと幅広く検討できるかなと思います。","id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"確認","question":"そこは今は公園ではないけれども、公園の位置付けをする。では、現庁舎の部分はどういうものを持ってくるのだと。そういうものは下神明駅まで含んだ中で、もう一度新たな考え方ができるのだよね、ここがそういう意味の都市計画の中の位置付けをして、現庁舎のここの部分が都市計画で位置付けされているから、その柔軟性が非常に奪われるということはないよね、という確認だけ。","respondent":"多並都市開発課長","answer":"庁舎については具体的には経理課の庁舎機能検討委員会で機能の検討をさせていただいていることもありますので、庁舎のほうの動きと連携を図りながら、どのような形が一番いいか、そういう中で今のご意見も。","id":"exchange-059"}]},{"id":"topic-05","title":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","agenda":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"この間、大井ふ頭でヒアリが何度か確認されているので、生息していないかということが心配になるわけですけれども、そうなってしまうと、生態系などを壊していくことになってしまうので、そうならないように願うとともに、そうしていかなければならないと思うのです。そういった中で、生息調査というのは、どういったことをやられているのか、伺いたいと思います。","respondent":"提坂環境課長","answer":"先ほど、６か所と申し上げましたけれども、具体的には、品川南ふ頭公園、天王洲公園、東品川海上公園、八潮北公園、みなとが丘ふ頭公園の中の品川区キャンプ場、東品川清掃作業所、この６か所で実施しておりまして。","id":"exchange-060"}]},{"id":"topic-06","title":"新型コロナウイルス感染症の影響に対応するための沿道飲食店等の路上利用に伴う道路占用許可基準の緩和","agenda":"新型コロナウイルス感染症の影響に対応するための沿道飲食店等の路上利用に伴う道路占用許可基準の緩和","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、一括占用ということなので、商店街全体として一体で申請することになるということでしょうか。個店１つ１つで申請していくのではないというところの確認をさせていただきたいと思います。今回、道路占用許可基準を制定したということですが、これは新たに作ったということなのか、それとも今まであったものを改定して利用したということになるのか、そこのところを伺いたいと思います。","respondent":"稲田土木管理課長","answer":"まちづくりの団体とかが申請してくるというようなところを想定しております。ただ、商店街がない地区もございまして、そういうところは個店の方が数軒、何人か集まって申請主体となれば、条件等を考えながら相談に乗っていきたいというふうに考えております。","id":"exchange-061"},{"speaker":"田中委員","kind":"確認","question":"確認を。今の続きになってしまうのですけれども、では、個店の場合は、数軒まとまってということだったのですけれども、１つのお店だけでの申請はできないということなのかという部分を確認させてください。今も許可基準の制定の話がありました。それを拝見したのですけれども、この基準を探してしまったので、ぜひ参考資料として提供してほしかったということを思いますが、伺います。","respondent":"稲田土木管理課長","answer":"そちらの商店街の方にも「隣接しているものですからどうですか」というようなお声をかけたのですが、この商店街は「これは利用しない」というような話でございまして、区といたしましても「１店舗だけでいいよ」というようなことはなかなかできないものですから。","id":"exchange-062"},{"speaker":"田中委員","kind":"意見","question":"その商店街に隣接した１軒のお店のことは分かったのですけれども、例えば商店街とかではなくて、路地にちょっとあるような１軒のお店とかは、今回の許可基準の緩和の部分には対象にならないということでよいのか、お知らせください。","respondent":"稲田土木管理課長","answer":"その１軒がどれぐらいの範囲か分からないのですけれども、周辺でそういう仲間といいますか、「みんな一緒にやりましょうよ」というふうになってくれれば、こちらも非常に嬉しいですが、そういう中におきましては、基本は団体にです。","id":"exchange-063"},{"speaker":"田中委員","kind":"意見","question":"了解しました。今回この品川区でも取り入れたというのは、大体どこの地域を想定した上で制定したのかと思うのですけれども、どこら辺の地域を想定していたのかなどをお知らせいただければと。","respondent":"稲田土木管理課長","answer":"国とか都がいう歩道上で、テーブルを出した後に３.５ｍとれるとか、２ｍとれるというような歩道はなかなかないのです。区のほうでは、商店街で歩道がなくて店を出せれば非常にいいのではないかというようなことは考えました。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"そこでは可能なわけだから、そこの商店街の方々に「どうでしょうか」と声をかけることは当然やれたと思うのです。それをどうするのかということ。今、一番厳しい飲食店が努力をされて、お店の中だと３密になってしまうから、何とか外にというところもあると思うのです。そこを団体ではないから駄目だというのは、この趣旨にそぐわないのではないかと思うのですが、その積極的な考え方はいかがですか。","respondent":"稲田土木管理課長","answer":"区商連のほうには、「こういうことがありますから周知をよろしく」という伝え方もしております。それから、商業・ものづくり課とは最初から一緒に連携して取り組んでおりまして、商店街とか、そういうところでの実施はやっていこうかというところで考えていたところです。","id":"exchange-065"},{"speaker":"西本委員","kind":"意見","question":"担当が違うところがあるので、なかなか言いづらいところがあるかと思うのですけれども、ぜひ商業・ものづくり課と一緒になって。やはり飲食店の方々は本当に大変だと思いますので、少しでもチャンスがあるのだったら緩和していただいて。地域の活性化にもつながっていくし、外であれば少しは感染の対策にもなるかと思いますので、ぜひ前向きに考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"１１月３０日までということですが、１１月３０日では収まらない。国なり都の道路の使い方に対する政策の上で、この１１月３０日までの制度が、今後どのような形で変わっていくのか。道路法の改正とか、いろいろと法律の改正もあると思うのですけれども、どのように変わっていくのか、お分かりになったら教えてください。","respondent":"稲田土木管理課長","answer":"区といたしましては、コロナの状況等を見ながら前向きに考えてやっていきたいと考えていますが、国、都の状況がまだ１１月３０日までという方針しか出ておりませんので、その辺は、今後、状況を把握しながらやっていきたいと思います。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"国の中で２０２０年に道路法の改正があって、歩行者の利便を増進する制度ができるわけですけれども、ウォーカブル、要は歩いて楽しい道路づくりに向けて、ある意味、政策の変換というか、切り出したわけなのです。この１１月３０日を節目にして、それ以降というのは、そちらのほうの制度が利用されていくというような考え方でいいのでしょうか。","respondent":"稲田土木管理課長","answer":"ただ、土木の管理という中において、今までは「こういうものは、特別な場合以外は駄目ですよ」と言っていたところを、このように緩和してきたですので、考え方も変わっていくという可能性はあるとは思いますが、その辺はまだはっきりしていませんので。","id":"exchange-068"},{"speaker":"大沢委員","kind":"意見","question":"可能性があるから法改正が行われたというふうに私は理解しているのですけれども。可能性としては、今までよりも利便性の高い歩行者空間、道路という、利用や資源を考えてやるので、そこの制度につながっていくために法改正が行われたと思うのですけれども、あらかたその考え方というか、そういう理解の仕方では間違っていないかどうか。","respondent":"稲田土木管理課長","answer":"そういう中で、道路の道路法による管理というものもございまして、ただ、それが今、急激に変化するかというと、今の段階ではなかなか急激な変化は見込めないのかなとは思いますが、今、こういうものもやっていきながらという状況ですので。","id":"exchange-069"}]},{"id":"topic-07","title":"（仮称）旗の台六丁目公園整備に向けたワークショップの実施","agenda":"（仮称）旗の台六丁目公園整備に向けたワークショップの実施","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"募集方法について伺います。声をかけるのが、地元町会だったり、周辺１５０ｍの住宅等ということだったのですけれども、公園をよく利用する周辺の保育園だったり、学校にもぜひ周知をしていただきたいと思います。ぜひそういった声がより広く聞かれて、そして皆さんから利用される公園になってほしいと思うので、ぜひそういった声かけについてお願いしたいのですけれども、いかがでしょうか。","respondent":"高梨公園課長","answer":"今回の用地がちょうど町会の狭間にあるものですから、その周囲の声かけ範囲について検討をいたしました。","id":"exchange-070"},{"speaker":"田中委員","kind":"質問・要望","question":"多分このワークショップの中でも示されると思うのですけれども、やはりおむつ替えができるトイレも必ずあるようにといった要望をしたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"ワークショップだけにとどまらず、まだ来年度も基本・実施設計といったところもありますので、今、委員ご指摘のありました周辺の保育園、今回の声かけの範囲、周辺についてはあまり認証保育園を含めていない地域でございまして、相当離れてしまうのですけれども。","id":"exchange-071"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今、実際に確保できている件数ですとか、何人分というところを教えていただきたいと思います。必要な資機材の整備というところで、今、優先順位を付けて整備をしているということですけれども、必要数に対してどれだけ整備できていらっしゃるのか、実際の具体的な数を含めて伺いたいと思います。そこのお考えを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"そういった意味では、何室分というよりは、そういったところにお願いしているというような感じで、今、考えているところです。併せまして、それ以外のところにも新たに協議を開始しているところも既にございまして、これからますます拡大させていこうというふうに考えてあります。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと含めて、区民避難所だけではなくて、やはり多くのところで避難所確保をしていくということが分散避難につながって、感染リスクを減らしていくということにもなりますので、日本共産党品川区議団としても、区の施設、文化センターですとか、児童センターですとか、そういったところを多く避難所として開設していくということでも考えていくべきではないかと思っているのですが。","respondent":"平原防災体制整備担当課長","answer":"避難先として区の施設をというようなお話ですが、確かに様々な施設を使っていかなければといったところもありますので、区の施設も当然活用を考えているところですが、災害時には既に区の施設の大半がいろいろな役割を与えられているところでございまして。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問・要望","question":"テントは検討していくということでしたので、ぜひご検討いただいて、感染リスクを下げるような形で進めていただきたいと思います。区有施設は、各々、いろいろな役割があるということでした。今、お考えがあれば伺いたいと思います。そこの強化が必要だと私も思っているわけですが、どういった形でこの強化をしていこうと今お考えになっているのか、そこを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"続きまして、在宅避難者支援はどういう形でですが、まず避難者をどのように把握するかといったところから始まりまして、それぞれの避難者にどちらのほうに来ていただくのか、例えば学校に来ていただくという形になりましたら、そこに人が殺到すると。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"どこまで進んでいますか。そうすると、誰が避難所運営をするのか、ということなのです。そうすると、「学校を開けるのは誰がするのですか」「その方いないよね」とかという話になってしまったりとか、避難所運営については、今回はスペースの問題と、それから、この新型コロナウイルス感染防止のゾーンを作るにしても、誰が指導していくのかということがどこまでできていますか。","respondent":"平原防災体制整備担当課長","answer":"特に今回の新型コロナのマニュアルを運用していこうというときには、感染リスクが高い方々の対応につきましては、区の職員がメインという形で位置付けさせていただいておりまして、そういう両輪でやっていく中で、さらには。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問・要望","question":"１回、２回で分かるような状況ではないと思うので、どうなりましたかという確認作業はやはり入れていかなければいけないと思うのです。そのばらつきに合わせた形で今回のコロナ対策をしっかりしないといけないというのは、１回やったからいいということは思っていないと思いますが、何回か、機会を捉えて強調していただきたい。ちょっと細かいことはいっぱいあるのですが、以上で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば、在宅でもどれだけの人が食事がなければ避難所に食事を取りに来るとか、そういうシミュレーションみたいなものがあるではないですか。鉄骨でほとんど在宅避難で大丈夫だということもあれば、そこへ販売のあっ旋をしていこうとか、働きかけて、「最低限、それくらいは備えてくださいね」と口では言うのはいいのだけれども、では、それを備えるためにはどうしたらいいかとかあるではないですか。","respondent":"平原防災体制整備担当課長","answer":"今のようなお話が目に見えるような形、誰が見ても分かりやすい形になるように、私どもも工夫してまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503098?Template=document&Id=4298#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":76146,"voices":224}},{"id":"r02-20200819-9","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"文教委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","topics":[{"id":"topic-01","title":"令和３年度品川区立学校使用教科用図書の採択","agenda":"令和３年度品川区立学校使用教科用図書の採択","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"５回の採択に関わる教育委員会ですけれども、今回、コロナ感染防止の観点から、通常とは違うリモート会議で開催されたと伺っているのですが、具体的にはどのように行われたのかというのを伺います。５回それぞれの教育委員会の開催日と傍聴者人数を、もし正確に分かれば教えていただきたいと思います。その人数というのは当日、教育委員会には報告されたのでしょうか。以上３点伺います。","respondent":"有馬庶務課長","answer":"傍聴のやり方ですが、傍聴規則では、傍聴は３０名までと規定しております。しかし、教育委員室に３０名入れますと大変密になるということで、密を避ける対応を取ろうということで、今回初めて別室で、会議の様子を映しながらという対応を取らせていただきました。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"傍聴した方からお話を伺う機会があったのですが、教育委員会の審議の、私も過去、そういえば傍聴したことがありました。大田区では会社名を挙げて審議が行われていると伺っているのですが、なぜ会社名を伏せるのかという理由を伺いたいと思います。会社名を明らかにしても、そのほうがいいのではないかと思いますけれども、いかがでしょうか。その辺も確認させてください。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"２点目を先に。教科書展示の中でどんな意見が出たかということ等は、教育委員会の中で簡単にご説明をさせていただいているところです。１点目の教科書名、出版社名を伏せる理由ですけれども、実際に委員に配っている教科書は、別に伏せてあるわけではありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"教科書の会社名は、どんな教科書が採択されるかというのは、区民にとっては非常に重要な関心事だと思いますので、審議の効率というのは分かるのですけれども、聞いている方々が何の教科書について議論しているのかというのは分かったほうがいいと思うので、そこについては改善をしていただきたいと思うのですが、いかがでしょうか。それは質問です。その辺の認識を伺いたいと思います。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"ただ、今回はコロナ対策ということで別室でやりましたが、通常の教育委員室でやる場合は、そんなに大きな部屋ではないので、きちんと発言していけば、今のところは大丈夫だろうという判断をしていますけれども、今後。先ほどのイニシャル等の表現につきましては、委員ご指摘のとおり、傍聴人にも分かりやすくということは、内容につきましても心がけているところですので、今後、次回は小学校、３年後になりますけれども、研究してまいりたいと思います。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"研究と言わず、教科書名、会社名のことに関しては、積極的に改善していただきたいのです。聞こえているだろうというのは、こちらの勝手な判断なのですから、多様な方に、今、対応しているというのも言われていますけれども、どなたにとっても聞きやすいという環境をつくるために、マイクを使うとか、さらなる改善を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"新型コロナウイルス感染症下における区立学校の運営","agenda":"新型コロナウイルス感染症下における区立学校の運営","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"それで、コロナに着目をしてガイドラインを作られているのですけれども、一方で今の時期でしたら、例えば熱中症との絡み、マスクは外しても可というのもありましたが、例えば８月の途中から２学期が始まるということで、制服が暑過ぎるのではないかとか、そういったところも含めて柔軟な対応ができるということも含まれているといいなと感じますけれども、その点はいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"臨時休業の際の学習の保障ですが、今、国から通知も引き続き来る中では、その状態にもよるのですけれども、あまり長い間の休業は考えられていないようですが、少なくとも数日だとしても、これまでのお子さんがお休みになった、またインフルエンザのときと同じように。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"それから学習保障のほうですけれども、一斉休校ということは当面ないかなと思ってはおりますが、とはいえ、これからまた秋、冬と来る中で、教育委員会でも遠隔授業等々、準備はされていて、予算は通っているけれども、まだ整備はというお話だったと思いますが、現状の見通しとしては、それは早まるようなことというのはないのでしょうか。状況を教えていただければと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"リモート学習に関してですけれども、私どものほうで３月からお休みになったときには、区の状況が。今の説明と併せまして、学校での状況ですけれども、例えば保護者会をＺｏｏｍで行うというところで。なかなか機械がそろわなかったということもありますが、今のところ、年度内には確実に各お子さん方の手元には届くだろうということで。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません、こちらはあまり突っ込まないほうがいいかなと思うのですけれども、入札は実はもう行われているのかと思っていたら、まだなのですね。入札がいつ頃になるかというのを教えてください。そちらのほうは要望にしておきますけれども、入札の見通しを教えてください。","respondent":"篠田学務課長","answer":"今ちょうど経理課に入札の依頼を出すところですので、公募型の形での入札ということを想定していますので、９月の頭から中旬にかけて入札が実施されるだろうという形で考えているところです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"できるだけ早くということを改めて申し上げておきます。それともう一つ、最後に要望させてください。今度は乾燥ですとか、インフルエンザですとか、それとコロナを共にどう防いでいくかということは、もう考え始めなければいけない時期になっていると思いますので、ぜひまたそういったことも情報収集をして取り組んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"この区立学校版感染症予防ガイドラインは、確認として、いつ作成されて、いつからこれにのっとって対応されているのかということと、先ほどお話に出た、陽性者が出たということですけれども、感染経路というのはもう全て把握はされているのでしょうか。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目のガイドラインにつきましては、当初、先ほどのお伝えと重複しますけれども、国や東京都のガイドラインを受けて作成してきたもので、４月にというところだったのですが、ご存じのとおり緊急事態宣言とか休業要請が出まして。感染者の経路についてです。今のところ、先ほどもご報告させていただいたとおり、児童・生徒で３名、それから給食調理員が１名、陽性が出たと。学校関係者では、そういう状況です。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"この感染症予防ガイドラインは、今、バージョン５が最新版ということでよろしいのかということと、これは品川区のホームページとかで掲載はされているのでしょうか。つまり、区民にどの程度広く公表されているのかをお聞きしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"ガイドラインのホームページへの掲載につきましては、これは内容が大分変わりまして、特に後半の行事につきましては、見直し、見直しというところで安定しなかったところもありますので、時期を見てお知らせしていきたいと検討はしております。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。では、バージョン５が最新ということですか。","respondent":"矢部教育総合支援センター長","answer":"現状はそうです。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"特に柔道のこととかが書いてあるのですけれども、柔道は寝技とかもかなりあったりして、また近距離で組み合ったりするので、感染の危険があるのかなということと、吹奏楽でも笛とかといったものは、歌もそうだと思うのですけれども、飛沫を吸うということなのですが、そうした体育会系の部活、文化系の部活、様々あると思うのですけれども、部活動についての感染の拡大を防止するということについて。","respondent":"矢部教育総合支援センター長","answer":"は各学校の工夫は、人数を減らして、部屋を分けて、吹奏楽にしても部屋を分けてしているとか、かなり離れて、換気はもとより、そういった工夫によって進めているというところまでは聞いておりますが、暑さの中でどこまでというのは。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"最後、換気についてなのですけれども、換気を行うということは当然、ここのガイドラインにも書かれておりますし、やらなくてはいけないと考えておりますが、換気がきちんと十分かどうかという、ある程度の客観的なやり方というのも必要かと思うのですけれども、具体的に何分間開けるとか、あと、そこの二酸化炭素の濃度とかを測るとか、ある程度科学的に換気をするということは行われているのでしょうか。","respondent":"篠田学務課長","answer":"これは従来から行っているものですので、そういった中では、何か問題があれば指摘はしているのですけれども、換気がどうしても必要になるぐらいの、言ってみれば空気の悪い状況というのは、これまでの学校では指摘がされてきてございませんので、逆に今回。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"冒頭の１ページのところに、「国や都からの『学校再開ガイドライン』を踏まえ」とありますけれども、逆に品川区独自の内容というのはあるのか、それともないのか、伺いたいというのが１つ目です。やっているところもあれば、やっていないところもあると伺うのですけれども、大体どれぐらいで実施されているのか、小学校１年生からやっているところというのはあるのか、その辺を伺います。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"ですので、これからの消毒の仕方等、新しい指針もありますので、そういった地域人材の活用も含めまして、さらに検討を深めて、また負担軽減を図るような方策については進めていきたいと考えています。４点目、土曜日につきましては、年度当初の１４回の土曜日につきましては、１学期は実施できませんでしたので、この２学期以降は当初の予定どおり、あと９回ありますが、やる予定です。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"年間指導計画というところでしたけれども、今、区独自のところは１９ページだということでしたが、ここのどこが独自で、４０分にしてもいいですよというところなのでしょうか。これは改善が必要ではないかと私は思います。最低限、７時間授業というのは見直すべきだと思いますけれども、これに関しては、お考えはいかがでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"先ほどお話がございました７時間のところ、午前５時間をやっているところも、もうめどがついたところで、３学期からまた同じように戻すという話も聞いてありますし、この導入に当たっては、保護者や地域の方たちにも。時程のほうは説明があったところですけれども、７時間授業も毎日行うということではなく、週の中で幾つか設定をするというところが多いと把握していますし、また、義務教育学校の前身の小中一貫校の時代に。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"とある先生からは、そのときは子どもの表情がはっきりと読み取れたという感動の声もあったと伺っているのですけれども、もちろん、これは感染防止にも大変有効だということで、少人数学級については、全国知事会、市長会、町村会の主要３団体も提言しているし、識者による署名活動も始まっていますけれども、区としてはどのように少人数学級というのを評価しているのか。","respondent":"篠田学務課長","answer":"ただ、知事会等の考え方もありますので、そういったものに関しましては、特別区においても学務課長会としては、少人数学級、３５人学級の要望等は出していますし、そういうことも踏まえて、品川区としては、現状の法や都の規定等に沿った形での対応を根本に考えつつという形で。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"検査です。それと、少人数学級のほうは、私が伺ったのは、教師も子どもも一時期、分散登校の経験をしたわけです。その辺の経験を含めて、区としてはああいう学級規模を少なくして、感染リスクを低減しながら子どもの学びを保障するというやり方をどのように評価したのか、あの時期の経験をどのように評価しているのでしょうかというのを伺ったので、もう一度お聞かせください。","respondent":"篠田学務課長、齋藤教育次長、工藤指導課長","answer":"そういう方々が全体で、感染された方も含めて、３７名のＰＣＲ検査を受けられた方ということになっているのです。そういった方が３７人いて、その中には、家族が陽性になったので念のため受けたら、お子さんは陰性だったという事例もある。それが３７人だです。ただ今回は、密を避けるというところでの分散登校というのは、目的とする部分が、通常行っている少人数・習熟度別指導と異なるところがありますけれども。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"なかなか少人数のところは、なぜこんなに後ろ向きなのかなと思うのですけれども、それはそれとして、私の受け止めなので、分かりました。ですから、区立学校の教員の定期的な検査の実施や、少なくとも陽性者が出た区立学校では、希望に応じて行政の判断で検査を広げるべきだと、受けてもらうということをするべきなのではないかと思いますけれども、最後にこれはいかがでしょうか、伺います。","respondent":"齋藤教育次長","answer":"ＰＣＲ検査は、医療資源も様々あります。総合的にご判断されるべきものと考えておりまして、教育委員会としてお答えすべきものではないと考えております。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それからもう一つは、この冊子の２２・２３ページにありますけれども、全体と学年でそれぞれいろいろな行事がどうしても中止にならざるを得ない中で、これは致し方ないと思うのですが、運動会ですとか、修学旅行とか、中でもできる限り実施の方向で、今のまま、通常の内容ではできないけれども、工夫しながらというのもあるという中で、先ほども何か工夫されるようなことがありましたけれども。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"さきの議会でこちらの予算をご承認いただきましたので、できるだけ早期の対応をしたいと思っていまして、特に６月の下旬から全員での一斉登校が始まるということもございましたので、６月の下旬から７月の頭にかけて。私からは２点目と３点目についてです。どちらもとても大事なことだと考えておりますので、常に役員・校長にも連絡をし、明日も校長会がありますので、私から改めて伝えたいと思います。","id":"exchange-019"},{"speaker":"たけうち委員","kind":"意見","question":"分かりました。あっさりとしたお答えが、多分そこには思いが込められているものだと考えていますので、個別にお話は結構です。昨日も校長先生が大勢いらして、関係者が来てお話があったようですが、ぜひその辺をしっかりとお願いして、終わりたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"幾つかお聞きしたいのですけれども、まず６ページにある「校内環境の適切な管理」というところの一番下のキのところに、残留塩素濃度のことが書いてあるのですけれども、「留意すること」とあるので、特にこれはコロナウイルス対策に特化しているということではなくて、学校環境衛生基準というものがあると思うのですが、それと同じ内容ということでよろしいでしょうか。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"１点目の残留塩素濃度に関するご質問です。調理実習は、例えば小学校の家庭科につきましても、調理実習は本当に僅かな時間ですので、１学期の実施を予定していたところは、２学期・３学期に後回しにしているということが考えられます。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問","question":"それぞれありがとうあります。２点、すみません。理想は１５分から２０分置きに１回というところなのですけれども、そこは難しいと思うのですが、そういったところ、もしかしたら腎臓の病気をお持ちの方とかは水分制限があったりするので、そちらでも注意しつつも、１年を通して小まめに水分摂取することというのは、検討されていないのかということをお聞きしたいです。すみません、長くなりました。","respondent":"矢部教育総合支援センター長","answer":"委員ご指摘の水分補給につきましても、医療的なところもあると思いますので、慎重にこちらでも検討しまして、必要なところは学校に案内していきたいと思います。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"水分を小まめに取るというのは、対策としてはすごく簡単なことだと思いますので、ぜひ検討していただきたいと思っています。すみません、あと１点だけ。途中で出てくる、お子さんが学校に出すという健康観察票なのですけれども、これは紙ベースですか。教えてください。","respondent":"矢部教育総合支援センター長","answer":"実際の活用については、手に取っているところも当然あるとは思うのですけれども、玄関先で見せているという感じを拝見しているので、もしかしたら委員ご指摘のようなやり取りが心配ということで、配慮しているところもあるかもしれませんので、また実態を踏まえた後。","id":"exchange-023"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"１点だけ確認させてください。これからタブレット端末が１人１台配備されるということで、先ほども年度内に間に合わせるようにというお話がありました。","respondent":"工藤指導課長","answer":"現状、学校にある機器を使って、Ｚｏｏｍを使ってであるとか、私どもが校長連絡会等で周知しているところでは、今回様々な機器、学校に今あるＩＣＴ機器の活用については、教育上効果があると見込まれる場合には、それを教育委員会として認めますという説明をしています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"１点、質問し忘れました。２２ページのところなのですけれども、学力定着度調査なのですが、共産党は中止するよう求めていたのですけれども、時間数も厳しい中で、今年度も実施されたと聞いていますが、実施の状況と、表の上では全国学力テストは中止となっています。なぜ品川区は実施をしたのかという理由を伺いたいと思います。","respondent":"工藤指導課長","answer":"集計結果は９月末から１０月にかけて学校に戻りますので、各学校で活用していくという予定です。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"今のお話、私はこの休業があった後で、それぞれの学力定着度をはかるというのは、意味あることだと思います。ただ、そのフィードバックが９月から１０月では、今の子どもたちの差がついてしまっている状況に学校が対応するのは難しいのではないかと思うのです。それを早めたりとかはできないのでしょうか。その辺のお考えを聞かせてください。","respondent":"工藤指導課長","answer":"そこは採点業者等とのやり取りの中では、一番最短でという日程でいただいているところではあります。それは様々、コロナ禍に対して業者側のというのもあろうかと思います。最短でいただける日程でというところで、今お話をしている中でというところではあります。","id":"exchange-026"}]},{"id":"topic-03","title":"児童センターの休館","agenda":"児童センターの休館","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"このうちの幾つかはネウボラ相談をやっていたかと思うのですけれども、今、ネウボラ相談は対面でしたか、それとも電話でしたか。曜日が当たっているところもあるのですけれども、この日はどうなのか、教えてください。","respondent":"崎村子ども家庭支援センター長","answer":"ネウボラ相談については、現在は面談での相談を再開しております。こちらの休館に当たる日については、ほかの休業日と振り替えて対応するようになるかと思いますが、そこは現場の児童センターと調整をさせていただきながら対応したいと考えています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"児童センターのＬＥＤ化なのですけれども、順次２５の全館、進めていくという計画なのでしょうか。その辺について、もし計画があるのであれば、中身と進捗などについて伺います。","respondent":"廣田子ども育成課長","answer":"おおむね令和４年までに終了予定としておりまして、令和元年に３館行っておりまして、今年度については９館、令和３年度につきましては６館、令和４年度で１館なのですけれども、今後改築の計画が立っているものについては、改築工事の際に一手にやるということで。","id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"参考までに事業の目的と、あと財源なのですけれども、国や都からの補助金事業なのかどうかを聞かせてください。","respondent":"廣田子ども育成課長","answer":"ＬＥＤ化につきましては、区全体の計画となっておりまして、環境の対策であるとか、もろもろ区の施設全体、令和４年末まで目標ということで決められたものです。財源については、補助金までは、今、手元にないので、申し訳ございません。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"ＬＥＤなのですけれども、最近、ブルーライトが低減されているようなタイプのものも出てきているようなのです。なので、そういったことも勘案しながら、順次入れていただければと思うのですけれども、そういうのは仕様とかに入っているのでしょうか。","respondent":"廣田子ども育成課長","answer":"ＬＥＤ化については、施設整備課でまとめて執行委任をしている関係で、細かい仕様については手元になくて、申し訳ございません。","id":"exchange-030"}]},{"id":"topic-04","title":"区立児童相談所整備スケジュールの変更","agenda":"区立児童相談所整備スケジュールの変更","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"幾つか質問したいのですけれども、まず資料に、地域理解を深めるため、期間を十分に確保し、丁寧に住民説明を行っていく必要があるとありますけれども、理解を深めるためには、必要であれば、今回１回目を９月にやるということですけれども、何回か説明会を行う考えはあるという理解でよろしいのでしょうか。伺いたいと思います。これも伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"そういう方のためには個別等で対応してまいりますことをメインに考えておりますが、地域の皆様とのお話の中で、複数回開催することも今後は検討してまいる必要があるかと考えております。一つの選択肢として考えております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"山手通りを挟んで品川学園がありますけれども、そちらの関係者ですとか、あるいは同じ公園内に少年野球の野球場がありますけれども、そういった関係者ですとか、あるいは公園を実際に利用している利用者への説明会の案内というのも、私は必要だと思いますけれども、そちらについてはどのようにお考えなのでしょうか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"ただいまの計画説明会は、中高層建築物の建築に係る紛争の予防と調整に関する条例に基づいて行いますので、条例で定める範囲に居住していらっしゃる方に、案内を各戸へポスティングしてまいります。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"早期からの関係者への丁寧な説明、周知というのは、私は必要だと思いますので、少年野球の方ですとか、あるいは公園利用者様には、公園の中でかなりの面積を使うわけですから、掲示板を立てるなど、工夫は必要だと思いますけれども、案内をしていただきたいと思いますが、最後にもう一度伺います。","respondent":"加島児童相談所移管担当課長","answer":"公園利用者への掲示という点ですけれども、失礼いたしました。こちらの建築計画について、公園内に掲示をしてまいる予定です。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。要望にしますけれども、掲示板というのは、９月３日にそういう説明会をやりますという、計画説明会のお知らせをぜひ公園内に貼り出すべきだと思いますので、こちらは要望します。少年野球の関係者の方にも、説明会の後で「やっていたのか」とならないように、所管とも連携を取って、ぜひ周知をしていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"大きく２点伺いたいのですけれども、まず説明会についてです。人数を通常の半分程度、２分の１程度に縮小させてというのは、イメージとしては、何人ぐらいの方々においでいただくイメージを持っていらっしゃるのでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"こちらの７０名に対して、周辺住宅およそ２００戸程度にご案内をいたしますので、３分の１程度での計算ということになります。そのため、入り切れない方がいらっしゃいましたら、複数回開催することも検討しています。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"つまり、知らせたくないけれども、工事をする以上は知らせなければいけないから行うということなのか、それとも、もっと広範に地域の方々に知っていただいて、理解を進めていただきたいという思いがあるのか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"資料に記載いたしましたように、児童相談所につきましては、運営に地域理解が必要ですので、決して計画について、広く知らしめたくないですとか、そのような考えはございません。そのため、一昨年度から、近隣周辺住民の方に向けて２回、事業に関する説明会も行ってまいりました。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"それを聞いてほっとしました。今回、工事の説明会ということですので、ある程度、対象というのはあるのかもしれないですけれども、事業説明会といっても、まだ周辺の方は、あまりよく知られていない状況です。今回、オンラインで内容をご説明して見ていただけるという可能性はありますでしょうか。ご検討いただければ、そんなに難しいことではないです。","respondent":"加島児童相談所移管担当課長","answer":"委員からのオンラインでの説明会開催という点についてなのですけれども、現在、セキュリティー面等、検討を行っていないので、お答えができる状況にはないのですけれども、今後に向けて情報推進課等と検討してみたいと考えております。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"なかなか後戻りできないものだと感じております。そうすると、今の段階でお答えは難しいかもしれないのですけれども、３か月延ばした延期とはいえ、令和５年度の開設というものは、現段階でなかなか私は難しいのではないかと考えているのですが、率直なところ、どのように今後たくさんの問題を、これから３年間でクリアされていこうとしているのか、その見通しを教えていただけますか。","respondent":"加島児童相談所移管担当課長","answer":"平成３０年度になりますけれども、区立児童相談所の設置に当たって、課題の抽出を区立児童相談所設置基本方針にまとめさせていただきました。今年度その課題に照らし合わせて、区として何ができるかというのを計画にまとめているところです。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"今のところ、そのご答弁で受け止めておきます。ただ、年限にこだわらず、最終的に事故のないような万全の体制をつくった上での移管としていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"私としても、児童相談所というものは必要な施設だと考えておりますけれども、今回、説明会をやる趣旨としては、地域理解を深めるためとありますけれども、現時点で周辺の住民やその他の区民の方から、児童相談所をここにつくることはやめるべきだなどという懸念の声というか、反対の声というのはあるのでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"そういったお声に対して説明会、また個別等のお問合せを通じて、子供の森公園の一角に児童相談所を整備しますが、下水道の整備工事が終了した際には、そこの部分を含めて公園を拡張してまいりますので、そういったことで事業のご理解を求めてきているところです。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"ご答弁がありましたように、複数回の説明会というのを行うということもおっしゃられていましたけれども、ぜひ回数や、区民の方がしっかりと説明が聞けるような状況にしていっていただきたいと考えておりますけれども、改めて、冒頭述べましたとおり、港区南青山の児童相談所の一件がありましたので、実際に南青山で起こった一件も踏まえて、区としては今後どのように丁寧に説明されていくのか。","respondent":"加島児童相談所移管担当課長","answer":"今後、住民の方、関係機関の団体に丁寧に説明を行っていくに当たって、まずはこういった説明会の場を公にはご用意させていただきましたが、それ以外にも個別に何か動きがあるたび、きちんと町会ですとか、目の前の品川学園、近隣の保育園等に情報提供を差し上げ。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"３点伺いますけれども、まず、子どもの貧困問題の解消ですとか子育て支援については、まさに行政の大事な仕事なのではないかと思うのですけれども、この事業を区の税金によってではなく、ガバメントクラウドファンディングで行うという理由は何なのでしょうかというのを１点伺いたいのと、２点目は、もし仮にこれで全然集まらなかったという場合はどうなるのかというか、縮小するのか。","respondent":"三ッ橋子育て応援課長","answer":"アンケート実施の募集期間がまだ締切りではないので、今現在の状況の全体を把握しているわけではないのですけれども、子どもの食の支援事業として、またコロナの状況として、生活状況調査のすごく深いものではないのですが、実施しています。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"後半のほうは非常にいいなと思います。ぜひそのアンケートを踏まえて、必要なところに支援をしていただきたいと思います。それと、最初の質問というのは、あまりお答えになっていないというか、区であえてやらない、区の単費でやらないで、寄附形式。ただ、あえて財源を寄附に求めたのは、何か意味が、意図があってやっているのですか。そこはどういう理由があるのかというのをもう一度お願いします。","respondent":"三ッ橋子育て応援課長","answer":"ふるさと納税による今回の寄附ですけれども、単費ではないもの、本当に単費ではできないことを実施していこうと考えています。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"収支状況について、少し詳しく教えていただきたいのですけれども、しあわせ食卓事業として、既に２回行われていて、それで何世帯にお配りしてきたかというのが、下のアンケートの対象世帯の数字と見ていいのでしょうか。つまり、第１回では２５８世帯に、そして第２回では３１０世帯に食品が提供できたという読み方でよろしいのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"委員の言われるとおり、第１回目は２５８世帯、第２回目は３１０世帯です。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"２回目のほうは６,０００円ぐらいの食品をお渡しできて、その戸当たりの経費が５,０００円近くかかっているということで、食品が増えて、若干その箱が大きくなったのかもしれないですけれども、経費が、数が増えて逆に単価がこれだけ上がっていて、１世帯当たり５,０００円経費がかかるというのは、何でこのようにかかるのですか。","respondent":"三ッ橋子育て応援課長","answer":"今回、第２回目というのはコロナの本当に最中でして、配送料というものが非常に難しい部分がございまして、そこで経費がかさんでしまったことが大きいです。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、これはまた下がっていくということなのでしょうか。配送屋さんは今、コロナだからということで特別に単価が上がっているのですか。大口だとそうなるのか、小口だとイメージがわかない。","respondent":"三ッ橋子育て応援課長","answer":"来年度、今回のガバメントクラウドファンディングが成功して、しあわせ食卓事業によって配送できる段階で、いろいろと調整はしていきたいと考えています。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問","question":"今もおっしゃったように、成功してということなのですけれども、安藤委員のご質問にもあったように、集まらないと結局できなくなってしまうということで、これは受け取っている側からすれば、毎回あるかどうか分からない。先行する自治体なども、ある程度は定例化、年に何回という形で見通しを持っている。財源の話は置いておいて、とにかく見通しを持てる方向に移行する考えはあるのか、教えてください。","respondent":"三ッ橋子育て応援課長","answer":"私どもとしても、できる限り定期的に実施したいのですけれども、なかなか状況によって、いついつできますというのは、そのときの状況によりますので、できましたら寄附が本当に集まりまして、５００万円以上集まった場合には、今年度内に、まず１回は考えているのですけれども。","id":"exchange-047"},{"speaker":"あべ委員","kind":"意見","question":"例えば１回目と２回目ではかなり分量が違う。お金の集まり具合によって、１年間全くなくなってしまったりとか、今年は集まったから物凄くたくさんあるけれども、次回は３分の１とか、そういうのは受け取る側からいえば、かなりつらいものがあると思うのです。そうすると、例えば今回の第２回は前回並みにしておいて、少なくとも次回はいつありますよという考え方もなかったのかなと思う。","respondent":"三ッ橋子育て応援課長","answer":"今回の場合は２回、令和２年度は９月１０日から実施する予定を組みまして、それまでに、令和元年度に寄附していただいた方に対しても、そのお金の中で終わらせようという考えの下で、今回は実施いたしました。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後になります。アンケートも４回実施されているということで、集計はまだ１回分も出ていないのですかね。大分、集計は途中かもしれませんけれども、早い段階のアンケートというのはいくつかとっていると思います。年度の考え方もおっしゃっていましたけれども、継続的な見通しが持てる、頼れる制度にしていただきますよう、これは要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"たけうち委員","kind":"確認","question":"確認なのですけれども、恐らく違うと思うのですが、これは９月１０日にふるさとチョイスのガバメントクラウドファンディングのホームページが公開されますとなっていますが、品川区の例の３万円・５万円の応援金も、実は寄附ができますよと。そことリンクするということはなくて、単独でこれはこれでということですか。確認です。","respondent":"三ッ橋子育て応援課長","answer":"委員おっしゃるように、これは単独で、子どもの食の支援事業に対して寄附を募ってまいります。","id":"exchange-050"},{"speaker":"たけうち委員","kind":"質問・要望","question":"限られた中で、しながわ活力応援給付金のところとリンクするのがいいのかどうかというのは、いろいろとあったかと思うのですが、この５００万円がどれだけ集まるかということがあるから、そういう考えもあったかなと思いつつも、時期のずれだとか、いろいろとあるでしょうし、そういう中での、これは単独でやるということなので、それはそれで、またしっかりと取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"２点、確認をさせていただきたいのですが、１点目が実施期間のところで、９月１０日から１２月３１日というところで、これは昨年と同じ実施期間だと思うのですけれども、そもそもこの日数に決めた経緯というのは、どういう流れがあったのかを確認させていただきたいのと、先ほどの議論の中で、食品の継続的な配送というお話があって、もちろんそれは、なるべく同じ定量を。","respondent":"三ッ橋子育て応援課長","answer":"支援制度を今後は困っている方、何かを求めている方に対しては、例えば電話でお困り事であれば相談したいという方に対しては、電話で相談していったり、訪問で相談したいという方については、今はコロナの状況ですのでなかなか対応は難しいのですけれども。","id":"exchange-052"},{"speaker":"芹澤副委員長","kind":"意見","question":"特に、先ほどもお話があったように、コロナで今回、非常に困っている方も増えてくると思っていますので、今年の配送の際にも、ぜひそういった様々な支援につなげるというのを一義的に考えていただいて、取り組んでいただければと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-05","title":"障害年金を受給しているひとり親家庭の「児童扶養手当」受給見直し","agenda":"障害年金を受給しているひとり親家庭の「児童扶養手当」受給見直し","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"障害年金と児童扶養手当の返金の問題というのは、ここ数年、国会などでも取り上げられていて、何度か段階的に改善してきたという印象で、今回も一歩改善ということで、よかったなと思います。区としては品川区内に、今回の年金の子の加算部分の額と児童扶養手当の相差ということで、新たに支給が発生するご家庭が何世帯ぐらいあるか、把握されていますでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"委員のご指摘の部分というのは、把握する方法がなかなか難しい状況でございまして、今現在のところは把握しておりません。","id":"exchange-054"},{"speaker":"あべ委員","kind":"質問","question":"だから、年金事務所側から、該当する人はいないかという働きかけをしていただければ、若干捕捉しやすい、ご案内しやすいかと思うのですけれども、そうしたことというのは、区と年金事務所で何らかのコミュニケーションを取られるのでしょうか。元がこれは厚生労働省の話なので、年金事務所が協力してくれないのはおかしな話だと思っているのですけれどもいかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"そこで、例えば今回、リーフレットなどについては、例えば国保医療年金課の年金のところに対して伝えていく、またそこから伝えてもらうなど、区としてはその程度になってしまうかもしれません。もちろん、障害者福祉課とも連携を取りながら対応してまいりたいと思います。","id":"exchange-055"},{"speaker":"あべ委員","kind":"質問・要望","question":"障害者福祉課には、この件でも伺ってみたのですけれども、なかなか障害者福祉課では、障害年金の受給者というのは、その情報が入らないということで、ちょっと難しいかなと思っているのです。なので、組織違いとはいえ、年金事務所ともコンタクトを試みていただければと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、なかなか理解が追いついていないのですけれども、対象者の方には別途案内いたしますとあるのですが、これは先ほど、把握する方法がなかなか難しいという話でしたけれども、対象者の全員に送付されるわけではないということなのでしょうか。逆に言うと、案内が送付される人というのはどういう方なのかというのが分かりづらいので、お伺いします。先ほどの質問だけお願いします。","respondent":"三ッ橋子育て応援課長","answer":"ご案内する方につきましては、こちらに記載しております３名です。そのほかは、窓口に来た方に対してもお知らせしてまいります。","id":"exchange-057"}]},{"id":"topic-06","title":"ぷりすくーる西五反田","agenda":"ぷりすくーる西五反田","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そもそも論で申し訳ないのですが、なぜ幼保連携型認定こども園化を目指しているのでしょうか。現在の幼保一体施設から幼保連携型認定こども園に移行することにより、ぷりすくーるの現在の子どもの受けている保育・教育の何が変わるのか、それとも変わらないのか、その辺も伺いたいと思います。伺います。","respondent":"吉田保育施設調整担当課長","answer":"区立の幼保一体施設の、並列型か区分型かの今後の方針ですが、まだはっきりとこちらでやっていこうという、どういう方針でやっていこうというところは、特に明確になっているところではございません。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"最後、３点目ですけれども、福栄会なのですが、もうかなり具体的に合意も進んでいるので、別に今からどうこうという話ではないのですが、福栄会というのはオアシスルームとか、あるいは平塚ゆうゆうプラザとか、子育て支援事業の経験はあると記憶しているのですけれども、３歳から５歳のところの教育機能といいますか、幼稚園機能といいますか。","respondent":"吉田保育施設調整担当課長","answer":"ＮＰＯの法人化への支援はできなかったかどうかというところなのですけれども、区でも昨年度まで、法人化の支援ができないかと考えてやってきたところではありますが、根本の問題として、こちらのＮＰＯ法人が社会福祉事業を持っていないということで。","id":"exchange-059"},{"speaker":"たけうち委員","kind":"質問","question":"例えば社会福祉事業をＮＰＯとしてできるのか、そもそも分からないのですが、こういうことをしないと駄目なのだというやり取りなどがあったのかなと思うのだけれども、そうではなくて、そもそもそこが最初の段階から、恐らく子育て品川は無理だったのか、その辺はどうだったのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"私の分かっているところでは、社会福祉法人に、現在の委託・受託の関係において児童福祉施設、ぷりすくーるを運営しているというところでも、社会福祉法人へ移行できるものとして進めてきたところがございました。","id":"exchange-060"},{"speaker":"たけうち委員","kind":"質問","question":"我々としても、そんなに細かくはあれですけれども、そういう思いを持ってやられていたので、そういうのは漏れ聞いていたので、それが頓挫してしまったというのは非常に残念かなとは思ったわけですが、致し方ないのかなとは思っていますけれども、そこは、もし分かる範囲であれでしたら、受け止めとしてはどんな感じなのでしょうか。何かもうちょっとバックアップできなかったのかなと。","respondent":"柏原子ども未来部長","answer":"この件に関しまして、課長の説明したとおりではあるのですけれども、先ほどの議論にもありましたが、もともとはＮＰＯ法人のぷりすくーるという形で、幼保一体という、教育と保育が一緒になったという新しい考え方を持ってスタートさせた区立の施設だということで。","id":"exchange-061"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"今のご答弁の中にもありました、今の形だと存続することができなくなってしまうと。それはタイムリミットはいつだったのでしょうか。今の形態のままだと、いつがタイムリミットで存続できなくなるという状況にあったのでしょうか、教えてください。","respondent":"柏原子ども未来部長","answer":"そういう意味でご説明さしあげたところです。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"確かに、国の補助金という意味で途中から不利になってしまって、そのままでは続かないという状況にあるというのは理解をいたします。それと、次の法人として社会福祉法人福栄会が挙がっているのですけれども、これは一体、誰が決めたということになるのでしょうか。そこを説明してください。","respondent":"吉田保育施設調整担当課長","answer":"の話につきましては、例えば職員の給料に関してはどうしますかとか、そういう話はＮＰＯと福栄会の間で進めてきたところです。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"区が福栄会を紹介したということですが、福栄会以外の社会福祉法人も紹介したのですか。それとも、福栄会だけを紹介したのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"選定に当たってはいろいろな条件を考えたところはあるのですけれども、規模的にも、あと財政的にも有利なところとして、福栄会というところを区としては紹介した次第です。","id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"今のご答弁だと、区は福栄会だけをご紹介したということです。指定管理を受けている側からいえば、１か所だけを紹介されれば、そこと話し合いを進めるというのは、ある意味、逆らい難いことではないかと思うのですけれども、なぜ、あまたの社会福祉法人、特に幼保一体施設を運営している社会福祉法人がたくさんある中で、その経験がない法人を紹介したのか、説明をしてください。","respondent":"吉田保育施設調整担当課長","answer":"福栄会しか紹介しなかったところということになりますけれども、先ほども申し上げたところの繰り返しになってしまうのですが、社会福祉法人の規模感のところと、あとは、ＮＰＯの職員をそのまま次に引き継いでもらえるようなところで紹介した次第です。","id":"exchange-066"},{"speaker":"あべ委員","kind":"質問","question":"それはつまり、区内の法人からのみ探したということなのでしょうか。ですから、日本中の社会福祉法人で福栄会だけが職員を引き受けてくれるなどということは、常識的に考えてもあり得ないわけです。もう一度伺います。なぜ福栄会のみを紹介したのでしょうか。ご存じのとおり、福栄会というのは区のＯＢの方も多く行かれている社会福祉法人ですけれども、そのことは何か関係があったのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"職員の資質向上策とか人事考課などの制度を持っているというところと、あとは、福栄会では持っていない今回のような幼保一体施設についてのノウハウは、福栄会では今まで持っておりませんので、そちらについて福栄会としては、それを受け取ることで。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問","question":"もう１点、指定管理によって、事業者が途中で事業者変更をせざるを得なくなったときに、後続の、次に受け取る事業者というのを、前に指定管理を受けていた事業者が、事実上決めることができるのですか。例えば自転車の管理といったことも、うちができなくなったから、途中からこちらの事業者にしますということでオーケーなのでしょうか、教えてください。","respondent":"吉田保育施設調整担当課長","answer":"その際に、指定管理者制度活用に係る基本方針の中で、一定程度、事業の継続性が必要なものについては、その事業者を選べるというものもありますので、そちらのところで福栄会から、指定管理に対する申請を出していただいて、区で審議をいたしまして。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問・要望","question":"決して福栄会が悪いと言っているわけではないのです。そうした意味で、もう一度、品川区としての指定管理の選定の在り方、信頼できる透明で公平なやり方というのが、区民に説明できる形でいかに実施されるのか、このぷりすくーる西五反田についても、ぜひもう少し透明性、説明ができる順番で行っていただきたいと思いますが、何かありますか。","respondent":"柏原子ども未来部長","answer":"今回ご説明させていただいているのは、文章が分かりづらいところはあったかもしれないのですけれども、指定管理を譲りますということは一切やっておりませんで、事業を移したいというのを、ＮＰＯ側から福栄会側に移すというやり取りが、まずあったというところです。","id":"exchange-069"},{"speaker":"せお委員","kind":"確認","question":"１点、確認といいますか、先ほど事業の内容というか、保育・教育の内容と事業内容みたいなところというのは、まだ決まっていないようなお話だったのですか。事業内容は、９月下旬に説明が実施されるので、そこまでには決まるということでよろしいですか。","respondent":"吉田保育施設調整担当課長","answer":"事業の内容というか、保育と幼児教育部門はこのまま継続いたします。それから、事業者が替わる可能性があるということについて、今回保護者向けに説明会を行うというのが、３番の今後の予定のところになっております。","id":"exchange-070"},{"speaker":"せお委員","kind":"質問","question":"ということは、今までＮＰＯ法人子育て品川がやってきた内容を、そのまま引き継ぐということで決定というか、変わりないということでよろしいでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"移行に当たって準備をしているところにつきましても、福栄会で、まだ完全に決定はされていないところですけれども、運営委員会等を設けまして、今の子育て品川で行っている教育理念とか、運営方法を、新しい事業者で引き継いだ際もすんなり引き継げるよう。","id":"exchange-071"},{"speaker":"せお委員","kind":"質問・要望","question":"というのも、せっかく福栄会が運営されるので、今まで品川児童学園とかを運営されてきたと思うので、先ほどからお話のあった社会福祉的な要素とかも新たに入ってくるとうれしいなというところがあって、しかも、先ほど９月下旬は運営者が替わるというお話だけのような感じでしたが、これから入る方は、その頃には検討していないとまずいと思うので、その辺までに教育理念とか保育の内容とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-07","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"そういうこともあるとは思うのですが、あってはならないことだと思いますけれども、理由について、なぜそのようになってしまったのかというのをご説明いただければと思います。","respondent":"三ッ橋子育て応援課長","answer":"次の場所が、もうお子さんがいないためにそのようになってしまうので、それは品川区として対象となるものです。したがいまして、今回、品川区外のお子さんが亡くなっているかどうか、その確認が少し明確ではなかったです。大変申し訳ありませんでした。","id":"exchange-073"},{"speaker":"あべ委員","kind":"確認","question":"今のご説明のパターンが１６世帯２４人、全てお子さんが区外にいらして、その時期に亡くなられていたということなのでしょうか。ごめんなさい、親御さんが転出されていたということなのですね。分かりました。確認で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"あべ委員","kind":"質問","question":"細かくて申し訳ないです。今の表現、全委員会一律では行わないというのは、縮小して行うみたいな、何か含みがある表現なのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=5010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":53760,"voices":192}},{"id":"r02-20200819-5","meetingId":"r02-cm08","date":"2020年8月19日","dateIso":"2020-08-19","committee":"総務委員会","time":"午後 １時００分～午後 ４時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件抜き出しています。","topics":[{"id":"topic-01","title":"員会事務局、総務部に関わる報告を先に受けることといたします。企画部につきましては、理事者の入替え後とさせていただきますので、ご了承願います。 それでは","agenda":"員会事務局、総務部に関わる報告を先に受けることといたします。企画部につきましては、理事者の入替え後とさせていただきますので、ご了承願います。 それでは","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"前回も契約金額の中に様々熱中症の対策が盛り込まれているという説明は受けてはいるのですけれども、いかんせん、先週と今週の暑さが危険なレベルになっているだけに、発注者として現場に対して、例えば具体的なチェックリストだったり、具体的な対応策だったり、今までも何もやっていないとは言いませんし、いろいろやっているという話は聞いているのだけれども、先週、今週、今後と、あまりにも暑いので。","respondent":"小林施設整備課長","answer":"もちろん現場で働いている方もそうですし、現場に我々施設整備課の職員が検査等で行くこともありますので、お互いその辺を注意しながら対策を進めている、今後も進めてまいりたいと思ってあります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"元請け、下請け、また、２次下請け、様々現場ではあるかと思います。とりわけ下請けになればなるほど、対策したいけれども、それだけの準備や資材がないという状況もあるかと思いますので、ぜひ隅々までこういった対策が徹底できるように、区としても見ていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、落札された企業は、私、あまり記憶にないのですが、入札参加企業が増えたと考えていいのでしょうか。そして、今、どうしても我々もお聞きしなければいけないのですが、感染症対策というのは、これから世界的にもやはり求められる時期だと思うので、それに対する設備の設置等は、何か特に対応を考えられているのでしょうか。","respondent":"東野経理課長、小林施設整備課長","answer":"ＪＶ工事につきましても同じでございまして、こちらも制限をかけておりますけれども、４企業体が応募をされたという形になります。やはり３密を防ぐための一つの方策として、換気の実施というのは国からも言われておりますので、そういった観点からいけば、この施設につきましても、換気設備をしっかり各室に設けておりますし、また、各保育室の天井には。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"今まで聞いたことがあまりなかった事業者だったのですが、区内業者を使っていただけるということで、ただ、この金額でＪＶをする意味があるのか私には分からないですが、多くの方、多くの業者が参加して区の仕事を担っていただけるということは、ある意味でいいと思うので、今後もよくその辺、業者のことも考えながら、また、もちろん設備的なこともありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ありがとうございました。屋上ということで理解できました。おっしゃったとおり、右側に園庭があるので、その園庭側にエアコンの室外機を設置したら、熱風とかが園児に当たります。その確認をしたかったのです。分かりました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"八潮西保育園大規模改修機械設備工事請負契約","agenda":"八潮西保育園大規模改修機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。ぜひ先ほど申し上げたとおり、感染症対策についても今後考えていただきたいと思います。は現行での安全な保育園を目指して造られると思いますので、しっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-03","title":"八潮学園屋内運動場空調機設置機械設備工事請負契約","agenda":"八潮学園屋内運動場空調機設置機械設備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいのですけれども、学校体育館にクーラーを入れるという方向が少し前に出て、日常の授業や避難所環境の改善を含めて進められているという話は聞いているのですけれども、今回は、要するに、金額が大きいから委員会の報告になったということなのですよね。全体としてはクーラーの導入が進められているという方向は聞いているのだけれども、そこだけ説明していただけますか。","respondent":"東野経理課長","answer":"今回につきましては、ガスヒートポンプというタイプを、アリーナおよびもう一つの体育館に設置するということで、９,０００万円以上の金額的に大きな工事となったいうことで、本委員会に報告させていただいたものです。","id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。今回の空調設備の設置は、３年計画ぐらいでしたでしょうか。学校体育館に空調設備をつけるという計画の中で、この八潮学園ということでよろしいですかね。それから、工期が１月１５日となっておりますが、これは生徒たちがいる中での工事になるのか。どれぐらいの期間なのか、スケジュールも教えていただきたいと思います。","respondent":"東野経理課長","answer":"今回、令和２年度につきましては、第一体育館、アリーナへの設置ということで、２年計画で進めているものです。","id":"exchange-008"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。これは何日間かかかるということですね。分かりました。では、居ながらにしての工事ということですので、音ですとか、差し障りのないようにご配慮いただきながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"ほかによろしいですか。では、私のほうから１点だけ確認です。全ての件に関してですけれども、予定価格というのが出ておりますが、先ほど感染症対策というお話がありましたけれども、工事においての感染症対応の金額というのは、予定価格に含めているのでしょうか。","respondent":"小林施設整備課長","answer":"新型コロナウイルス感染症対策の費用ですが、国や都から指針が出ておりまして、それにかかった費用については、工事が始まった後にしっかり設計変更なり対応することが、実費がかかった分について精算することが指針等で示されておりますので、この後、工事契約が終わった後に。","id":"exchange-010"}]},{"id":"topic-04","title":"会計事故の調査結果","agenda":"会計事故の調査結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ伺いたいのですけれども、やはり１４億円という金額の大きさから、区議会への報告をはじめ、プレスリリースもされ、一部マスコミでも取り上げられましたが、やはりこうしたことを繰り返さない、また、ほかの自治体にも何か今の執行体制に不備がないのか考えるきっかけになるためにも、マスコミへのプレスリリースや、また、ホームページでの報告ですね。","respondent":"立川総務課長","answer":"この総務委員会が終わりましたら、区のホームページに会計事故に関しまして報告をしたいと考えているところです。","id":"exchange-011"},{"speaker":"松澤委員","kind":"確認","question":"確認したいのですけれども、事故の概要の経過に、２７日に指定銀行にデータを送信していますと。お互い認識に違いがあるのに、指定金融機関は間違っていないという認識だと、何か少しちぐはぐかなと、この文面では見えてしまうのですけれども、行政側と指定金融機関の中で、解決といいますか、そういう話はしっかり持たれたのでしょうか。","respondent":"立川総務課長","answer":"今、委員ご指摘のところなのですけれども、指定金融機関側の主張といたしましては、事務フローのとおりだということでございまして、当日の確認すべきデータは届いていないことというのは事実であって、間違いではないという、そういった考え方に基づく発言と理解しています。","id":"exchange-012"},{"speaker":"松澤委員","kind":"確認","question":"分かりやすかったです。それは確認すればいいのにと素人ながら考えてしまうのですけれども、そういうことは起こり得る、今後もあり得ますよね。１４億円でしたか、大きな金額ですので、再発防止に向け、指定金融機関と再協議というのもありますけれども、そこでしっかりとお話をし合った中で、またこの委員会にこういうことを話しましたという報告はあるのでしょうか。","respondent":"立川総務課長","answer":"今回の報告といたしましては、会計事故調査検討委員会の報告ですので、後日、みずほ銀行側との協議がまとまった時点で、所管のほうからしかるべき報告等をしてもらおうと考えているところです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"確認","question":"若干重なるところがあるのですけれども、みずほ銀行のほうにも、事務フローの中で、前の日にやったかどうかの確認は必要ないというふうに事務フローがなっていて、一方、品川区のほうも、昨日送ったということを証明できるような、そこのスキルが足りなかったというふうに伺ったのですけれども、その辺について、品川区のほうにも少し手続的に瑕疵があるので、それ以上強くみずほ銀行側に。","respondent":"立川総務課長","answer":"会計事故調査委員会のほうで会計管理室のほうから再発防止策について聴取いたしまして、既に実務的には今回のようなことが二度と起こらないような内容の対策を講じているところですけれども、その具体的な内容について、今後。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうあるべきかと思ったので伺いますが、いかがでしょうか。","respondent":"立川総務課長","answer":"そういったダブルチェックを具体的にできるような対応というのを所管のほうでは考えておりまして、既に一部実施していますので、委員のご指摘も踏まえて対応してまいりたいと思います。","id":"exchange-015"},{"speaker":"吉田委員","kind":"意見","question":"すみません、先ほどの繰り返しになってしまうかもしれないのですけれども、お互いの事務フローも知らなかったと。品川区からしてみたら、前の日の分はチェックしないというみずほ銀行側の事務フローを知らなかったわけですよね。その当日の担当者が、当日伝票がなかったら、それはデータがないものとして品川区のほうに報告した。知らないのが普通なのかもしれないのですけれども。","respondent":"立川総務課長","answer":"今までこういった事故というか、こういった指摘というのは、みずほ銀行側からも導入３年でなかったと。担当者のほうも、経験が浅かった。どちらも浅かったということで、こういった事故が起こってしまったというような認識です。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"しつこいようですけれども、いろいろなことも重なってしまったということだと思うのです。当然、ミスがないようにというのが第一ですが、もし何かあったとしても、その辺のカバーができるようなところまできちんと協定を結んで、協定なのか契約なのかは分かりませんけれども、そのようにすべきだと思うのですけれども、その辺はいかがでしょうか。","respondent":"立川総務課長","answer":"今後、指定金融機関との協議を進める上で、文書としてきっちり残していきたいというふうに考えております。","id":"exchange-017"},{"speaker":"湯澤委員","kind":"質問","question":"４月２８日に、先ほど来おっしゃっていますけれども、届いていないと金融側から強く言われたから、再度振込データを作成し送信しているということでありますけれども、仮に今後、まずないとは思うのですけれども、金融機関からまた強くそういうことを言われたときには、どういった形で再発防止をするような対策を取るのかというのを教えていただければと思います。","respondent":"立川総務課長","answer":"共通マニュアルの内容ですが、今まで２つの係で対応が違っていましたデータ送信の手順というのをまず統一いたしました。","id":"exchange-018"},{"speaker":"湯澤委員","kind":"質問","question":"そうすると、４番にあります再発防止策というのは、既に行っているということでよろしいのでしょうか。","respondent":"立川総務課長","answer":"当面、絶対起こらないようにするための対策は取っているところですが、今後時間がたつに従いまして、またその辺が曖昧になるとか、周知徹底されないということが起こらないように、みずほ銀行側と協議いたしまして。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。今回、４月３０日着金ということで処理が進められていったと思いますが、ちょうど４月２９日が祝日であったということもあって、早めの手続がされていたのでしょうか。ゴールデンウイークに入る、そういう時期であります。そういう区民とか業者の方からのご指摘だけで分かったのか、銀行側からは何か一報があったのか、そこら辺を教えていただきたいと思います。","respondent":"中山会計管理者","answer":"振込の手順です。今回の口座振込と随時払込、こちらにつきましては、着金日の１日前までに処理をすることとなっています。３０日の前の日が２９日だったものですから、通常であれば２８日までに処理をする。たまたまその日、担当が休みだったので、２７日に処理をしたです。","id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そこら辺、少し不思議だと。お金が動くわけですので、同じような金額が１つのところに行くとなると、「あれっ」と普通思うと思うのですが、そこら辺の確認が銀行側も取れなかったというのはどうかと思うのですけれども、何かそこら辺に関しての、どうなのでしょうか。何かその点の話が銀行からあれば、教えていただきたいのですけれども。","respondent":"中山会計管理者","answer":"１回目の正当な振込の後、２回目の送金をしてしまって、それで実際には決済前振込方式を銀行のほうでは取っていたということですので、通常であれば、預金残高がなければ、そこで送金がストップされてしまうところではあったかと思うのですが、銀行側でも。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"分かりました。今、原因の究明をして、再発防止策を作っていただいておりますので、これだけ大きな金額を動かす職員の方も責任を非常に感じていらっしゃることと思うのですけれども、再発防止策にまた努めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-05","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"具体的には、共産党は、感染震源地と言われるエピセンター、つまり、感染の発生が多く確認されている、また、リスクの高い地域を限定して、そこで働いている方、住んでいる方全員に検査を行って、感染力を持つ無症状者を発見し、保護・隔離して治療につなげていく、そういう検査が必要だと思うのですけれども、検査自体は重要だという答弁は今までもありましたけれども。","respondent":"立川総務課長","answer":"２つ質問を頂きました。１点目の症状がない者への検査の件ですが、こちらは国や東京都の動向等を注視いたしまして、区として対応を決めていきたいと考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、大井町駅東口については、所管に問合せをしていただきたいとともに、対策本部として、全体で情報共有すべき事項だと思います。これをぜひ毎日更新にしていただきたいと思うのと、区民はこの不安払拭や正確な情報が伝わると同時に、区自身も共通認識が広がっていくことにもつながってくると思うので、１週間ではなく日々の更新にしていただきたいと思っているのですが、その点についても伺いたいです。","respondent":"立川総務課長","answer":"区の独自の方針はないのかという、そういったご質問ですけれども、これまで答弁いたしましたとおり、国や都の方針や動向を常に注視しながら、区として対応していくべきものと考えているところです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に２点だけ伺いたいのですけれども、資料にも、４の主な施設の状況の(3)で制限付きの運用（定員の制限など）とありますけれども、区民集会所や中小企業センターや文化センターでは、簡単に言うと、５０人の会場であれば、３分の１の利用者でという案内がされておりまして、それはそれで必要な対応だと思います。ぜひそこをご検討いただきたいと思うのですけれども、いかがですかということです。","respondent":"立川総務課長","answer":"障害者のある方への対応ですが、こちらは所管のほうにそういったご意見があったということを伝えてまいりたいと思います。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問・要望","question":"実際、課長にお聞きしますと、全然そんなことはなく、濃厚接触者をきちんと確認してからという対応をしっかりしているのですけれども、そういった情報がしっかり施設に届いていないということで、働く人にとってすごく不安であったり不満であったりというのが大変多く聞かれるので、情報共有という部分では、全体は難しいにしろ、その近くの施設であったり、患者さんが流れるという部分に関しては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"情報共有というか、情報発信で、ずっと生活者ネットワークとしては要望をしていることなのですけれども、やはりどこかでクラスターなり、例えば、公的な保育園とか小学校で発生したときに、どこでどういう発生があったかということは公開してほしいということが、生活者ネットワークにご意見としてたくさん来ます。私はというか、生活者ネットワークとしてはそのように考えております。２点、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の方向性ということもありますけれども、やはりそれでは足りないということで、例えば、ＰＣＲ検査センターなども、国や都のやり方では足りないというところで、各自治体が判断して広げていっているところもありますし、品川区としてもそういうことを行っているわけですから、私もやはり本来国がやるべきことだと思いますが、それで足りないということであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"アプリを入れて濃厚接触者だという通知が来たのだけれども、それはどのようにしてくれるのですかということに対して、どこにも答えがないと感じておりまして、ぜひそこは、これは国がやっていることなので、国の対応、国に求めることも当然だと思うのですけれども、例えば、品川区としては、品川区独自の対応として、そういう濃厚接触者ですと通知をされた方に対して。","respondent":"立川総務課長","answer":"アプリの通知ということなのですけれども、なかなか難しいところかと思っているのですけれども、基本的に、厚生労働省の考え方といたしましては、ざっくり言ってしまいますと、お互いにマスクをしている場合は濃厚接触には当たらないというのがありますので。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"それも本当に数秒で確認できますので、そういうこともそろそろ考えたほうがいいのではないかと。なぜお店のことを言うかといいますと、私も本当に２月から残念ながら居酒屋に行っていないというのが現状なのです。感染の公表ですが、やはり今、どうしても差別的な扱いを受けるということが、これだけ国民の皆さんの恐怖心をあおったのですから、当面の間、それを拭うのは難しいかと思うのです。","respondent":"立川総務課長","answer":"１点目のサーモグラフィーカメラの導入ですが、学校では既に導入を進めているということで聞いております。庁舎におきましては、どういった形がふさわしいかというのは検討していきたいと考えております。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"何しろ不安だらけの世の中なので、何とか少しでも払拭できるように、いろいろ考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-06","title":"品川区新型コロナウイルス対策支援寄附金の募集","agenda":"品川区新型コロナウイルス対策支援寄附金の募集","exchanges":[{"speaker":"松澤委員","kind":"確認","question":"寄附金なのですけれども、区のホームページを確認しました。確かに上のほうはコロナ関連でいっぱいだと思うのですけれども、すごくいい取り組みなので、もっと目立つところに上げてもいいのかと個人的に思ったのが１点と、現在は、１６.６％で６５人、百六十何万円の寄附があるのですけれども、これは行政として今のこの数字の上がり方をどのように捉えているのか。","respondent":"伊東税務課長","answer":"ほかに、先ほど申し上げたとおり、いろいろな媒体を使っているのと、広報のほうも異例に何回も載せていただく予定でおりますので、そういう形での周知でも広めていこうかと考えているところです。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"とてもすばらしい取り組みなので、トップページに何とか載せていただいた努力と、寄附金がしっかり１,０００万円に到達することを願うとともに、もう一つ聞きたかったことは、この支援をやることによって、医療支援、保育支援、介護支援、障害者支援と、活用先がいろいろと書いてありますけれども、これというのは、医療従事者であったり、保育関係の方、介護関係の方、障害者の方に。","respondent":"伊東税務課長","answer":"目標達成１,０００万円ということで、その中でそれぞれの分野というところで選択していただいておりますので、その集まり具合というのを見ながら考えていかなくてはいけないかと考えています。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうですね。例えば、介護士の本当に困り事といいますか、ここにこうやって使ってほしいとか、こうあるべきだということを、多分、大々的にそういう宣言をすることによって、支援に共感した方が寄附金という形で募っていただけるのかと思いますので、そういったアピールといいますか、そういうのもしっかりしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"吉田委員","kind":"提案","question":"そうではなくて、何とか役に立ちたいという区民の気持ちが先にあるのだ、だからそれを品川区として形にしましたというほうが、それはどう感じるかは個人のいろいろな感じ方もありますけれども、私個人としては、区民の声を活かした制度であるというほうが納得度があってというか、共感者が増えるかと思いましたが、ここの今ホームページに出ている意図というか、もし何かご見解があれば伺いたいと思いますが。","respondent":"伊東税務課長","answer":"そういう考えといいますか、問合せ等も区民の方から、何か今回の新型コロナウイルス感染症の関係で寄附の受け皿はないのかという話があったのは事実でありまして、その後いろいろと検討を重ねて、今回こういう形での募集を開始したです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"意見","question":"やはりぜひ言葉で書いていただかないと、その気持ちは伝わらないと思います。本当にそういう何とか役に立ちたいという区民がたくさんいるというのは私も承知していますし、そういう方たちの気持ちをぜひ活かすような制度を品川区は作るべきだと思いますが、この表現だと、例えば、こういう寄附先とかいうレベルで１,０００万円という金額だと、何かちょっとなと。これは意見で結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり一言、区民の善意を募って福祉現場等に支援をしていくという取り組みそのものは、善意を受け止めて、それを活用していただきたいと思いますが、先ほどからいろいろ議論がありましたように、寄附金の活用先を見ると、これはそもそも感染症対策として必要でしょと思われるものなので、これはこれで、寄附金の使い道としては構わないけれども、そもそもこれは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-07","title":"指定管理者選定における外部委員導入の試行","agenda":"指定管理者選定における外部委員導入の試行","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"質問としましては、総務省から外部委員の導入が言われている中、私は遅過ぎたと思っていますけれども、このタイミングをどう考えているのか伺いたいのと、あと、２点目は、外部委員２名ということですけれども、選定委員会が例えば１０名で、２名が外部委員だと、結局８名が区の関係者ですから、それで透明性・客観性をどう担保するのかということにもなると思うのです。望ましくは、半分だと思うのです。","respondent":"佐藤企画調整課長","answer":"３点目の誰が外部委員を決めるのかですが、基本的に選定は各所管のほうで行いますけれども、選定委員に関しましては、指定管理者制度を所管する企画部のほうでチェックをして、様々、公平性・透明性を担保できるようにアドバイス等をしていきたいと考えております。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"選考委員会における財務状況だったり資産状況のチェックの話がありましたけれども、外部委員の方にはそこを特にお願いしたいという説明だったのか、今の説明が理解できなくて、もう少しご説明いただきたいのですけれども、いずれにしても、今ご説明あったように、他の自治体では半分を外部委員にして、客観性・透明性をより担保できるようにしているという中で、本区の２名というのは少ないのではないかと。","respondent":"佐藤企画調整課長","answer":"１点目、財務状況のチェックのところなのですけれども、私の説明が悪くて申し訳ございませんでした。選定委員会の中身なのですけれども、選定委員会の中では、経営状況、業務実績、サービス内容や体制、あと、経費というものに関してそれぞれチェックをします。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"この間もなぜそのような判断に至ったのかという事業計画書だったり、評価の点数だったり、他の自治体ではホームページで公開しているところもありますので、客観性・透明性の確保という視点をさらに高めるためにも、選定委員会における外部委員の導入だけでなく、選考過程の公表、それをぜひこれを通じて検討していただきたいと思うのですが、最後にいかがでしょうか。","respondent":"佐藤企画調整課長","answer":"今は詰めの段階といいますか、そういう意味で今回外部委員を導入するというところで、委員ご指摘の選定の際の公表の内容に関しましても、今検討をしており、そういったご意見は様々頂いていますし、私どもも透明性を高めたいという意識はありますので。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどの外部委員選定のときの、外部委員に求めているのが経費のというふうに聞こえたのですが、だから、そもそもがその団体の財務状況の点検と、それから、今度行う事業についての事業計画というか、それに伴う収支とか、そういうところを見ていくための外部委員ということなのでしょうか。ごめんなさい、理解が悪くて。もう一回ご説明いただければと思います。","respondent":"佐藤企画調整課長","answer":"ご質問を２点頂きまして、１点目のスケジュール感といいますか、本格実施に向けてのスケジュールですけれども、先ほどご答弁したとおり、平成３０年の後半からずっと検討していまして、今、詰めの段階ですので、今回の外部委員の導入の結果を踏まえて。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"９月に試行をして、今年度中に本格実施を行う。試行と本格実施の間が短いような気がするのですが、その辺の試行の結果、どのように改善とか、例えば、先ほどの外部委員の人数のこととか、その間にそれこそスピード感を持って考えていくと思っていいのでしょうか。私たちとしても、外部委員２名というのは少ないのではないかと思って伺うのですが、その辺についてはいかがでしょうか。","respondent":"佐藤企画調整課長","answer":"本格実施に向けては、先ほどご答弁したとおり、今年度中にまとめて、来年度から進めていきたいと考えております。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのようなスケジュールで進めていただくということであれば、きちんとした形の外部委員の導入ということをやっていただきたいと思います。説明に出てこなかったような気がしたのですが、それは前提として考えてよろしいのでしょうか。ごめんなさい、それだけご答弁いただきたいと思います。","respondent":"佐藤企画調整課長","answer":"労働環境チェックに関しましては、ご案内のとおり、平成２６年から４年目の事業者に対して試行という形でやっておりますが、ほぼ毎年やっていますので、そういった形で進めていきたいというふうに考えております。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点確認させていただきたいのですけれども、間違っていたら言ってください。やはり利用者との関係を踏まえると、事業の継続性というのは必要だと思うのです。","respondent":"佐藤企画調整課長","answer":"委員ご紹介のとおり、何度でもという取扱いはできるというふうに読み取れるのですけれども、それに関しましても、結果として同じ事業者であることはあると思うのですけれども、公募をかけるということは、何年延長するかはまだ検討しているところなのですけれども。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、意見ですけれども、やはり介護施設や障害者施設、保育施設も、事業の継続性はとても大事だと思います。公募を出して競い合って結果同じであってもという話がありましたけれども、やはり今まで積み上げられた技術だけでなく、利用者との信頼関係や、地域との関係というものが積み上げられていますので、そこはぜひ引き続き重視をしていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-08","title":"令和２年度都区財政調整交付金当初算定結果","agenda":"令和２年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"逆に地方消費税交付金が２８％増ということですけれども、そんなことはあるのか、伺います。しっかりと都市部、また、東京で感染拡大を抑止するという部分にしっかり財調算定させるということはとても大事だと思うので、どこまで新型コロナウイルス感染症対策が算定されているのか、算定されていないもの、調整中なものは何か、そこを伺いたいと思います。","respondent":"品川財政課長","answer":"その段階で出された令和２年度の見込額とほぼ変わらない数字となっておりますので、令和２年１月時点ぐらいの状況で想定をした収入額となっているというのが状況です。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"基準財政収入額が、基準日が現状とは大分実態が異なると思いますので、そこはよく注視していただきたいし、注視しているのだと思っています。財調算定に新型コロナウイルス感染症対策をどこまで入れるのかというところは、今後調整をしていくということですけれども、区として、また、２３区として、具体的に都に求めている新型コロナウイルス感染症対策というものは何なのか。そこをご説明いただけますか。","respondent":"品川財政課長","answer":"まだ全然分かりませんけれども、例えば、ＰＣＲ検査とか、そういうところは十分、当然、こういう財調の対象になるような部分ではないかと思いますので、その辺についてはまた今後の交渉の中で出てくるものだと考えております。","id":"exchange-047"}]},{"id":"topic-09","title":"マイナポイントによる消費活性化策","agenda":"マイナポイントによる消費活性化策","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今、コロナ禍の下、ここに２,４７８億円も国が予算をつける。一体何を考えているのだと思います。マイナンバーカードが普及されない、持っていても大して役にも立たない、使う機会もない、だから税金で５,０００ポイント、２万円分をぶら下げて、プレミアム率２５％、それで普及を図るなんていうのは、本当にずさんな事業だと。質問は１０分の１０かどうかだけご説明いただきたいと思います。","respondent":"山本情報推進課長","answer":"国の補助ですけれども、基本的にお金の流れとしましては、国のほうからキャッシュレス決済サービスのほうに行くという形になるので、この事業自体、区のほうに補助はないのですけれども、周知、申込支援等に関して、パソコンの利用料だったり、そういった部分は１０分の１０。","id":"exchange-048"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。１つには、マイナンバーカードの普及もあるということです。現状、これが周知されて、推進されている中で、品川区のマイナンバーカードの普及がどれだけ今のところ増えているのかとか、あとは、申込支援がどれだけ活用されているのかという現状をお聞かせいただきたいと思います。","respondent":"山本情報推進課長","answer":"申込支援のところですけれども、地域センターを含めまして、７月の１か月で約７００名の方に、予約の支援というところを行ったところです。","id":"exchange-049"}]},{"id":"topic-10","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"質問なのですけれども、求める情報が探しづらい、トップページの情報量が多い等の課題があるということですけれども、どういうテーマやどういう項目に検索が多いのかという分析は既にされているのか。少しホームページで調べてから問合せをするというのが、どうも我々世代の感覚なのです。","respondent":"大澤広報広聴課長","answer":"そういう区が持っている情報が区民に現在はフィードバックされていないので、リニューアル後は一番上に、今よく見られているページということで、例えば今ですと感染症対策とか給付金についてという、見られているページの上位５項目か６項目を出して。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に遊びに行くときもそうですけれども。ただ、自治体の場合はどうなのでしょうか。やはり公的機関が発表する情報ですから、概要も必要だし、より詳しい情報も必要だと。これは意見を述べさせていただきたいと思います。やはり既に目的が明確でホームページにたどり着きますので、そういう利用者の目線に立ったリニューアルを丁寧に進めていただきたいと要望して終わりたいと思います。","respondent":"大澤広報広聴課長","answer":"区民の方がやはり何かでお困りになったときに、区のホームページを開くということが一番だと思っていますので、困ったときに解決方法を探せるということを一番に考えて、リニューアルに臨みたいと考えております。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどご報告いただいた今後のアクセシビリティの確保に向けてというところで、各課所管の意識向上ということがあったのですけれども、統一感のなさというのと、各所管がそういう情報を上げて、うちの所管としてはぜひこれをというのを上げてくるというのも必要かと思うのですが、全体の統一感ということを考えると、各課職員のというだけでは駄目なのではないかと思うのですけれども。","respondent":"大澤広報広聴課長","answer":"１点目の見やすさでありますけれども、１つ作って、それでフィックスということではないので、いろいろ区民の方からお問合せを頂いたり、ご意見を頂いたりする中で、更新をかけて見やすくするように日々変えていくように努力はしていますし。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、今後リニューアルを検討されるときには、パブリックコメントというのは区民の声を募集する、私たちはパブリックコメントよりもっと前に、そういう意見を募集する前に説明会とかをもっと開いてくれというのが要望ですけれども、やはり最終的にパブリックコメントが区民が公式に発言できるというか、そういう場だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、それぞれの所管がそれぞれの自分たちの情報を多くの区民の方に聞きたい、多くの区民の要望に応えたいということがこのようにつながってきたので、ただ、これは際限なくきっと続くのかと思うので、見やすいというのはどうなのか。今、どうしようというのも、どれが優先だというのは、私も一言で言えないので、広報広聴課のご努力をこれから期待するしかありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"湯澤委員","kind":"意見","question":"先ほど吉田委員からもありましたけれども、このように行けばそこに到達できるのだみたいな、そういうのがあったりすると思うので、やはり私なんかは、個人的な意見ですけれども、かなりシンプルにして、検索すると、もちろん行政側としては、言いたいこと、伝えたいことはたくさんあると思うのですけれども、区民の方はもちろん知りたいことがすごくあったとしても、区外の方、海外の方とかにとっては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"何点か、少し気になったことを質問させてください。アクセス障害対策についてです。聞き漏らしてしまったのですけれども、何かそのことによってアクセスが集中しても、見れなくなることがないというお話があったのですけれども、その対策をすれば、もし仮にこの前みたいな大災害が起こったときに、絶対にそういう障害が起こらないということなのでしょうか。","respondent":"大澤広報広聴課長","answer":"絶対に障害が起こらないかと言われると、２２万世帯からアクセスが一気にあると分からないのですけれども、まず大丈夫だと考えています。","id":"exchange-056"},{"speaker":"松澤委員","kind":"質問・要望","question":"自分がこうやって調べたいことがすぐ返ってくるというシステムが私はすごくうれしいというか、周りにも結構紹介したのですけれども、今はまだ、しながわ活力応援給付金しかないのですけれども、ああいうのがどんどんいろいろ増えていくと、多分、皆さんおっしゃるとおり、区民が知りたいことがそこに情報が載ったという、それがチャットボットで会話をパンパンとやりとりできるようになるということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問","question":"すみません、１個だけ質問。先ほどパブリックコメントというお話が出てきたのですけれども、それをチャットボットでやり取りする予定というのは今のところありますか。","respondent":"大澤広報広聴課長","answer":"チャットボットは。","id":"exchange-058"},{"speaker":"松澤委員","kind":"意見","question":"すみません、間違えました。チャットボットは、防災とかいろいろ、活用されてますよね。なので、画面にパブリックコメントみたいなのを表示して、そうすると、すぐに投稿できるといいますか、パブリックコメントしやすいといいますか、ホームページに飛んで探して行うよりも、行いやすい。ぱっと気になったときに携帯で打てるかと。画面にパブリックコメントという欄があってもいいのかと思いました。","respondent":"大澤広報広聴課長","answer":"戸籍とか保育園関係です。そのほかにも、チャットボットを使うものは今検討していて、同時にそれはＬＩＮＥでも使えるようにしていきたいと考えていますが、具体的にパブリックコメントを今どうしようというところの検討はしていないです。","id":"exchange-059"},{"speaker":"新妻副委員長","kind":"質問","question":"ありがとうございました。今現在のホームページを広報広聴課の皆様が作成していただいていると思うのですが、広報広聴課の皆様の中に、ホームページとかの専門の方がいらっしゃるのかということと、あと、関わっている人数についてもお伺いしたいと思います。","respondent":"大澤広報広聴課長","answer":"それについての取りまとめや検収を担っているのは、広報広聴課の報道の担当職員４名が携わっています。専門的な職員というのは、業務の中で専門知識は身につけていますが、それに特化した職員というのはいませんので、それは専門業者と相談しながら進めております。","id":"exchange-060"},{"speaker":"新妻副委員長","kind":"質問","question":"ということは、デザイン的なところというのは、外部の業者がやっていらっしゃるということでよろしいですか。","respondent":"大澤広報広聴課長","answer":"デザインそのものは、業者と職員とで相談しながら進めているという形になってあります。","id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。ところが、今の品川区のホームページでは、だらっと書かれた文章がある同じページに飛んでいくというのが非常にもったいないと思っていまして、そういうところのぜひ工夫を、広く知りたいという要望もあるかと思うのですけれども、同じところにクリックする先が飛んでいくというのは、情報提供としてはどうなのだろうというところを感じますが、いかがでしょうか。それが１点です。","respondent":"大澤広報広聴課長","answer":"緊急情報については、おっしゃるとおりで、分かりやすい情報になるように努めてまいりたいと思います。","id":"exchange-062"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。今、情報をためていただいて、準備されているということでしたので、できたら、文章として載せるのではなくて、ＬＩＮＥのマーク自体を載せていただく。品川区公式アカウントを。それですぐにＬＩＮＥだというのが分かるわけです。なので、そういう見せ方もぜひ工夫していただきたいと思いますが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥの周知につきましては、より分かりやすく、簡易に登録できるように工夫してまいりたいと思います。","id":"exchange-063"},{"speaker":"新妻副委員長","kind":"確認","question":"お願いいたします。最後に１点だけ。先ほども他自治体のホームページの話しがありました。広報広聴課の皆様は既に２３区全ての自治体のホームページは確認をしていただいているかと思います。高橋伸明委員からもありましたが、やはり世田谷区、渋谷区、港区は、非常に作りがいいという印象を受けます。ご答弁いただければと思います。","respondent":"大澤広報広聴課長","answer":"広報広聴課で他区のホームページは研究しておりますので、いいところをまねして、いいものにしたいと思います。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2176#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":61562,"voices":192}},{"id":"r02-20200820-14","meetingId":"r02-cm08","date":"2020年8月20日","dateIso":"2020-08-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"まだ私の頭の中でも十分にこなれていないのですけれども、素朴な問題意識で、労働時間、勤務時間の問題がこのテレワーク、特に在宅勤務ということで、私の頭の中には一番初めに素朴に引っかかったのですが、今のご説明を伺っていると、電話で出勤・退勤の報告をして、それで管理なさったということだと思うのですけれども、しかし課題ということで。","respondent":"黒田人事課長","answer":"週の労働時間は、区の職員の場合３８時間４５分と定められておりますので、そういった中では、今回の在宅勤務の中ではそういった労働時間の問題については、逆に言うとやれる仕事が少ないというところが課題かなと思っています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"私も実態を全く知らないままで、素朴な問題意識で申し上げて申し訳ないのですけれども、とにかく在宅勤務ということになったときに、その辺で超過勤務あるいは今例に挙げられたウェブ、ＩＴ企業でのということで、限りなく労働してしまうというようなことに追い込まれると、あるいは追い込まれやすくなる労働環境になると大変だなというところを非常に素朴に思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"ですから、確かにテレワークを進めるということは、一部はよいかと思いますが、積極的にこれもあれもというようなＩＴ業界と同じような感覚では、私は進んでいってほしくないと思います。そうすると家にいる。そして、どうしても個人的に１人でやることですから、孤独になったり、それから一歩も外へ出ない、出る機会がそれだけ減るわけですから、体力的にも身体的な問題にも影響が出てくるのかなと。","respondent":"黒田人事課長","answer":"コロナ対応で超過勤務が増えた職場もあるのではないかというお尋ねですが、こちらの対策本部の中でも、仕事が縮小できる職場については繁忙な職場へ応援するということを方針として打ち出して取り組んでまいりましたが。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは実際に業務改善したわけですから、そうなるのは反面いいことかもしれませんけれども、逆に様々な影響が出るかと私は思いますので、職員のことも大事ですけれども、今後も区民への対応をしっかりやる、区民に寄り添った業務をきめ細かく今後も推進していっていただきたいと私は思います。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"お聞きしたいのが、今回この新型コロナの面ということで、２か月あまりテレワークを実施したということですが、職員の感想というか、実施した実際の状況というのはどのような声があったのかということを伺いたいのと、今はそこまで実施はしていないということでよいかということをお聞きしたいと思います。","respondent":"黒田人事課長","answer":"お尋ねの職員の感想がどうであったのかですが、直接的なアンケートを職員に取ったわけではございませんけれども、聞いたところでは、在宅勤務をした職員からは、通勤しなくて済んだのでよかった、またやりたいというような声もあれば、できない職種がありますので。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった中で、この課題に保育園、清掃等の施設や現場において行政サービスを行わなければならない業務が今挙げられているわけなのですが、やはり現場に行かないとできない仕事、先ほどから説明されているので、これがなかなかテレワークには向かないという話もありますけれども、課題に挙げていらっしゃるというのは、今後変えていかなくてはいけないという認識でいらっしゃるのか。","respondent":"黒田人事課長","answer":"向く仕事と向かない仕事がある中で、変えていかなければと考えているのかですが、自宅で勤務することだけがテレワークではありませんので、例えば庁舎で会議をやって、施設長会等々があれば、例えば業務連絡であればウェブ会議を使うというのも一つのテレワークでありますし。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。テレワークに適さないということで、その業務がなくなってしまうということなのか、ちょっとその辺がイメージできなかったので伺いたいのと、もう一点、ＩＣＴの活用で職員による直接対応の縮減を図るというところもあるのですが、これもどういったものが想定されているのか。これからの検討ということではありますが、今、想定されているところを伺いたいと思います。","respondent":"黒田人事課長","answer":"ただ一方で、行政の意思決定の中で、全てその電子データの中で完結するというのは難しい面もありますので、ここにつきましては、要は行政の場合、いろいろな契約だったり行政処分というのが何十年も有効になるという中では。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところで、いろいろなものがやはりあると思うので、時間の有効活用、働き方、そういったところを職員が人間らしく働ける環境を整えていく、あるいは住民サービスがよくなっていくという観点で進めていくというのは確かにいいと思うのですが、その一方で、自治体の業務というのはやはり実際に現場に行かなければならないこともあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"質問なのですけれども、２の（２）のところで、基礎自治体におけるテレワークということで、その活用と実現方法ということが特別区長会の調査研究機構で行われたということなのですが、この報告書をネットで見てみたのですけれども、百五十数ページにわたってのすごく膨大なまとめがされていまして、このテーマの提案区が品川区になっているのです。これは、品川区としてはなぜ提案区になったのか。","respondent":"黒田人事課長","answer":"品川区での業務改善プロジェクトチームとの関係ですが、昨年度の研究体制の中では、研究員の中に企画部の職員も入っておりまして、もともと業務改善につきましては、企画部を中心にいわゆるＢＰＲという手法を使って業務を棚卸しして。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"特別区長会のほうなのですけれども、そうすると、品川区が提案するということで、品川区としても検討を一緒になって行ってきたということになると思うのですが、そうすると、品川区としてそこの検討のメンバーとしては、誰が、どういう部署のどういう方が何人くらい入られて検討してきたのかということについてもお聞かせいただきたいと思います。","respondent":"黒田人事課長","answer":"今後、どのように取り組んでいくのかですが、先ほど申し上げたとおり、今のところテレワークと言ってもモバイルワークでありますとか在宅勤務だとか、様々なやり方の中で時間を有効的に使って区民サービスを向上しようというところを目的に検討しておりますので。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、これから本格的に取り組むためにチームを作って検討するという段階ではなくて、どういう可能性があるかというような段階ということで捉えていいのでしょうか。","respondent":"黒田人事課長","answer":"チームを作って検討するということではないのかですけれども、可能性を検討しておりますので、そういった意味では先ほど企画部、総務部を中心にと申し上げたとおり、昨年度、管理職を対象にモバイルワークができる端末を配布しまして。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に働き方というところも、やはり一番初めに申し上げましたように、残業をなくして人間らしい働き方ができる、区民サービスをさらに向上させていく、こういうところを目的としながら、働き方改革を進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"ちょっとこの実態を伺いたいのですけれども、平均すれば３割の方が庁舎に来ていないと、本来出勤している人が来ていない状況で、緊急事態宣言中の業務を仕切っていく中で、やはり出勤している方に多くのしわ寄せが来てしまったというような状況だったのか、いやいや、緊急事態宣言だから、やはり世の中も静かにしているので、業務自体がそれだけ減ったからできたのですということなのか、そうではなくて。","respondent":"黒田人事課長","answer":"３割ということの感想なのですけれども、職員が３人いまして、１人在宅勤務していると在宅勤務３割ですので、平均するといろいろな工夫で３割をやってきていて、当然業務のしわ寄せが行っていたというところもあるかと思いますし、逆にいろいろと新たな。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。今はコンビニなどでも発行できるような形になっておりますけれども、本当にこういうのはもっと法令の簡素化、先ほどの判こは要らないみたいな話も含めて、どんどんこういうのは電子化できて、役所に来なくても、電子窓口みたいなことで進められる手続きというようなことも今後は出ていくのだろうと思いますが、その辺についてのご見解をお伺いしたいと思います。","respondent":"黒田人事課長","answer":"先ほど申し上げましたが、特に法令で本人確認が必要でありますとか、例えば添付書類が区長名が入った公文書でなければといったところの社会的要請で、どうしても区役所で証明書をもらわなければいけないといったところで。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"私も最近銀行などは本当に窓口業務みたいなものがどんどんスマホでオンライン化されて、もう窓口など要らなくなって、支店もどんどんなくなっていく方向ですけれども、そういう中で、一概にそういった民間企業と行政は比較はできないでしょうけれども、そういう技術の進展とともに社会的ないろいろな通信技術のインフラが進むとともに、ＩＣＴでできる効率化から進めていただきたいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"もっと言うと、そういうのをやると、例えば簡単に言うと１人１つのテーブルが要るのかというのまで、そうするとこのフロアの在り方とかいろいろなところまで入ってくると思うのです。それはしようがないから。そういうことも含めていろいろな方法を考えていくというのは、さっき企画部とやっていると言ったけれども、そういうところまで踏み込んで検討しているのかどうかだけ教えてほしいと思う。","respondent":"黒田人事課長","answer":"この場合は、持っている資料については全て共有できるように電子化してあって、どこからでもアクセスできるといった環境面のところも必要ですし、ご質問の中にありましたが、その職員がいないと事前の相談に乗れないというようなところについては、いわゆるその職員のノウハウ。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お願いだけしておきます。だから、それは若い頃はみんないろいろな経験をしてもらって、いろいろな形で動いてもらっていく。そこら辺のところをやはりよく考えていただきたいと思うのだけれども、そこら辺まで突っ込んでやってくださいというのは要望だけにします。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ですから、今後そういう検討を進めていく中で、例えば部課長が在宅勤務をされているとき、例えばオンラインでやり取りができるような、やはり書面というのは一方的なやり取りですから、こういう相談をして、またニュアンスが届かないような相談もあるわけで、それに対して議会が、こちらの問題もありますけれども、それをみんなが共有するような、共有する事項もあれば共有しない事項も当然あるわけで。","respondent":"黒田人事課長","answer":"今後実際に来られないような状況があるならばというところでは、これはウェブ会議のような仕組みはありませんでしたが、このコロナを機に、いわゆるオンラインで会議ができるような仕組みも一部導入しているというところがございまして。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ここで課題として挙げられているところ、そのとおりだと思います。難しいと思います。そういう意味でも、ただ課題ですから、さっき言った秘匿性であるとか脆弱性であるとか、そういったものは必ずクリアできると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはりこの改善の中に業務の効率化というのも入って、その前提に、やはり組織内風土の意識の改善ということが、効率化する上では大きなファクターになってくると思うのですけれども、先ほど来のこの資料を頂いた部分の３つの課題がありましたが、それをやはり解決するためにも、やはり組織内風土の改善が必要だと思うのですけれども、それについて今後の見通し。","respondent":"黒田人事課長","answer":"組織内風土の意識の改善というところでは、先ほども出ましたけれども、昨年度まで取り組んでおりました、業務改善のプロジェクトチームについては庁内横断型というところで、各職場から職員に手挙げで出ていただりした中では、やはり聞き及んだところでは活発な意見が出て。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"そこもやはり改善の中の一つの要素でありますが、区から発表される冊子に、コンペか何かをやっていてということで、各セクションの若手の職員が皆さんテーマを決めて、解決に向けて話し合いをされているというのは、今、課長がお話になったことも十分認識をしているところではありますけれども、その組織内風土をさらに新しい時代に沿ったものに変えていくには、やはり若手の人材育成の上で、今後の世の中。","respondent":"黒田人事課長","answer":"今年度はちょっとコロナの関係もありまして実施できていないのですが、昨年度まではいわゆる政策提案も出していただいて、いろいろと自分のアイデアを区政に活かすというような制度も運用してまいりましたので、そういった中で。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781582?Template=document&Id=6094#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":27879,"voices":44}},{"id":"r02-20200821-18","meetingId":"r02-cm08","date":"2020年8月21日","dateIso":"2020-08-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問","question":"３番のしながわ文化プログラム事業助成についてなのですけれども、先ほど、口頭で５事業のご説明があったのですけれども、どうして説明資料として出されなかったのか。外部委員の採択事業ということだったのですけれども、ほかに応募されて採択されなかった事業というものが、どういったものがあったのかといったことも伺いたかったと思ったので、その辺に関してお知らせください。","respondent":"古巻文化観光課長","answer":"今、口頭で事業の説明をさせていただきました文化プログラムの事業助成ですけれども、少し分量が多くなってしまうことを気にしまして、簡略な資料として使わせていただいて、口頭でご説明をするという形にしたのですけれども、そういう意味では。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません。私が勉強不足で、このクリエイティブ・チャレンジとリンクと、２種類とかはよく分からなかったのですけれども、せっかく採択されてこれから行われる事業ですので、次回から、そういった資料提供も充実させていただければと思います。要望でおしまいにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"渡部副委員長","kind":"確認","question":"今の、クリエイティブ・リンクのところなのですけれども、僕も確認をしていたのですが、事業としては去年の事業で、昨年度のうちに決定が出されていて、これは昨年度の区民委員会かオリンピック・パラリンピック推進特別委員会で、この辺の事業の説明ですとか採択の決定は、どこかでこれは報告があったのでしょうか。それだけ確認したいのですけれども。","respondent":"古巻文化観光課長","answer":"事業は今年度予算なのですけれども、４月からの開始ということがありましたので、ある程度、予算のめどがついた段階で申請を開始しています。","id":"exchange-003"},{"speaker":"渡部副委員長","kind":"質問","question":"てっきり、これはもう報告がどこかで終わっているのかなと僕も思ったのですが、そうしたら、どういうもので、どういうふうに決定されたかぐらいの資料は、後日配付で結構ですので、お願いできますでしょうか。委員長、それでいいですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、中止になってしまったところですとか、例えば、そこに向けて予定していた準備の費用ですとか、あるいは、予定されていたチケット収入のようなものの損失があるのではないかと思うのですけれども、その辺について、どのようになっているのかと言いますか、どういうものが発生していて、それに対する手立てのような、補償ですとか、そういったものというのはどういう考え方になっているのか。","respondent":"古巻文化観光課長","answer":"開催をするという部分については、ほぼ、この秋以降の日程で、現状であれば、しっかり感染症対策を施した上で開催が可能であろうというものについて、舞台芸術等が難しいところもありますので、野外であったり、展示ということで。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。その上で、具体的に２点、要望とともに伺いたいのです。１点目ですけれども、文化ホールなどの貸出し施設なのですが、その中に、利用定員の制限というのがあるのですけれども、定員制限に応じて、例えば使用料を引き下げるとか、そういうような対応というのも必要なのではないかと思うのですけれども、いかがでしょうか。今、実際の対応はどうなっているのか。","respondent":"古巻文化観光課長","answer":"出演者や講師への謝礼等の補償ですけれども、特に、キャンセルしたコンサート事業などですと、例えば、指揮者の方への謝礼については、ゼロということではなくて、１００％ではないにしてもなるべくお支払いするなど、区主催の事業については、精算の中で。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"ホールの貸出しの使用料の減額についてもそうなのですけれども、区としてできることというのは積極的にやっていただきたいと言いますか、実際に文化やスポーツを担っている、それをなりわいにしている方々というのは、本当に大変な状況に追い込まれていますので、国や都の補償制度も併せてというのはもちろん当然のことなのですが、やはり区としてそういったものを盛り上げていく、文化の火を。","respondent":"古巻文化観光課長","answer":"先ほど申し上げたとおりで、今、特につけ加えることはございません。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"しながわ文化プログラム事業助成で、このセミナーシリーズというのが書かれておりますけれども、第１回が令和２年７月２９日、オンラインで実施済みということなのですけれども、それ以降、第２回以降の情報はホームページなどで掲載をされているのですか。その周知状況をお聞かせください。","respondent":"古巻文化観光課長","answer":"２回目は、一昨日開催いたしましたけれども、３回目以降については、これから日程や内容を事業者と調整していくところですので、まだ決まっていないというような状況です。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"このセミナーシリーズは、ＳＨＩＮＡＧＡＷＡ ＣＲＥＡＴＩＶＥ ＳＵＰＰＯＲＴという特別なサイトに載っているもので、２０１９年１２月５日とかにやられているものと同じような形で今後やっていくのでしょうかということと、オンラインで開催するということで、これは、一般の方というのは見ることというのはできないのでしょうか。","respondent":"古巻文化観光課長","answer":"特段、何か特殊なソフトが要るわけではなく、Ｚｏｏｍというオンラインの会議をするためのソフトを使ってやっておりますので、そちらが使える環境であればアクセスは可能だというふうに認識をしております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"ご説明ありがとうございました。しながわ文化プログラムの品川区民芸術祭についてお伺いをしたいと思います。アーティスト展のほうにはこのしながわ文化プログラムのロゴが入っていなかったのですけれども、たまたま入る余地がなかったのか、しながわ文化プログラムの位置づけがあるので、そこはどうなのかなというふうに思ったのですけれども、その２点をお伺いしたいと思います。","respondent":"古巻文化観光課長","answer":"ティーンズコンサートという形で１０月１１日に予定されていたものですが、これは、お子さんが出たりするものもございましたので、そういった観点からの中止というふうに認識をしています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、プロのアーティストでも、無観客での、オンラインでの配信が非常に多くなってきているということで、様子、状況を見ながら開催されておりますけれども、今後の状況判断が必要かと思いますが、例えば、品川区における、このきゅりあんを使った芸術推進というところ、文化プログラムの推進の１つとして、オンライン配信というようなやり方が、今後、何かあるのか。","respondent":"古巻文化観光課長","answer":"このあたりは、すぐにどうこうというのは、なかなか難しいのですけれども、発表の場というものを、オンラインのことも含めまして、しっかりと考えて、なるべく発表の場が閉ざされることのないような今後の進め方をしっかり検討してまいりたいというふうに思います。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。本当に、この見極めが難しいところかと思います。とにかく、感染拡大防止というところも一番大事であります。来年の東京２０２０大会も、どういうふうな形になるのかということも未決定のままではありますけれども、しっかり品川区としてはできるところを、また、お声を聞いていただきながら、ぜひ取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"癒されている。そういう意味では、区においても同じことが考えられるし、東京都でも、たしか何かいろいろなアーティストの方をネット上で支援するというのがありましたよね。それは、当然、出展していただいた方のご了解などがないといけないと思うのですけれども。加えて、品川アーティスト展ですね。作品の放映とか、その辺について、重ねて考え方を教えてください。","respondent":"古巻文化観光課長","answer":"アーティスト展に関しては、ステージのＹｏｕＴｕｂｅライブ配信も予定しているので、一部、オンライン的なものも取り上げながら進めるというようなことも、試行的なところはありますけれども、やっておりますので、そのあたり、さらに効果を見極めまして。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"品川アーティスト展２０２０については、私も今チラシを見て、ライブ配信があることを確認しました。要はこういうことですよね。来年の東京２０２０大会がどうなるかというのは、非常に悩ましい、センシティブなところである中で、それはあくまでも通過点で、大会の有無に関わらず、品川区の文化をしっかりと醸成していくということが、品川区にとってみれば主目的かと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"東京２０２０大会の新競技日程","agenda":"東京２０２０大会の新競技日程","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"新しい競技日程の報告ということなので、あえて伺いたいと思うのです。来年に延期された競技日程なのですけれども、基本的に同一日程を維持という内容だと思うのですね。伺いたいのは、この立候補ファイルの記述ですね。そして、この猛暑、酷暑時期での開催日程がまた今発表されましたけれども、区としてはどういうふうに考えているのか、ここは伺いたいなと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"立候補ファイルの記載についての区の見解ですが、その当時の立候補ファイルがどのように記載されているかということは、私どもは意見する立場ではございませんでしたので、今、意見として区として言うことはできかねます。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区だってアスリートファーストということを言っているわけですから。では、質問を変えますけれども、私たちが現実に今日も体感しているこの猛暑、酷暑の時期での開催日程について、開催について、このアスリートファーストという立場を掲げる区としてどのようにお感じになっているのか、そのお考えだけ聞かせていただきたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区としては、この時期に行われるということを大前提の上に、アスリートファーストをしっかり体現できるような準備をしていくです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"意見","question":"もちろん、品川区が意見するべき立場ではないということは分かりますけれども、ただ、それでも、やはり品川区として選手のことを第一に考えるのであれば、そして、最高の大会を作っていく、目指していくというのであれば、やはり必要な考えを表明すべきだし、それをしっかりと発信していくべきだというふうに私は思います。非常に残念です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"西村委員","kind":"質問","question":"改めて伺わせてください。不勉強で申し訳ないのですが、今年、梅雨明けが８月１日だったと思うのですけれども、私も体感しながら、来年こんな感じなのかなと、この日程を見ながら、この日程で進んだ場合、どうなるかなというふうにイメージしていたのですが、これは、梅雨が同じぐらい長引いた場合、スケジュールがどういうふうになるか、今、もし決まっているところがあれば教えていただけますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"梅雨が長引いた場合にはというご質問ですが、特段、それで日程が変更になるとか、そういったことは聞いたことはございません。そのままの日程で行うようになります。","id":"exchange-018"},{"speaker":"西村委員","kind":"質問","question":"屋外でも、雨の中のスポーツであったり、そういうことになるということでよろしいですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば、いわゆる普通の雨だったらそのままやりますよ、ただし、雷があった場合には、そこで一時中断、それが明けたらまた始めるですとか、そういった競技の中のルールがあると思いますので、それに従っての判断になるのかなというふうに認識しております。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"ただいま、日程の公表のお知らせをいただきました。これは、ＩＯＣが決定をすることですので、品川区ではなかなかこの日程などについて言えないというところですけれども、現状、東京都等を通じて、この大会開催に向けてどういう検討が行われていて、何か教えていただけることがあればお知らせいただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういったことに関して、後ほどご報告もするのですけれども、公式練習会場として品川区でも提供するところがあるですとか、聖火リレーのときも一定程度の会議室を諸室としてお貸しするなどという予定がございましたので、そういったところの調整等を、今、しています。","id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"意見","question":"ＬＩＮＥスタンプについてなのですけれども、予算がどうなっているのか、お知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これは、今、決定金額については持ち合わせはないのですが、全体の機運醸成・啓発の予算から出しております。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"去年からＬＩＮＥスタンプがあるということだったのですけれども、ごめんなさい、存じていませんでした。ＬＩＮＥスタンプのイラストが変わったのですか。それとも、追加がされたのか。そういった場合というのは、新しいデザイナーが入ってということになるのかと思うのですけれども、その辺についてお知らせいただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"おっしゃるとおり、今までのキャラクターの絵をもとに、それを崩した、少し緩い感じにデザイナーに描き直していただいて、言葉等を追加して作ったものです。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"去年のＬＩＮＥスタンプの金額よりも上下が多少あるということですか。そこの予算の内訳をお知らせいただければと思います。今、分かる範囲でいいです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"昨年度なのですが、最初に作ったときは、これはほぼ職員で作ったので、ほぼ費用がかかっていないです。今年度に関しましては、絵柄を少し変えたりしているので、デザイナーさんに入っていただいているので、金額はかかっています。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"ちなみに、このＬＩＮＥスタンプなのですけれども、現状、第１弾はどのくらいダウンロードされているのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"第１弾のほうは販売数が１００個です。","id":"exchange-024"},{"speaker":"つる委員","kind":"提案","question":"ＬＩＮＥスタンプ、これは何年か前に当委員会で提案させていただいて、作成していただいて、当委員会に所属されている方で知らない人がいるというのは、逆にびっくりなのですね。皮肉ではないですけれども、そういう人もいるということで、使ってもらうというか、第１弾ができたときも伝えたのですけれども、オリンピックの周知だけではないですよね。そこのところだけ考え方を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ということで、今までどおりの１２０円をお支払いいただいて買っていただくということでご理解いただきたいと思います。","id":"exchange-025"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ぜひ、品川区のほうで著作権がもらえるような契約で物事を進めていただいて。それで、もう広く、いいのではないですか。例えば、第１弾を買ってしまった人がいるけれども、好きな人はダウンロードしてくださいとか。これはもう聞き流していただきたいのですけれども、せっかくこういうキャラクターがあるわけですから、何かゲームとか作ってほしいなと。独り言なのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ですので、私どもも、例えば何かに参加してくれた人にプレゼントするというのをやりたいのですけれども、今、ハードルが高くてなかなかできないでいるところです。","id":"exchange-026"},{"speaker":"新妻委員","kind":"意見","question":"前回の委員会でご報告いただきました、１年前どうしようか会議が７月２３日に放映されたと思いますので、その視聴状況ですとか、その後のアーカイブの状況ですとか、反響をぜひご報告いただけたらと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"前回ご報告申し上げました、１年前どうしようか会議です。こちらのほうなのですが、リアルタイムで見てくださった方は最大で１５６人とか、少し寂しい状況ではございました。","id":"exchange-027"},{"speaker":"新妻委員","kind":"質問","question":"私も１５６人分の１として視聴させていただきました。シミスくんがこういう方なのだと分かったりとか、あとは、とても良かったのは、やはり、しな助のお二人がすごく良かったなと。今後また、何か機会があればと思いますが、継続してやっていくことというのはいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、このような状況で、なかなか難しいところもあるかもしれないですし、先ほど申し上げたような、ネットでやるメリットというのもまた感じているところです。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706411?Template=document&Id=6580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":23793,"voices":85}},{"id":"r02-20200824-10","meetingId":"r02-cm08","date":"2020年8月24日","dateIso":"2020-08-24","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"の１、「令和３度予算（議会費）について」","agenda":"の１、「令和３度予算（議会費）について」","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"７つ項目を挙げさせていただきました。次年度につきましても、第三者機関設置が必要ということで、今、政務活動費に関しては、それぞれ適正に運用されていると思いますが、さらなるチェック体制ですとか、使途について検討するための第三者機関設置を求めます。４番、防災備蓄の確保。メール等でやっていただいておりますけれども、ＬＩＮＥも入れていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"大倉委員","kind":"提案","question":"議会棟トイレにペーパータオルを設置するということで、衛生面に気を遣って、今、こういうご時世なので、ペーパータオルを設置してはいかがでしょうかということで提案させていただきました。４、議会図書室の機能の強化ということで、オンラインとかでも検索ができるようにということで考えていたのですが、現在、外部から検索もできるということだったので、これはこれで結構ですということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"こんの委員","kind":"質問・要望","question":"うちの会派からは３つ要望させていただきました。３点目、議場のコロナ感染防止対策についてということで、これはちょっと文字になっていないですが、および委員会室も含めて、いわゆる飛沫防止のための議員席の間、アクリル板などを設置、フェイスシールドなどの備えというところも必要ではないでしょうかというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"共産党としては、５項目、そして１つ追加したいと思うのですけれども、１点目は、海外調査は予算計上しないこと。４番目は、本会議及び委員会の議事録作成ですけれども、特に最終本会議における討論作成に間に合うように関係予算を増額していただきたいということです。５番目は、本会議と同じく、委員会もインターネット中継ができるように必要な整備をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"これは総括質疑や意見表明者にも同様な対応をしていただきたいと思います。これは部屋の広さに応じて換気扇数の確保はお願いしたいということですが、扇風機で現在やっているところもあるのですが、やっぱり扇風機は逆に飛沫のものがそのまま一定の場所に、万が一、ある特定の場所で集中的に直接飛沫を受けることもあるので、できれば換気のほうがいいのではないかと思いまして、提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"提案","question":"自民の提案の件で、海外調査費と、それから特別、議運の視察経費というのが今回提案されていますが、私は、こういうものは有志で行かれて、現在、政務活動費というものがそれぞれ出されているのですから、それを使用するというのが本来ではないかというふうに思います。それをさらに議会で備蓄するというのは、どうなのかなという疑問を感じますので、それだけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言ということなので、海外調査について、今もご意見がありましたが、議長がまとめられる際には、ぜひ各会派共通、また共通できるものとして整理していただきたいということだけ意見を添えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"それも１つの方法だと思います。ただ、我々が議会費の予算要望をしている背景には、今までの海外調査の実績がありまして、経費のことだけ言われるのかもしれないのですが、我々は、今まで行ってきた海外調査の成果をしっかり見ていただきたいと思います。防災備蓄についても、必要最小限のものはやはり議会で用意をする必要があるのではないかということで要望しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合議会の報告について","agenda":"東京都後期高齢者医療広域連合議会の報告について","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"７月３０日の１４時から、東京都後期高齢者医療広域連合議会の第１回臨時会が開かれました。本当は４月に開く予定だったらしいのですが、緊急事態宣言のため時期がずれたということになっております。１点目としまして、議長選挙をやりました。支給対象は、被保険者２４万人のうちの約１％、約２,４００人を想定しているということです。内容としましては、これもそのまま全会一致で賛成しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"提案","question":"一言、意見だけ述べさせていただきたいのですけれども、やはりコロナ禍の下、区民生活が厳しくなる中、傷病手当が全会一致で決まったということはよかったと考えています。その上で、やはり保険料の引き下げ、私は足を踏み入れるべきだと考えています。ぜひ今後、広域連合議会が開かれるかと思いますけれども、そういった趣旨のご発言や提案をしていただけたらと要望しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今回は、当然内容が違うので、その話は一切出ておりませんし、保険料につきましては、品川区議会としての問題もありますので、その辺を踏まえた上での対応になると思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"石田（秀）委員長","kind":"質問","question":"私から１点だけ。よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"提案","question":"これはフェイスシールドが巷に大分普及されてきまして、販売もされてきました。そのときに、そこの議会では、個人情報と人権保護のために、氏名、性別、年齢は非公表とする運用を議会で申し合わせ事項にしたということなのですが、この辺について、議運で審議されるのか、議長のほうでお決めいただくのか、その辺を一応提案させていただきたいと思います。","respondent":"渡辺議長","answer":"もちろん今までも検討はしているのですが、フェイスシールドだけの場合の効用ですとか、まだ情報を全て把握できていないので、少しお時間をください。２つ目、議員の感染時、これもかねてから検討しております。ケース・バイ・ケースによるところが多々ある。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5374#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":9512,"voices":37}}]);
